  for (var i=-6;i<12;i++){ ctx.beginPath(); var x=i*12; ctx.moveTo(x,2); ctx.lineTo(x+6,2); ctx.lineTo(x+12,10); ctx.lineTo(x+6,10); ctx.closePath(); ctx.fill(); }
  ctx.restore();
  // Kabin
