  ctx.beginPath(); ctx.moveTo(-44,-50); ctx.lineTo(-44,-46); ctx.moveTo(42,-50); ctx.lineTo(42,-46); ctx.stroke();
  ctx.fillStyle = c2; ctx.beginPath(); ctx.roundRect(-20,-56,26,6,2); ctx.fill(); // yük
  // Yedek lastik arkada
