function drawSportsCar(ctx, def, v, thr, t) {
  const sa = v.suspAnim || [0,0];
  _drawSusp(ctx, -44, 0, -44, 13*(1-(sa[0]||0)*0.25), sa[0]||0);
  _drawSusp(ctx,  44, 0,  44, 13*(1-(sa[1]||0)*0.25), sa[1]||0);
  // Shadow
  ctx.save(); ctx.globalAlpha=0.15; ctx.fillStyle='#000';
  ctx.beginPath(); ctx.ellipse(0, 22, 60, 7, 0, 0, Math.PI*2); ctx.fill(); ctx.restore();
  // Diffuser
  ctx.fillStyle = '#111';
  ctx.beginPath(); ctx.moveTo(-60, 8); ctx.lineTo(-54, 16); ctx.lineTo(54, 16); ctx.lineTo(60, 8); ctx.closePath(); ctx.fill();
  // Body wide coupe
  _carPaint(ctx, 0, -12, 118, 36, def.color || '#2980b9');
  // Sleek roofline
  ctx.fillStyle = def.color||'#2980b9';
  ctx.beginPath(); ctx.moveTo(-38, -16); ctx.lineTo(-28, -44); ctx.lineTo(18, -44); ctx.lineTo(32, -16); ctx.closePath(); ctx.fill();
  // Gradient overlay on roof
  const roofG = ctx.createLinearGradient(-38,-44,32,-16);
  roofG.addColorStop(0,'rgba(255,255,255,0.18)'); roofG.addColorStop(1,'rgba(0,0,0,0.12)');
  ctx.fillStyle = roofG;
  ctx.beginPath(); ctx.moveTo(-38, -16); ctx.lineTo(-28, -44); ctx.lineTo(18, -44); ctx.lineTo(32, -16); ctx.closePath(); ctx.fill();
  // Windows
  ctx.fillStyle = 'rgba(100,180,255,0.38)';
  ctx.beginPath(); ctx.moveTo(-32, -20); ctx.lineTo(-22, -40); ctx.lineTo(14, -40); ctx.lineTo(26, -20); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-2, -20); ctx.lineTo(0, -40); ctx.stroke(); // B pillar
  // Hood (long, sloped)
  ctx.fillStyle = 'rgba(0,0,0,0.1)'; ctx.fillRect(22, -22, 38, 24);
  ctx.fillStyle = def.color||'#2980b9';
  ctx.beginPath(); ctx.moveTo(32, -18); ctx.lineTo(54, -22); ctx.lineTo(62, -8); ctx.lineTo(58, 8); ctx.lineTo(32, 8); ctx.closePath(); ctx.fill();
  const hoodG = ctx.createLinearGradient(32,-22,58,8);
  hoodG.addColorStop(0,'rgba(255,255,255,0.2)'); hoodG.addColorStop(1,'rgba(0,0,0,0.15)');
  ctx.fillStyle = hoodG;
  ctx.beginPath(); ctx.moveTo(32, -18); ctx.lineTo(54, -22); ctx.lineTo(62, -8); ctx.lineTo(58, 8); ctx.lineTo(32, 8); ctx.closePath(); ctx.fill();
  // Hood vents
  for(let hv=0; hv<2; hv++) {
    ctx.fillStyle='#1a1a1a'; ctx.beginPath(); ctx.roundRect(38+hv*12, -18, 8, 6, 2); ctx.fill();
  }
  // Front fascia
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.roundRect(58, -16, 8, 26, 2); ctx.fill();
  // LED headlight strip
  ctx.fillStyle = 'rgba(220,240,255,0.85)'; ctx.fillRect(58, -18, 8, 3);
  _headlight(ctx, 60, -10, true, 7); _headlight(ctx, 60, 2, true, 6);
  // Front splitter
  ctx.fillStyle = '#0a0a0a'; ctx.fillRect(56, 6, 14, 4);
  // Side air intake (scoops)
  ctx.fillStyle = '#1a1a1a';
  ctx.beginPath(); ctx.moveTo(-22, -4); ctx.lineTo(-30, -10); ctx.lineTo(-30, 2); ctx.lineTo(-22, 4); ctx.closePath(); ctx.fill();
  // Rear deck
  ctx.fillStyle = '#111'; ctx.fillRect(-60, -16, 18, 28);
  _taillight(ctx, -62, -14, 9); _taillight(ctx, -62, 0, 8);
  // Taillamp strip
  ctx.fillStyle = 'rgba(255,20,20,0.5)'; ctx.fillRect(-62, -6, 6, 3);
  // Quad exhaust (center-mounted)
  ctx.fillStyle = '#444'; ctx.fillRect(-16, 8, 8, 6); ctx.fillRect(-4, 8, 8, 6);
  _exhaustFlame(ctx, -12, 11, thr, t, 0.8);
  _exhaustFlame(ctx, 0, 11, thr, t, 0.8);
  // Side rocker panel
  ctx.fillStyle = '#0d0d0d'; ctx.fillRect(-58, 6, 116, 5);
  // Door line crease
  ctx.strokeStyle = 'rgba(255,255,255,0.12)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-46, -16); ctx.lineTo(32, -16); ctx.stroke();
  _neonStrip(ctx, -56, 12, 112, def.color||'#2980b9');
  // --- Additive polish: windshield glare, headlight bezels, chrome tips, idle glint ---
  ctx.save();
  // Windshield glare streak across the raked glass
  ctx.fillStyle = 'rgba(255,255,255,0.24)';
  ctx.beginPath(); ctx.moveTo(-20,-38); ctx.lineTo(-6,-38); ctx.lineTo(-14,-22); ctx.lineTo(-24,-22); ctx.closePath(); ctx.fill();
  // Headlight glass bezels
  ctx.strokeStyle = 'rgba(220,220,200,0.6)'; ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.arc(60,-10,7,0,Math.PI*2); ctx.stroke();
  ctx.beginPath(); ctx.arc(60,2,6,0,Math.PI*2); ctx.stroke();
  // Chrome exhaust tips (center)
  ctx.fillStyle = '#ccc';
  ctx.beginPath(); ctx.ellipse(-12,8,3,1.6,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(0,8,3,1.6,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle = '#222';
  ctx.beginPath(); ctx.ellipse(-12,8,1.6,0.9,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(0,8,1.6,0.9,0,0,Math.PI*2); ctx.fill();
  // Sweeping body specular glint (idle life)
  var scgx = Math.sin(t*1.6)*24;
  ctx.fillStyle = 'rgba(255,255,255,0.16)';
  ctx.beginPath(); ctx.ellipse(scgx,-12,11,3.5,-0.28,0,Math.PI*2); ctx.fill();
  ctx.restore();
}

