function drawFormula(ctx, def, v, thr, t) {
  // === SIFIRDAN ÇİZİM — gerçek Formula 1 silüeti (burun sağda/önde) ===
  var c1 = def.color || '#cc0000', c2 = def.color2 || '#ffffff';
  var sa = v.suspAnim || [0,0];

  // Push-rod süspansiyon + yaylar
  ctx.strokeStyle = '#3a3a3a'; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(-50, 2); ctx.lineTo(-30, -8); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(50, 2); ctx.lineTo(30, -8); ctx.stroke();
  _drawSusp(ctx, -50, 2, -50, 10*(1-(sa[0]||0)*0.35), sa[0]||0);
  _drawSusp(ctx,  50, 2,  50, 10*(1-(sa[1]||0)*0.35), sa[1]||0);

  // Zemin plakası / kaporta tabanı
  ctx.fillStyle = '#0a0a0a';
  ctx.beginPath(); ctx.moveTo(-60, 6); ctx.lineTo(-56, 13); ctx.lineTo(70, 13); ctx.lineTo(74, 6); ctx.closePath(); ctx.fill();
  // Arka difüzör dilimleri (sol uç)
  ctx.fillStyle = '#151515';
  for (var d=0; d<6; d++){ ctx.fillRect(-60 + d*7, 7, 5, 7); }

  // Motor kapağı / gövde — merkezde yüksek, arkaya sivrilen; metalik gradyan
  var bodyG = ctx.createLinearGradient(0, -12, 0, 10);
  bodyG.addColorStop(0, _shade(c1, 0.4)); bodyG.addColorStop(0.5, c1); bodyG.addColorStop(1, _shade(c1, -0.4));
  ctx.fillStyle = bodyG;
  ctx.beginPath();
  ctx.moveTo(-58, 6);
  ctx.lineTo(-40, -6);
  ctx.quadraticCurveTo(-20, -16, -6, -16);
  ctx.lineTo(10, -14);
  ctx.quadraticCurveTo(40, -10, 74, -4);
  ctx.lineTo(74, 6);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = _shade(c1, 0.55); ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.moveTo(-38,-6); ctx.quadraticCurveTo(-20,-15,-6,-15); ctx.stroke();

  // Sidepod (radyatör kutusu) — beyaz aksan + koyu giriş
  ctx.fillStyle = c2;
  ctx.beginPath(); ctx.moveTo(-30, -6); ctx.lineTo(28, -6); ctx.quadraticCurveTo(34, 0, 20, 6); ctx.lineTo(-30, 6); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#0a0a0a';
  ctx.beginPath(); ctx.moveTo(24, -5); ctx.lineTo(30, -1); ctx.lineTo(22, 4); ctx.closePath(); ctx.fill();
  ctx.fillStyle = c1; ctx.fillRect(-28, -6, 52, 2);

  // Airbox / roll hoop (kokpit arkası hava girişi)
  ctx.fillStyle = _shade(c1, -0.25);
  ctx.beginPath(); ctx.moveTo(-8, -14); ctx.lineTo(2, -26); ctx.lineTo(8, -14); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(1, -18, 3, 0, Math.PI*2); ctx.fill();

  // Uzun sivri burun (önde/sağda, hafif kalkık)
  ctx.fillStyle = c1;
  ctx.beginPath(); ctx.moveTo(60, -6); ctx.lineTo(96, -3); ctx.quadraticCurveTo(100, 0, 96, 3); ctx.lineTo(60, 6); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.25)';
  ctx.beginPath(); ctx.moveTo(62, -5); ctx.lineTo(94, -2); ctx.lineTo(62, -1); ctx.closePath(); ctx.fill();
  ctx.fillStyle = c2; ctx.fillRect(66, -1, 24, 2);

  // Ön kanat (çok elemanlı) + endplate
  ctx.fillStyle = '#111';
  ctx.fillRect(78, 4, 24, 3);
  ctx.fillRect(82, 7, 18, 2.5);
  ctx.fillRect(84, 9.5, 12, 2);
  ctx.fillStyle = c1;
  ctx.beginPath(); ctx.roundRect(99, -2, 5, 16, 1); ctx.fill();

  // Kokpit + pilot kaskı
  ctx.fillStyle = '#0a0a0a'; ctx.beginPath(); ctx.roundRect(-8, -18, 26, 14, 5); ctx.fill();
  ctx.fillStyle = c2; ctx.beginPath(); ctx.arc(6, -14, 8, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = c1; ctx.beginPath(); ctx.arc(6, -14, 8, Math.PI, 0); ctx.fill();
  ctx.fillStyle = '#111'; ctx.fillRect(6, -16, 9, 4);
  ctx.fillStyle = 'rgba(120,200,255,0.65)'; ctx.fillRect(7, -15, 7, 2);

  // Halo (kokpit koruma barı)
  ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = 3.5;
  ctx.beginPath(); ctx.arc(6, -12, 13, Math.PI+0.25, -0.25); ctx.stroke();
  ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(19, -12); ctx.lineTo(24, -6); ctx.stroke();

  // Arka kanat (yüksek, çok elemanlı) + pylon + endplate
  ctx.fillStyle = '#333'; ctx.fillRect(-46, -34, 4, 30);
  ctx.fillStyle = '#111';
  ctx.fillRect(-64, -40, 40, 6);
  ctx.fillRect(-62, -32, 34, 4);
  ctx.fillStyle = c1;
  ctx.beginPath(); ctx.roundRect(-68, -44, 6, 34, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-30, -44, 6, 34, 2); ctx.fill();
  ctx.fillStyle = c2; ctx.fillRect(-64, -40, 40, 2);

  // Egzoz (üflemeli difüzör) + alev
  ctx.fillStyle = '#555'; ctx.fillRect(-58, 2, 7, 5);
  _exhaustFlame(ctx, -56, 4, thr, t, 0.9);
}

