function drawDuneBuggy(ctx, def, v, thr, t) {
  const sa = v.suspAnim || [0,0];
  _drawSusp(ctx, -42, 0, -42, 22*(1-(sa[0]||0)*0.3), sa[0]||0);
  _drawSusp(ctx,  42, 0,  42, 22*(1-(sa[1]||0)*0.3), sa[1]||0);
  // Roll cage (exposed chrome tubes)
  ctx.strokeStyle = '#888'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(-34, 8); ctx.lineTo(-34, -42); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(16, 8); ctx.lineTo(16, -42); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-34, -42); ctx.lineTo(16, -42); ctx.stroke(); // top bar
  // X-brace
  ctx.lineWidth = 2.5; ctx.strokeStyle = '#666';
  ctx.beginPath(); ctx.moveTo(-34, 8); ctx.lineTo(16, -42); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(16, 8); ctx.lineTo(-34, -42); ctx.stroke();
  // Rear cage
  ctx.strokeStyle = '#888'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(-50, 8); ctx.lineTo(-50, -26); ctx.lineTo(-34, -42); ctx.stroke();
  // Front engine
  ctx.fillStyle = '#1e1e1e'; ctx.beginPath(); ctx.roundRect(18, -16, 34, 28, 4); ctx.fill();
  // Cooling fins on engine
  ctx.strokeStyle = '#2a2a2a'; ctx.lineWidth = 1;
  for(let ef=0; ef<6; ef++) { ctx.beginPath(); ctx.moveTo(20, -12+ef*5); ctx.lineTo(50, -12+ef*5); ctx.stroke(); }
  // Carburettor / air filter
  ctx.fillStyle = '#333'; ctx.beginPath(); ctx.arc(34, -18, 8, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#444'; ctx.beginPath(); ctx.arc(34, -18, 5, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#555'; ctx.beginPath(); ctx.arc(34, -18, 3, 0, Math.PI*2); ctx.fill();
  // Seat
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.roundRect(-28, -38, 36, 12, 4); ctx.fill();
  ctx.fillStyle = '#1e1e1e'; ctx.beginPath(); ctx.roundRect(-26, -36, 32, 10, 3); ctx.fill();
  // Headrest
  ctx.fillStyle = def.color||'#16a085'; ctx.beginPath(); ctx.roundRect(-20, -48, 16, 10, 3); ctx.fill();
  // Steering wheel (exposed)
  ctx.strokeStyle = '#555'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.arc(12, -26, 10, 0, Math.PI*2); ctx.stroke();
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(12, -36); ctx.lineTo(12, -16); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(2, -26); ctx.lineTo(22, -26); ctx.stroke();
  // Side panels (minimal)
  ctx.fillStyle = def.color || '#16a085'; ctx.globalAlpha = 0.8;
  ctx.beginPath(); ctx.roundRect(-52, -8, 32, 22, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(16, -8, 38, 22, 3); ctx.fill();
  ctx.globalAlpha = 1;
  // Numbers on side
  ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.font = 'bold 10px Arial'; ctx.textAlign = 'center';
  ctx.textBaseline = 'middle'; ctx.fillText('32', -36, 4);
  // Front light bar
  ctx.fillStyle = '#1a1a1a'; ctx.beginPath(); ctx.roundRect(48, -28, 14, 20, 3); ctx.fill();
  _headlight(ctx, 54, -22, true, 7); _headlight(ctx, 54, -10, true, 6);
  // Rear lights
  _taillight(ctx, -54, -10, 8);
  // Dual rear exhausts (up-swept)
  ctx.save(); ctx.strokeStyle = '#555'; ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(-46, 8); ctx.bezierCurveTo(-48, -4, -52, -18, -50, -28); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-50, 8); ctx.bezierCurveTo(-54, -2, -56, -16, -54, -26); ctx.stroke();
  ctx.restore();
  _chrome(ctx, -52, -30, 8, 8); _chrome(ctx, -56, -28, 8, 8);
  _exhaustFlame(ctx, -54, -22, thr, t, 0.85);
  // Flagpole with flag
  ctx.strokeStyle = '#888'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-40, -42); ctx.lineTo(-40, -62); ctx.stroke();
  ctx.fillStyle = def.color||'#16a085';
  ctx.beginPath(); ctx.moveTo(-40, -62); ctx.lineTo(-24, -58); ctx.lineTo(-24, -50); ctx.lineTo(-40, -54); ctx.closePath(); ctx.fill();
  // Driver
  _driver(ctx, -6, -50, def.color||'#16a085', '#1a1a1a', t);
}

