function drawChopper(ctx, def, v, thr, t) {
  const sa = v.suspAnim || [0,0];
  _drawSusp(ctx, -34, 0, -34, 20*(1-(sa[0]||0)*0.25), sa[0]||0);
  _drawSusp(ctx,  34, 0,  34, 20*(1-(sa[1]||0)*0.25), sa[1]||0);
  // Long extended front fork
  ctx.strokeStyle = '#666'; ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(22, 2); ctx.lineTo(44, -32); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(26, 2); ctx.lineTo(48, -32); ctx.stroke();
  // Chrome fender over front
  ctx.strokeStyle = '#aaa'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(22, -8); ctx.bezierCurveTo(30, -14, 40, -12, 44, -24); ctx.stroke();
  // Frame backbone (thick chrome)
  ctx.strokeStyle = '#888'; ctx.lineWidth = 6;
  ctx.beginPath(); ctx.moveTo(-34, -4); ctx.lineTo(22, 2); ctx.stroke();
  ctx.strokeStyle = '#555'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(-34, -4); ctx.lineTo(-4, -28); ctx.lineTo(10, -22); ctx.lineTo(22, 2); ctx.stroke();
  // Engine (V-twin finned)
  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.roundRect(-8, -10, 24, 22, 3); ctx.fill();
  // V-twin jugs
  ctx.fillStyle = '#1a1a1a'; ctx.save(); ctx.translate(4, 0);
  ctx.beginPath(); ctx.roundRect(-8, -22, 10, 16, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(0, -20, 10, 14, 3); ctx.fill(); ctx.restore();
  // Cooling fins
  ctx.strokeStyle = '#2a2a2a'; ctx.lineWidth = 1;
  for(let cf=0; cf<5; cf++) {
    ctx.beginPath(); ctx.moveTo(-4, -20+cf*4); ctx.lineTo(6, -20+cf*4); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(4, -18+cf*4); ctx.lineTo(14, -18+cf*4); ctx.stroke();
  }
  // Chrome primary cover
  _chrome(ctx, 4, -4, 16, 16);
  // Gas tank (teardrop shape)
  ctx.fillStyle = def.color || '#8B0000';
  ctx.beginPath();
  ctx.moveTo(-18, -26); ctx.bezierCurveTo(-8, -38, 14, -36, 16, -26);
  ctx.bezierCurveTo(16, -18, 6, -14, -14, -16);
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.2)';
  ctx.beginPath(); ctx.ellipse(-2, -28, 10, 5, -0.3, 0, Math.PI*2); ctx.fill();
  // Flame tank decal
  ctx.fillStyle = 'rgba(255,120,0,0.6)';
  ctx.beginPath(); ctx.moveTo(-16, -20); ctx.bezierCurveTo(-10, -30, -2, -32, 4, -22);
  ctx.bezierCurveTo(0, -18, -10, -16, -16, -20); ctx.fill();
  // Seat (long low)
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.roundRect(-32, -14, 52, 10, 5); ctx.fill();
  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.roundRect(-30, -12, 48, 8, 4); ctx.fill();
  // Sissy bar
  ctx.strokeStyle = '#888'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(-32, -6); ctx.lineTo(-34, -28); ctx.lineTo(-26, -28); ctx.lineTo(-28, -6); ctx.stroke();
  // Headlight (round big)
  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.arc(46, -26, 12, 0, Math.PI*2); ctx.fill();
  _headlight(ctx, 46, -26, true, 10);
  // Chrome headlight ring
  ctx.strokeStyle = '#aaa'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(46, -26, 12, 0, Math.PI*2); ctx.stroke();
  // Dual exhaust pipes low
  ctx.save(); ctx.strokeStyle = '#666'; ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(-6, 16); ctx.bezierCurveTo(-18, 14, -30, 8, -36, 4); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-6, 12); ctx.bezierCurveTo(-18, 10, -30, 4, -36, 0); ctx.stroke();
  ctx.restore();
  _chrome(ctx, -36, 0, 8, 6); _chrome(ctx, -36, 6, 8, 6);
  _exhaustFlame(ctx, -38, 2, thr, t, 1.0);
  _exhaustFlame(ctx, -38, 8, thr, t, 0.9);
  // Tail light
  _taillight(ctx, -36, -8, 9);
  // --- Additive polish: tank gloss, chrome pipe tips, headlight glint, idle vibe ---
  ctx.save();
  // Teardrop-tank glossy reflection
  ctx.fillStyle = 'rgba(255,255,255,0.26)';
  ctx.beginPath(); ctx.ellipse(-2,-30,9,3,-0.3,0,Math.PI*2); ctx.fill();
  // Chrome dual-pipe tips
  ctx.fillStyle = '#eee';
  ctx.beginPath(); ctx.ellipse(-36,1,2.4,1.4,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(-36,7,2.4,1.4,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle = '#333';
  ctx.beginPath(); ctx.arc(-36,1,1.1,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(-36,7,1.1,0,Math.PI*2); ctx.fill();
  // Headlight glass idle glint
  var chg = 0.5+0.35*Math.abs(Math.sin(t*2.6));
  ctx.fillStyle = 'rgba(255,255,235,'+chg.toFixed(2)+')';
  ctx.beginPath(); ctx.arc(43,-29,2.5,0,Math.PI*2); ctx.fill();
  // V-twin fin sheen flickering with idle vibration
  ctx.strokeStyle = 'rgba(255,255,255,'+(0.2+0.12*Math.abs(Math.sin(t*20))).toFixed(2)+')'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(0,-18); ctx.lineTo(10,-18); ctx.stroke();
  ctx.restore();
  // Rider
  _driver(ctx, -8, -30, def.color||'#8B0000', '#111', t);
}

