  const fg = ctx.createRadialGradient(10, -18, 2, 14, -14, 16);
  fg.addColorStop(0,'rgba(255,255,255,0.3)'); fg.addColorStop(1,'rgba(0,0,0,0.1)');
  ctx.fillStyle = fg; ctx.beginPath(); ctx.arc(14, -14, 16, 0, Math.PI*2); ctx.fill();
  // Windshield (small)
  ctx.fillStyle = 'rgba(150,200,255,0.4)';
  ctx.beginPath(); ctx.moveTo(8, -28); ctx.bezierCurveTo(14, -38, 22, -36, 24, -28);
  ctx.lineTo(20, -26); ctx.bezierCurveTo(18, -32, 12, -34, 8, -28); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#aaa'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(8, -28); ctx.bezierCurveTo(14, -38, 22, -36, 24, -28); ctx.stroke();
  // Handlebar
