  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.arc(18, -24, 3, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.arc(30, -24, 3, 0, Math.PI*2); ctx.fill();
  // Rear storage box
  ctx.fillStyle = '#1a1a1a'; ctx.beginPath(); ctx.roundRect(-30, -20, 18, 16, 3); ctx.fill();
  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.roundRect(-28, -18, 14, 12, 2); ctx.fill();
  ctx.strokeStyle = '#333'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-21, -18); ctx.lineTo(-21, -6); ctx.stroke();
  // Headlight
  _headlight(ctx, 30, -18, true, 8);
