function drawHoverCar(ctx, def, v, thr, t) {
  // Hover glow (below)
  const hov = 4 + Math.sin(t * 4) * 2;
  ctx.save();
  const hg = ctx.createRadialGradient(0, 20, 0, 0, 20, 50);
  hg.addColorStop(0, `rgba(0,200,255,${0.4 + Math.sin(t*3)*0.1})`);
  hg.addColorStop(0.5, `rgba(0,100,200,0.2)`);
  hg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = hg; ctx.beginPath(); ctx.arc(0, 20, 50, 0, Math.PI*2); ctx.fill();
  // Thruster jets (4 corners)
  const jd = thr > 0.2 ? 0.7 + Math.random()*0.3 : 0.3;
  for(const jx of [-42, 42]) {
    const jg = ctx.createRadialGradient(jx, 18, 0, jx, 18, 12);
    jg.addColorStop(0, `rgba(100,200,255,${jd})`);
    jg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = jg; ctx.beginPath(); ctx.arc(jx, 18, 12, 0, Math.PI*2); ctx.fill();
  }
  ctx.restore();
  // Main saucer body
  const bodG = ctx.createEllipse ? null : ctx.createLinearGradient(-60, -16, -60, 12);
  ctx.fillStyle = def.color || '#00ccff';
  ctx.beginPath(); ctx.ellipse(0, -2, 64, 20, 0, 0, Math.PI*2); ctx.fill();
  const bodyGrad = ctx.createLinearGradient(-60, -22, -60, 20);
  bodyGrad.addColorStop(0,'rgba(255,255,255,0.4)'); bodyGrad.addColorStop(0.4,'rgba(255,255,255,0.1)');
  bodyGrad.addColorStop(1,'rgba(0,0,0,0.3)');
  ctx.fillStyle = bodyGrad; ctx.beginPath(); ctx.ellipse(0, -2, 64, 20, 0, 0, Math.PI*2); ctx.fill();
  // Canopy dome
  ctx.fillStyle = '#111';
  ctx.beginPath(); ctx.ellipse(0, -12, 28, 18, 0, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = 'rgba(80,200,255,0.35)';
  ctx.beginPath(); ctx.ellipse(0, -12, 26, 16, 0, 0, Math.PI*2); ctx.fill();
  // Canopy highlight
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  ctx.beginPath(); ctx.ellipse(-8, -18, 12, 6, -0.4, 0, Math.PI*2); ctx.fill();
  // Pilot silhouette in dome
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.beginPath(); ctx.ellipse(0, -10, 8, 12, 0, 0, Math.PI*2); ctx.fill();
  // Rim detail
  ctx.strokeStyle = 'rgba(0,180,255,0.8)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.ellipse(0, -2, 64, 20, 0, 0, Math.PI*2); ctx.stroke();
  // Panel lines on hull
  ctx.strokeStyle = 'rgba(0,0,0,0.15)'; ctx.lineWidth = 1;
  for(let pl=0; pl<4; pl++) {
    ctx.beginPath(); ctx.ellipse(0, -2, 64-pl*14, 20-pl*3, 0, 0, Math.PI*2); ctx.stroke();
  }
  // Nacelles / engine pods
  for(const nx of [-44, 44]) {
    ctx.fillStyle = '#0a0a1a';
    ctx.beginPath(); ctx.ellipse(nx, 8, 10, 6, 0, 0, Math.PI*2); ctx.fill();
    const ng = ctx.createRadialGradient(nx, 10, 0, nx, 10, 8);
    ng.addColorStop(0, thr>0.3?'rgba(0,200,255,0.9)':'rgba(0,50,100,0.5)');
    ng.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = ng; ctx.beginPath(); ctx.arc(nx, 12, 8, 0, Math.PI*2); ctx.fill();
  }
  // Forward sensor array
  ctx.fillStyle = '#111'; ctx.fillRect(56, -8, 10, 14);
  for(let sa2=0; sa2<3; sa2++) {
    ctx.fillStyle = `rgba(0,${100+sa2*60},255,0.7)`;
    ctx.beginPath(); ctx.arc(61, -4+sa2*5, 2, 0, Math.PI*2); ctx.fill();
  }
  // Neon ring underglow
  _neonStrip(ctx, -60, 4, 120, def.color||'#00ccff');
  // Weapons / fins
  ctx.fillStyle = '#1a1a2a';
  ctx.fillRect(-64, -4, 10, 6); ctx.fillRect(54, -4, 10, 6);
  ctx.fillRect(-68, -2, 6, 3); ctx.fillRect(62, -2, 6, 3); // tips
  // --- Additive polish: canopy sweep glint, sensor pulse, nacelle rings ---
  ctx.save();
  // Canopy dome sweeping specular glint (idle life)
  var hcgx = -8 + Math.sin(t*2)*10;
  ctx.fillStyle = 'rgba(255,255,255,0.30)';
  ctx.beginPath(); ctx.ellipse(hcgx,-16,7,3,-0.4,0,Math.PI*2); ctx.fill();
  // Forward sensor array pulse
  var hsp = 0.4+0.5*Math.abs(Math.sin(t*4));
  ctx.save(); ctx.shadowColor = 'rgba(0,200,255,0.9)'; ctx.shadowBlur = 6*hsp;
  ctx.fillStyle = 'rgba(120,230,255,'+hsp.toFixed(2)+')';
  ctx.beginPath(); ctx.arc(61,-4,2,0,Math.PI*2); ctx.fill(); ctx.restore();
  // Engine-pod chrome rings
  ctx.strokeStyle = 'rgba(150,220,255,0.5)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.ellipse(-44,8,10,6,0,0,Math.PI*2); ctx.stroke();
  ctx.beginPath(); ctx.ellipse(44,8,10,6,0,0,Math.PI*2); ctx.stroke();
  ctx.restore();
}

// AHMET — Hover Bike: ince, süzülen his veren hafif motor; alt itici parıltıları,
// tek koltuk, neon enerji şeridi. YER aracı (uçmaz) — hover pedleri sadece görsel.
function drawHoverbike(ctx, def, v, thr, t) {
  var c1 = def.color || '#12d6c2', c2 = def.color2 || '#141822';
  var pulse = 0.5 + Math.sin(t * 4) * 0.15 + thr * 0.25;

  // ── Hover underglow (yumuşak süzülme yastığı) ──
  ctx.save();
  var ug = ctx.createRadialGradient(0, 26, 0, 0, 26, 58);
  ug.addColorStop(0, 'rgba(0,220,210,' + (0.38 * pulse).toFixed(2) + ')');
  ug.addColorStop(0.5, 'rgba(0,150,180,0.16)');
  ug.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = ug;
  ctx.beginPath(); ctx.ellipse(0, 26, 58, 16, 0, 0, Math.PI * 2); ctx.fill();

  // ── Alt itici jetleri (ön + arka pod) ──
  var jd = thr > 0.2 ? (0.75 + Math.random() * 0.25) : 0.4;
  for (var ji = 0; ji < 2; ji++) {
    var jx = ji === 0 ? -32 : 30;
    var jg = ctx.createRadialGradient(jx, 20, 0, jx, 20, 13);
    jg.addColorStop(0, 'rgba(120,240,255,' + jd.toFixed(2) + ')');
    jg.addColorStop(0.5, 'rgba(0,180,220,0.35)');
    jg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = jg; ctx.beginPath(); ctx.arc(jx, 20, 13, 0, Math.PI * 2); ctx.fill();
    // sıcak çekirdek
    ctx.fillStyle = 'rgba(220,255,255,' + (0.6 * jd).toFixed(2) + ')';
    ctx.beginPath(); ctx.ellipse(jx, 18, 5, 2.5, 0, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();

  // ── Süzülen gövde salınımı (boşta canlılık) ──
  var bob = Math.sin(t * 3) * 1.5;
  ctx.save();
  ctx.translate(0, bob);

  // ── İtici pod kılıfları ──
  ctx.fillStyle = _shade(c2, 0.05);
  for (var pi = 0; pi < 2; pi++) {
    var px = pi === 0 ? -32 : 30;
    ctx.beginPath(); ctx.roundRect(px - 11, 8, 22, 10, [3, 3, 6, 6]); ctx.fill();
    ctx.strokeStyle = 'rgba(0,220,255,0.7)'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(px - 8, 16); ctx.lineTo(px + 8, 16); ctx.stroke();
  }

  // ── Ana şasi — ince, alçak, sivri burun (sağda) ──
  var bg = ctx.createLinearGradient(0, -14, 0, 12);
  bg.addColorStop(0, _shade(c1, 0.45)); bg.addColorStop(0.45, c1); bg.addColorStop(1, _shade(c1, -0.4));
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-46, 4);
  ctx.lineTo(-42, -6);
  ctx.quadraticCurveTo(-10, -14, 20, -10);
  ctx.lineTo(44, -6);
  ctx.quadraticCurveTo(56, -3, 50, 4);
  ctx.quadraticCurveTo(10, 10, -30, 9);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = _shade(c1, 0.5); ctx.lineWidth = 1.2;
  ctx.stroke();

  // ── Parlak boya süpürmesi ──
  ctx.fillStyle = 'rgba(255,255,255,0.22)';
  ctx.beginPath();
  ctx.moveTo(-40, -4); ctx.quadraticCurveTo(-6, -11, 40, -6);
  ctx.quadraticCurveTo(-4, -6, -40, -1); ctx.closePath(); ctx.fill();

  // ── Neon enerji şeridi (yan panel) ──
  ctx.save();
  ctx.shadowColor = 'rgba(0,230,255,0.9)'; ctx.shadowBlur = 8;
  ctx.strokeStyle = 'rgba(80,240,255,0.95)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-40, 2); ctx.quadraticCurveTo(0, 4, 44, 0); ctx.stroke();
  ctx.restore();

  // ── Ön kaporta / gidon başlığı ──
  ctx.fillStyle = _shade(c2, 0.1);
  ctx.beginPath(); ctx.moveTo(20, -10); ctx.lineTo(38, -22); ctx.lineTo(44, -20); ctx.lineTo(40, -7); ctx.closePath(); ctx.fill();
  // cam parlaması
  ctx.fillStyle = 'rgba(130,220,255,0.5)';
  ctx.beginPath(); ctx.moveTo(24, -11); ctx.lineTo(37, -20); ctx.lineTo(40, -12); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.35)';
  ctx.beginPath(); ctx.moveTo(28, -13); ctx.lineTo(35, -18); ctx.lineTo(36, -15); ctx.closePath(); ctx.fill();
  // gidon
  ctx.strokeStyle = _shade(c2, 0.25); ctx.lineWidth = 2.5; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(34, -18); ctx.lineTo(44, -24); ctx.stroke();

  // ── Ön far ──
  _headlight(ctx, 50, -2, true, 6);

  // ── Tek koltuk kamburu ──
  ctx.fillStyle = _shade(c2, 0.02);
  ctx.beginPath(); ctx.moveTo(-30, -6); ctx.quadraticCurveTo(-14, -16, -2, -8); ctx.quadraticCurveTo(-16, -6, -30, -4); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.10)';
  ctx.beginPath(); ctx.ellipse(-16, -11, 8, 2.5, -0.2, 0, Math.PI * 2); ctx.fill();

  // ── Arka kuyruk kanadı + parıltı ──
  ctx.fillStyle = _shade(c1, -0.2);
  ctx.beginPath(); ctx.moveTo(-46, 4); ctx.lineTo(-54, -14); ctx.lineTo(-44, -6); ctx.closePath(); ctx.fill();
  ctx.save();
  ctx.shadowColor = 'rgba(0,230,255,0.9)'; ctx.shadowBlur = 6;
  ctx.strokeStyle = 'rgba(80,240,255,0.9)'; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(-46, 3); ctx.lineTo(-53, -13); ctx.stroke();
  ctx.restore();

  // ── Sürücü ──
  _driver(ctx, -6, -20, c1, '#101820', t);

  ctx.restore();
}

