function drawMoonLander(ctx, def, v, thr, t) {
  const sa = v.suspAnim || [0,0];
  // Descent engine glow (bottom)
  if (thr > 0.1) {
    ctx.save();
    const eg = ctx.createRadialGradient(0, 26, 0, 0, 26, 30);
    eg.addColorStop(0, `rgba(180,140,255,${0.7*thr})`);
    eg.addColorStop(0.4, `rgba(100,50,220,${0.4*thr})`);
    eg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = eg; ctx.beginPath(); ctx.arc(0, 26, 30, 0, Math.PI*2); ctx.fill();
    ctx.restore();
  }
  // WIKI(3 Agu): "shape-shifting SIX-WHEELER" — 6 küçük teker EKLEMLİ süspansiyon
  //   kollarıyla platform şasiye bağlanır. Tekerlerin kendisi drawVehicle'da çizilir;
  //   burada yalnızca onları şasiye bağlayan kollar çizilir (ölçüldü: fiziğe etkisi 0).
  {
    const wl = def.wheels || [];
    ctx.strokeStyle = '#9aa0a6'; ctx.lineWidth = 2.5; ctx.lineCap = 'round';
    for (let i = 0; i < wl.length; i++) {
      const c = Math.max(0, sa[i] || 0);
      ctx.beginPath();
      ctx.moveTo(wl[i].x * 0.45, 6);
      ctx.lineTo(wl[i].x, (wl[i].y || 32) * (1 - c * 0.3) - 4);
      ctx.stroke();
    }
    ctx.strokeStyle = '#6f757c'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(-56, 8); ctx.lineTo(56, 8); ctx.stroke();   // platform şasi
  }
  // Landing legs (4 of them, spring-loaded)
  const legCompress = Math.max(0, sa[0]||0);
  const legH = 22 - legCompress * 4;
  for(const lx of [-38, 38]) {
    // Leg strut
    ctx.strokeStyle = '#aaa'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(lx*0.5, 8); ctx.lineTo(lx, legH); ctx.stroke();
    // Cross brace
    ctx.lineWidth = 1.5; ctx.strokeStyle = '#888';
    ctx.beginPath(); ctx.moveTo(lx*0.3, 14); ctx.lineTo(lx*0.8, 14); ctx.stroke();
    // Foot pad
    ctx.fillStyle = '#ccc';
    ctx.beginPath(); ctx.ellipse(lx, legH+2, 10, 4, 0, 0, Math.PI*2); ctx.fill();
    ctx.strokeStyle = '#999'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.ellipse(lx, legH+2, 10, 4, 0, 0, Math.PI*2); ctx.stroke();
  }
  // Fuel tanks (spherical, quad)
  for(const [tx, ty] of [[-22, 0], [22, 0], [-22, -20], [22, -20]]) {
    ctx.fillStyle = '#ccc';
    ctx.beginPath(); ctx.arc(tx, ty, 10, 0, Math.PI*2); ctx.fill();
    const tg = ctx.createRadialGradient(tx-3, ty-3, 1, tx, ty, 10);
    tg.addColorStop(0,'rgba(255,255,255,0.5)'); tg.addColorStop(1,'rgba(0,0,0,0.2)');
    ctx.fillStyle = tg; ctx.beginPath(); ctx.arc(tx, ty, 10, 0, Math.PI*2); ctx.fill();
    ctx.strokeStyle = '#aaa'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(tx, ty, 10, 0, Math.PI*2); ctx.stroke();
  }
  // Frame / truss structure
  ctx.strokeStyle = '#888'; ctx.lineWidth = 2;
  // Vertical struts
  ctx.beginPath(); ctx.moveTo(-10, 8); ctx.lineTo(-10, -28); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(10, 8); ctx.lineTo(10, -28); ctx.stroke();
  // Cross members
  ctx.beginPath(); ctx.moveTo(-22, 0); ctx.lineTo(22, 0); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-22, -20); ctx.lineTo(22, -20); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-10, -14); ctx.lineTo(10, -14); ctx.stroke();
  // Descent engine bell
  ctx.fillStyle = '#bbb';
  ctx.beginPath(); ctx.moveTo(-14, 8); ctx.lineTo(14, 8); ctx.lineTo(10, 22); ctx.lineTo(-10, 22); ctx.closePath(); ctx.fill();
  _chrome(ctx, -14, 8, 28, 4);
  ctx.strokeStyle = '#999'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-14, 12); ctx.lineTo(14, 12); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-12, 16); ctx.lineTo(12, 16); ctx.stroke();
  // Ascent stage (top box)
  ctx.fillStyle = '#ddd';
  ctx.beginPath(); ctx.roundRect(-18, -38, 36, 18, 3); ctx.fill();
  const asg = ctx.createLinearGradient(-18, -38, -18, -20);
  asg.addColorStop(0, 'rgba(255,255,255,0.4)'); asg.addColorStop(1, 'rgba(0,0,0,0.1)');
  ctx.fillStyle = asg; ctx.beginPath(); ctx.roundRect(-18, -38, 36, 18, 3); ctx.fill();
  // Ascent engine nozzle
  ctx.fillStyle = '#bbb';
  ctx.beginPath(); ctx.moveTo(-8, -38); ctx.lineTo(8, -38); ctx.lineTo(6, -44); ctx.lineTo(-6, -44); ctx.closePath(); ctx.fill();
  // Docking port
  ctx.fillStyle = '#888'; ctx.beginPath(); ctx.arc(0, -42, 6, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#aaa'; ctx.beginPath(); ctx.arc(0, -42, 4, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#666'; ctx.beginPath(); ctx.arc(0, -42, 2, 0, Math.PI*2); ctx.fill();
  // Windows (small round portholes)
  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.arc(-8, -30, 4, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = 'rgba(100,200,255,0.5)'; ctx.beginPath(); ctx.arc(-8, -30, 3, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.arc(8, -30, 4, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = 'rgba(100,200,255,0.5)'; ctx.beginPath(); ctx.arc(8, -30, 3, 0, Math.PI*2); ctx.fill();
  // Solar panels (deployed)
  ctx.fillStyle = '#1a4a8a';
  ctx.fillRect(-54, -32, 28, 12); ctx.fillRect(26, -32, 28, 12);
  // Solar cell lines
  ctx.strokeStyle = '#2a5aaa'; ctx.lineWidth = 0.5;
  for(let sc=0; sc<7; sc++) { ctx.beginPath(); ctx.moveTo(-52+sc*4, -32); ctx.lineTo(-52+sc*4, -20); ctx.stroke(); }
  for(let sc=0; sc<7; sc++) { ctx.beginPath(); ctx.moveTo(28+sc*4, -32); ctx.lineTo(28+sc*4, -20); ctx.stroke(); }
  // Solar panel supports
  ctx.strokeStyle = '#888'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-18, -26); ctx.lineTo(-26, -26); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(18, -26); ctx.lineTo(26, -26); ctx.stroke();
  // Navigation antenna
  ctx.strokeStyle = '#aaa'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(14, -38); ctx.lineTo(20, -56); ctx.stroke();
  ctx.fillStyle = '#ccc'; ctx.beginPath(); ctx.arc(20, -56, 3, 0, Math.PI*2); ctx.fill();
  // Thruster plumes
  if (thr > 0.1) {
    _exhaustFlame(ctx, 0, 20, thr, t, 1.2);
  }
  // RCS thrusters (small)
  for(const [rx, ry] of [[-20, -20], [20, -20]]) {
    ctx.fillStyle = '#999'; ctx.fillRect(rx-3, ry-2, 5, 4);
  }
  // --- Additive polish: nav beacon, porthole reflections, solar glint, foil sheen ---
  ctx.save();
  // Blinking red nav beacon on the antenna dish (idle life)
  var nb = 0.4 + 0.6*Math.abs(Math.sin(t*3));
  ctx.fillStyle = 'rgba(255,60,60,'+nb.toFixed(2)+')';
  ctx.beginPath(); ctx.arc(20,-56,2,0,Math.PI*2); ctx.fill();
  // Porthole glass reflections
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.beginPath(); ctx.arc(-9,-31,1.1,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(7,-31,1.1,0,Math.PI*2); ctx.fill();
  // Solar panel glint sweeping across the cells
  var solx = (Math.sin(t*1.2)*0.5+0.5);
  ctx.fillStyle = 'rgba(180,220,255,0.35)';
  ctx.fillRect(-54+solx*26,-32,3,12);
  ctx.fillRect(26+solx*26,-32,3,12);
  // Gold-foil sheen on the descent stage
  ctx.fillStyle = 'rgba(255,215,120,0.18)';
  ctx.beginPath(); ctx.moveTo(-14,8); ctx.lineTo(-4,8); ctx.lineTo(-9,20); ctx.lineTo(-11,20); ctx.closePath(); ctx.fill();
  // Engine bell heat glow when firing
  if (thr > 0.1) {
    ctx.save(); ctx.shadowColor = 'rgba(180,140,255,0.9)'; ctx.shadowBlur = 10;
    ctx.strokeStyle = 'rgba(200,170,255,'+(0.5*thr).toFixed(2)+')'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-10,22); ctx.lineTo(10,22); ctx.stroke(); ctx.restore();
  }
  ctx.restore();
}

