function drawLawnMower(ctx, def, v, thr, t) {
  const sa = v.suspAnim || [0,0];
  _drawSusp(ctx, -26, 0, -26, 14*(1-(sa[0]||0)*0.2), sa[0]||0);
  _drawSusp(ctx,  26, 0,  26, 14*(1-(sa[1]||0)*0.2), sa[1]||0);
  // Deck (main cutting body)
  ctx.fillStyle = '#cc0000';
  ctx.beginPath(); ctx.roundRect(-40, 4, 80, 14, 3); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.15)'; ctx.beginPath(); ctx.roundRect(-38, 4, 76, 7, 2); ctx.fill();
  // Blade discharge chute
  ctx.fillStyle = '#aa0000';
  ctx.beginPath(); ctx.moveTo(-42, 10); ctx.lineTo(-54, 14); ctx.lineTo(-54, 20); ctx.lineTo(-40, 18); ctx.closePath(); ctx.fill();
  // Blade visible (spinning)
  ctx.save(); ctx.translate(0, 11); ctx.rotate(t * 20);
  ctx.strokeStyle = '#aaa'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(-24, 0); ctx.lineTo(24, 0); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(0, -24); ctx.lineTo(0, 24); ctx.stroke();
  ctx.fillStyle = '#ccc'; ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
  ctx.restore();
  // Engine block on top
  ctx.fillStyle = '#1a1a1a'; ctx.beginPath(); ctx.roundRect(-14, -20, 28, 26, 4); ctx.fill();
  ctx.fillStyle = '#2a2a2a'; ctx.beginPath(); ctx.roundRect(-12, -18, 24, 20, 3); ctx.fill();
  // Cooling fins
  ctx.strokeStyle = '#333'; ctx.lineWidth = 1.5;
  for(let f=0; f<5; f++) { ctx.beginPath(); ctx.moveTo(-12, -14+f*4); ctx.lineTo(12, -14+f*4); ctx.stroke(); }
  // Fuel cap
  ctx.fillStyle = '#cc0000'; ctx.beginPath(); ctx.arc(-6, -22, 5, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#ff2222'; ctx.beginPath(); ctx.arc(-6, -22, 3, 0, Math.PI*2); ctx.fill();
  // Oil fill cap
  ctx.fillStyle = '#ffaa00'; ctx.beginPath(); ctx.arc(6, -22, 4, 0, Math.PI*2); ctx.fill();
  // Pull starter
  ctx.strokeStyle = '#888'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(14, -12); ctx.lineTo(24, -18); ctx.stroke();
  ctx.fillStyle = '#555'; ctx.beginPath(); ctx.arc(24, -18, 5, 0, Math.PI*2); ctx.fill();
  // Seat (zero-turn style)
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.roundRect(-18, -34, 36, 16, 5); ctx.fill();
  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.roundRect(-16, -32, 32, 14, 4); ctx.fill();
  // Steering wheel (lap bar)
  ctx.strokeStyle = '#444'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(-16, -26); ctx.lineTo(-22, -36); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(16, -26); ctx.lineTo(22, -36); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-22, -36); ctx.lineTo(22, -36); ctx.stroke();
  // Exhaust (small)
  ctx.fillStyle = '#555'; ctx.fillRect(-18, -28, 5, 8);
  _exhaustFlame(ctx, -16, -28, thr, t, 0.5);
  // Driver
  _driver(ctx, 0, -50, def.color||'#cc0000', '#228822', t);
}

