function drawRickshaw(ctx, def, v, thr, t) {
  const sa = v.suspAnim || [0,0];
  _drawSusp(ctx, -28, 0, -28, 16*(1-(sa[0]||0)*0.25), sa[0]||0);
  _drawSusp(ctx,  28, 0,  28, 16*(1-(sa[1]||0)*0.25), sa[1]||0);
  // Small front wheel / scooter front
  ctx.strokeStyle = '#555'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(24, 0); ctx.lineTo(32, -16); ctx.stroke();
  ctx.fillStyle = '#333'; ctx.beginPath(); ctx.arc(32, -14, 4, 0, Math.PI*2); ctx.fill();
  // Chassis tube
  ctx.strokeStyle = '#888'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(-28, -4); ctx.lineTo(28, -4); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-28, -4); ctx.lineTo(-28, 4); ctx.stroke();
  // Engine (3-wheeler style)
  ctx.fillStyle = '#1a1a1a'; ctx.beginPath(); ctx.roundRect(16, -16, 20, 22, 3); ctx.fill();
  ctx.strokeStyle = '#2a2a2a'; ctx.lineWidth = 1;
  for(let f2=0; f2<4; f2++) { ctx.beginPath(); ctx.moveTo(18, -12+f2*5); ctx.lineTo(34, -12+f2*5); ctx.stroke(); }
  // Passenger cabin
  _carPaint(ctx, -14, -18, 56, 34, def.color || '#f39c12');
  // Cabin roof (fabric canopy)
  ctx.fillStyle = '#e8a010';
  ctx.beginPath(); ctx.moveTo(-40, -18); ctx.lineTo(-40, -36); ctx.lineTo(12, -36); ctx.lineTo(12, -18); ctx.closePath(); ctx.fill();
  // Roof stripes
  ctx.fillStyle = 'rgba(255,255,255,0.25)';
  for(let rs=0; rs<4; rs++) { ctx.fillRect(-38+rs*12, -36, 6, 18); }
  // Side curtains (open)
  ctx.strokeStyle = '#d4880e'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-40, -18); ctx.lineTo(-40, 10); ctx.stroke(); // rear post
  ctx.beginPath(); ctx.moveTo(12, -18); ctx.lineTo(12, 10); ctx.stroke(); // front post
  // Window (open sides)
  ctx.fillStyle = 'rgba(150,210,255,0.2)';
  ctx.beginPath(); ctx.roundRect(-36, -18, 44, 24, 2); ctx.fill();
  // Passengers (decorated)
  ctx.fillStyle = '#e64c19'; ctx.beginPath(); ctx.arc(-22, -22, 8, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#FFCC44'; ctx.beginPath(); ctx.arc(-22, -22, 6, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#ff4444'; ctx.fillRect(-28, -32, 12, 6); // hat
  ctx.fillStyle = '#e64c19'; ctx.beginPath(); ctx.arc(-2, -22, 8, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#FFCC44'; ctx.beginPath(); ctx.arc(-2, -22, 6, 0, Math.PI*2); ctx.fill();
  // Driver (front)
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(20, -26, 8, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#FFCC44'; ctx.beginPath(); ctx.arc(20, -26, 6, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#222'; ctx.beginPath(); ctx.arc(20, -26, 6, Math.PI, 0); ctx.fill();
  // Decorative fringe
  ctx.strokeStyle = '#f39c12'; ctx.lineWidth = 2;
  for(let fr=0; fr<8; fr++) {
    ctx.beginPath(); ctx.moveTo(-40+fr*7, -36); ctx.lineTo(-37+fr*7, -40); ctx.stroke();
  }
  // Handlebar
  ctx.strokeStyle = '#666'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(24, -26); ctx.bezierCurveTo(28,-32, 34, -32, 36, -26); ctx.stroke();
  // Headlight
  _headlight(ctx, 38, -20, true, 7);
  // Taillight
  _taillight(ctx, -42, -14, 8);
  // Exhaust
  ctx.fillStyle = '#555'; ctx.fillRect(-24, 8, 5, 5);
  _exhaustFlame(ctx, -22, 8, thr, t, 0.5);
  // Decorations (flowers painted on side)
  ctx.fillStyle = 'rgba(255,100,100,0.5)';
  ctx.beginPath(); ctx.arc(-30, -2, 6, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = 'rgba(255,200,0,0.7)';
  ctx.beginPath(); ctx.arc(-30, -2, 3, 0, Math.PI*2); ctx.fill();
}

  // Hood / cover
  // Fringe decoration
  // Engine (rear)
  // TAXI sign
  // Exhaust

function drawHipsterCar(ctx, def, v, thr, t) {
  const sa = v.suspAnim || [0,0];
  _drawSusp(ctx, -40, 0, -40, 16*(1-(sa[0]||0)*0.22), sa[0]||0);
  _drawSusp(ctx,  40, 0,  40, 16*(1-(sa[1]||0)*0.22), sa[1]||0);
  // Vintage car body (tall narrow 1960s style)
  _carPaint(ctx, 0, -16, 102, 40, def.color || '#2ecc71');
  // Curved roofline (tall)
  ctx.fillStyle = def.color||'#2ecc71';
  ctx.beginPath(); ctx.moveTo(-44, -18); ctx.lineTo(-36, -52); ctx.lineTo(28, -52); ctx.lineTo(36, -18); ctx.closePath(); ctx.fill();
  const hg = ctx.createLinearGradient(-44,-52,36,-18);
  hg.addColorStop(0,'rgba(255,255,255,0.25)'); hg.addColorStop(1,'rgba(0,0,0,0.12)');
  ctx.fillStyle = hg;
  ctx.beginPath(); ctx.moveTo(-44, -18); ctx.lineTo(-36, -52); ctx.lineTo(28, -52); ctx.lineTo(36, -18); ctx.closePath(); ctx.fill();
  // Rounded windows (VW bug style)
  ctx.fillStyle = 'rgba(100,200,255,0.4)';
  ctx.beginPath(); ctx.arc(-10, -36, 14, Math.PI, 0); ctx.lineTo(4, -22); ctx.lineTo(-24, -22); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(100,200,255,0.4)';
  ctx.beginPath(); ctx.arc(20, -32, 10, Math.PI, 0); ctx.lineTo(30, -22); ctx.lineTo(10, -22); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#111'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(8, -22); ctx.lineTo(10, -44); ctx.stroke(); // B-pillar
  ctx.beginPath(); ctx.moveTo(-24, -22); ctx.lineTo(-28, -44); ctx.stroke(); // A-pillar
  // Hood (smooth curved)
  ctx.fillStyle = def.color||'#2ecc71';
  ctx.beginPath(); ctx.moveTo(34, -16); ctx.bezierCurveTo(44, -20, 52, -14, 54, -4); ctx.lineTo(54, 10); ctx.lineTo(34, 10); ctx.closePath(); ctx.fill();
  const hoodg = ctx.createLinearGradient(34,-20,54,10);
  hoodg.addColorStop(0,'rgba(255,255,255,0.2)'); hoodg.addColorStop(1,'rgba(0,0,0,0.15)');
  ctx.fillStyle = hoodg;
  ctx.beginPath(); ctx.moveTo(34, -16); ctx.bezierCurveTo(44, -20, 52, -14, 54, -4); ctx.lineTo(54, 10); ctx.lineTo(34, 10); ctx.closePath(); ctx.fill();
  // Round headlights (vintage)
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(52, -12, 8, 0, Math.PI*2); ctx.fill();
  _headlight(ctx, 52, -12, true, 6);
  ctx.strokeStyle = '#888'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.arc(52, -12, 8, 0, Math.PI*2); ctx.stroke();
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(54, 2, 6, 0, Math.PI*2); ctx.fill();
  _headlight(ctx, 54, 2, true, 4);
  // Grille (period correct vertical bars)
  ctx.fillStyle = '#c8a800'; // chrome gold
  ctx.beginPath(); ctx.roundRect(50, -8, 8, 14, 2); ctx.fill();
  ctx.fillStyle = '#111';
  for(let gr=0; gr<4; gr++) { ctx.fillRect(52, -6+gr*3, 4, 2); }
  // Chrome bumpers (period style)
  _chrome(ctx, 48, 8, 14, 6);
  _chrome(ctx, -54, 8, 14, 6);
  // Tailfins!
  ctx.fillStyle = def.color||'#2ecc71';
  ctx.beginPath(); ctx.moveTo(-50, -10); ctx.lineTo(-60, -32); ctx.lineTo(-44, -22); ctx.closePath(); ctx.fill();
  _taillight(ctx, -58, -28, 9);
  // Roof rack (vintage luggage)
  ctx.fillStyle = '#4a2a0a'; ctx.fillRect(-32, -56, 60, 6); // luggage
  ctx.fillStyle = '#6a3a0a'; ctx.fillRect(-30, -54, 56, 4);
  ctx.strokeStyle = '#2a1a04'; ctx.lineWidth = 1;
  for(let ls=0; ls<4; ls++) { ctx.beginPath(); ctx.moveTo(-28+ls*16, -56); ctx.lineTo(-28+ls*16, -50); ctx.stroke(); }
  // Chrome rack rails
  ctx.strokeStyle = '#aaa'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-34, -50); ctx.lineTo(28, -50); ctx.stroke();
  // Exhaust (side pipe classic)
  ctx.save(); ctx.strokeStyle = '#888'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(-30, 10); ctx.lineTo(-50, 10); ctx.stroke();
  ctx.restore();
  _chrome(ctx, -50, 8, 10, 5);
  _exhaustFlame(ctx, -52, 10, thr, t, 0.7);
  // Driver
  _driver(ctx, -4, -62, def.color||'#2ecc71', '#4a3a0a', t);
}

