function drawPaintingTruck(ctx, def, v, thr, t) {
  const sa = v.suspAnim || [0,0];
  _drawSusp(ctx, -44, 0, -44, 16*(1-(sa[0]||0)*0.22), sa[0]||0);
  _drawSusp(ctx,  44, 0,  44, 16*(1-(sa[1]||0)*0.22), sa[1]||0);
  // Chassis
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.roundRect(-62, 4, 124, 14, 3); ctx.fill();
  // Main box body (paint truck)
  _carPaint(ctx, -8, -16, 100, 42, def.color || '#FFFFFF');
  // Colorful paint splatter on sides
  const colors2 = ['#FF3366','#00CCFF','#FFAA00','#00FF88','#FF00FF','#FFEE00'];
  for(let sp=0; sp<12; sp++) {
    const spx = -40 + sp * 8 + Math.sin(sp * 1.7) * 4;
    const spy = -20 + Math.cos(sp * 2.3) * 10;
    const spr = 3 + (sp % 3) * 2;
    ctx.fillStyle = colors2[sp % 6];
    ctx.beginPath(); ctx.arc(spx, spy, spr, 0, Math.PI*2); ctx.fill();
    // Splat spikes
    for(let ss=0; ss<4; ss++) {
      const ang = (ss / 4) * Math.PI * 2;
      ctx.fillStyle = colors2[(sp+2) % 6];
      ctx.beginPath(); ctx.arc(spx + Math.cos(ang)*spr*1.5, spy + Math.sin(ang)*spr*1.3, 1.5, 0, Math.PI*2); ctx.fill();
    }
  }
  // Paint brush mounted on side
  ctx.fillStyle = '#8B4513'; ctx.fillRect(-60, -20, 6, 24); // handle
  ctx.fillStyle = '#888'; ctx.fillRect(-60, -22, 6, 4); // ferrule
  ctx.fillStyle = '#ffcc00'; ctx.beginPath(); ctx.moveTo(-62, 4); ctx.lineTo(-54, 4); ctx.lineTo(-56, 8); ctx.lineTo(-60, 8); ctx.closePath(); ctx.fill(); // bristles
  // Paint roller on top
  ctx.fillStyle = '#888'; ctx.fillRect(-10, -42, 4, 10); // arm
  ctx.fillStyle = '#ddd'; ctx.beginPath(); ctx.ellipse(-8, -42, 8, 4, 0, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = colors2[(Math.floor(t*2)%6)]; ctx.beginPath(); ctx.ellipse(-8, -42, 6, 3, 0, 0, Math.PI*2); ctx.fill();
  // Cab windows
  _window(ctx, 28, -36, 40, 30);
  ctx.strokeStyle = '#111'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(28, -22); ctx.lineTo(68, -22); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(48, -36); ctx.lineTo(48, -6); ctx.stroke();
  // Cab
  ctx.fillStyle = def.color || '#fff';
  ctx.beginPath(); ctx.moveTo(56, -20); ctx.lineTo(58, -40); ctx.lineTo(68, -40); ctx.lineTo(68, -20); ctx.closePath(); ctx.fill();
  // Company logo on side
  ctx.fillStyle = '#1a1a1a'; ctx.font = 'bold 8px Arial'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('PAINT', -8, -2);
  ctx.font = 'bold 6px Arial'; ctx.fillText('PRO', -8, 8);
  // Headlights
  _headlight(ctx, 64, -34, true, 8);
  _headlight(ctx, 64, -18, true, 7);
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.roundRect(60, -38, 10, 26, 2); ctx.fill();
  // Taillights
  _taillight(ctx, -64, -20, 9);
  ctx.fillStyle = '#cc0000'; ctx.fillRect(-66, -26, 6, 20);
  // Exhaust
  _exhaustFlame(ctx, -64, 6, thr, t, 0.85);
  ctx.fillStyle = '#555'; ctx.fillRect(-64, 4, 8, 5);
  // Dripping paint trail from rear
  if (thr > 0.1) {
    for(let dp=0; dp<4; dp++) {
      ctx.fillStyle = colors2[dp % 6];
      ctx.fillRect(-62 - dp*8, 14 + dp*3, 4, 4 + dp*2);
    }
  }
  _driver(ctx, 42, -50, def.color||'#fff', '#1a1a1a', t);
}

