function drawSupercar(ctx, def, v, thr, t) {
  const sa = v.suspAnim || [0,0];
  _drawSusp(ctx, -48, 0, -48, 12*(1-(sa[0]||0)*0.3), sa[0]||0);
  _drawSusp(ctx,  48, 0,  48, 12*(1-(sa[1]||0)*0.3), sa[1]||0);
  // Ground effect / diffuser
  ctx.fillStyle = '#0a0a0a';
  ctx.beginPath(); ctx.moveTo(-62, 10); ctx.lineTo(-56, 18); ctx.lineTo(56, 18); ctx.lineTo(62, 10); ctx.closePath(); ctx.fill();
  // Diffuser fins
  ctx.fillStyle = '#111';
  for(let df=0; df<7; df++) { ctx.fillRect(-52+df*16, 12, 8, 6); }
  // Low wide body
  _carPaint(ctx, 0, -10, 120, 32, def.color || '#9b59b6');
  // Side sills (extended)
  ctx.fillStyle = '#0d0d0d'; ctx.fillRect(-60, 6, 120, 8);
  // Air vents on side
  for(let sv=0; sv<3; sv++) {
    ctx.fillStyle = '#1a1a1a'; ctx.beginPath(); ctx.roundRect(-52+sv*28, -2, 18, 6, 2); ctx.fill();
    ctx.fillStyle = '#222';
    for(let svl=0; svl<3; svl++) { ctx.fillRect(-50+sv*28, -1+svl*2, 14, 1); }
  }
  // Cabin / windshield (very low, raked)
  ctx.fillStyle = '#1a1a1a';
  ctx.beginPath(); ctx.moveTo(-24, -10); ctx.lineTo(-16, -40); ctx.lineTo(24, -40); ctx.lineTo(30, -10); ctx.closePath(); ctx.fill();
  _window(ctx, -18, -40, 42, 28);
  // A-pillars
  ctx.strokeStyle = '#111'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(-18, -40); ctx.lineTo(-24, -10); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(24, -40); ctx.lineTo(30, -10); ctx.stroke();
  // Roof scoop
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.roundRect(-8, -44, 20, 6, 3); ctx.fill();
  ctx.fillStyle = '#0a0a0a'; ctx.beginPath(); ctx.roundRect(-6, -44, 16, 4, 2); ctx.fill();
  // Active rear wing
  ctx.fillStyle = '#1a1a1a'; ctx.fillRect(-50, -38, 100, 6);
  ctx.fillRect(-48, -32, 5, 18); ctx.fillRect(43, -32, 5, 18);
  // Wing end plates
  ctx.fillStyle = def.color||'#9b59b6';
  ctx.beginPath(); ctx.roundRect(-54, -42, 8, 24, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(46, -42, 8, 24, 2); ctx.fill();
  // Hood with air intakes
  ctx.fillStyle = '#111'; ctx.beginPath();
  ctx.moveTo(28, -14); ctx.bezierCurveTo(42, -18, 54, -16, 60, -8); ctx.lineTo(60, 6); ctx.lineTo(32, 8); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#0d0d0d';
  ctx.beginPath(); ctx.roundRect(32, -18, 20, 8, 2); ctx.fill(); // Hood intake
  // Quad headlights
  _headlight(ctx, 58, -14, true, 8);
  _headlight(ctx, 58, -4, true, 7);
  ctx.fillStyle = 'rgba(255,200,50,0.5)'; ctx.fillRect(54, -6, 8, 3); // DRL strip
  // Taillights
  _taillight(ctx, -62, -14, 9); _taillight(ctx, -62, -2, 8);
  ctx.fillStyle = 'rgba(255,0,0,0.4)'; ctx.fillRect(-62, -8, 6, 3); // brake strip
  // Quad exhausts (low center)
  _exhaustFlame(ctx, -62, 6, thr, t, 1.1);
  _exhaustFlame(ctx, -62, 12, thr, t, 1.0);
  ctx.fillStyle = '#333'; ctx.fillRect(-64, 2, 8, 5); ctx.fillRect(-64, 9, 8, 5);
  // Neon underbody
  _neonStrip(ctx, -58, 14, 116, def.color||'#9b59b6');
  // Brake caliper detail (visible through wheels)
  ctx.fillStyle = '#e74c3c'; ctx.beginPath(); ctx.arc(-48, 8, 5, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#e74c3c'; ctx.beginPath(); ctx.arc(48, 8, 5, 0, Math.PI*2); ctx.fill();
  // --- Additive polish: canopy glare, quad-headlight bezels, chrome tips, idle glint ---
  ctx.save();
  // Windshield/canopy glare streak
  ctx.fillStyle = 'rgba(255,255,255,0.24)';
  ctx.beginPath(); ctx.moveTo(-14,-38); ctx.lineTo(0,-38); ctx.lineTo(-8,-22); ctx.lineTo(-18,-22); ctx.closePath(); ctx.fill();
  // Quad-headlight glass bezels
  ctx.strokeStyle = 'rgba(220,220,200,0.6)'; ctx.lineWidth = 1.3;
  ctx.beginPath(); ctx.arc(58,-14,8,0,Math.PI*2); ctx.stroke();
  ctx.beginPath(); ctx.arc(58,-4,7,0,Math.PI*2); ctx.stroke();
  // Chrome quad-exhaust tips
  ctx.fillStyle = '#ccc';
  ctx.beginPath(); ctx.ellipse(-62,4,3,1.6,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(-62,11,3,1.6,0,0,Math.PI*2); ctx.fill();
  ctx.fillStyle = '#222';
  ctx.beginPath(); ctx.ellipse(-62,4,1.6,0.9,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(-62,11,1.6,0.9,0,0,Math.PI*2); ctx.fill();
  // Sweeping body specular glint (idle life)
  var spgx = Math.sin(t*1.7)*26;
  ctx.fillStyle = 'rgba(255,255,255,0.15)';
  ctx.beginPath(); ctx.ellipse(spgx,-10,12,3.5,-0.3,0,Math.PI*2); ctx.fill();
  ctx.restore();
}

