  pbg.addColorStop(0,'rgba(255,255,255,0.3)'); pbg.addColorStop(1,'rgba(0,0,0,0.15)');
  ctx.fillStyle=col;
  ctx.beginPath();
  ctx.moveTo(-w*0.14,-h*0.48); ctx.lineTo(w*0.5,-h*0.48);
  ctx.lineTo(w*0.54,-h*0.04); ctx.lineTo(-w*0.16,-h*0.04);
  ctx.closePath(); ctx.fill();
  ctx.fillStyle=pbg;
  ctx.beginPath();
  ctx.moveTo(-w*0.14,-h*0.48); ctx.lineTo(w*0.5,-h*0.48);
  ctx.lineTo(w*0.54,-h*0.04); ctx.lineTo(-w*0.16,-h*0.04);
  ctx.closePath(); ctx.fill();
  // Cabin roof
  ctx.fillStyle=col;
  ctx.beginPath();
  ctx.roundRect(-w*0.14,-h*0.48,w*0.64,h*0.44,4);
  ctx.fill();
  // Windshield
  ctx.fillStyle='rgba(120,200,255,0.5)';
  ctx.beginPath();
  ctx.moveTo(-w*0.1,-h*0.44); ctx.lineTo(w*0.42,-h*0.44);
  ctx.lineTo(w*0.44,-h*0.08); ctx.lineTo(-w*0.12,-h*0.08);
  ctx.closePath(); ctx.fill();
  // Side window
  ctx.fillStyle='rgba(120,200,255,0.35)';
  ctx.beginPath();
  ctx.roundRect(-w*0.14,-h*0.4,w*0.2,h*0.28,2);
  ctx.fill();
  // Bed detail (cargo)
  ctx.fillStyle='rgba(60,40,20,0.8)';
  ctx.fillRect(-w*0.5,-h*0.1,w*0.34,h*0.06);
  // Grille
  ctx.fillStyle='#111';
  ctx.fillRect(w*0.48,-h*0.2,w*0.07,h*0.14);
  ctx.fillStyle='rgba(255,200,50,0.8)';
