  ctx.fillStyle=col;
  ctx.beginPath(); ctx.roundRect(-w*0.44,-h*0.5,w*0.88,h*0.52,6); ctx.fill();
  ctx.fillStyle=dg;
  ctx.beginPath(); ctx.roundRect(-w*0.44,-h*0.5,w*0.88,h*0.52,6); ctx.fill();
  // Windshield
  ctx.fillStyle='rgba(120,200,255,0.5)';
  ctx.beginPath();
  ctx.moveTo(-w*0.28,-h*0.44); ctx.lineTo(w*0.3,-h*0.44);
  ctx.lineTo(w*0.28,-h*0.04); ctx.lineTo(-w*0.26,-h*0.04);
  ctx.closePath(); ctx.fill();
  // Snorkel tube on side
  ctx.fillStyle='#222'; ctx.fillRect(-w*0.44,-h*0.52,5,h*0.5);
  // Roof rack
  ctx.fillStyle='#333';
  ctx.fillRect(-w*0.38,-h*0.54,w*0.76,4);
  ctx.fillRect(-w*0.3,-h*0.54,3,h*0.06);
  ctx.fillRect(w*0.16,-h*0.54,3,h*0.06);
  // Roll cage visible through windshield
  ctx.strokeStyle='rgba(60,60,60,0.5)'; ctx.lineWidth=2;
  ctx.beginPath(); ctx.moveTo(-w*0.28,-h*0.44); ctx.lineTo(-w*0.28,-h*0.04); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(w*0.28,-h*0.44); ctx.lineTo(w*0.28,-h*0.04); ctx.stroke();
  // Front bull bar
  ctx.fillStyle='#444';
  ctx.beginPath();
  ctx.moveTo(w*0.46,-h*0.32); ctx.lineTo(w*0.56,-h*0.28);
  ctx.lineTo(w*0.56,-h*0.08); ctx.lineTo(w*0.46,-h*0.04);
  ctx.closePath(); ctx.fill();
  // Lights
  ctx.fillStyle='rgba(255,255,200,0.9)';
  ctx.beginPath(); ctx.arc(w*0.44,-h*0.26,4,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(w*0.44,-h*0.12,4,0,Math.PI*2); ctx.fill();
