function drawWarthog(ctx, def, v, thr, t) {
  const w = def.w||112, h = def.h||52;
  const col = def.color||'#556644';
  ctx.save();
  // Military green gradient
  const wg=ctx.createLinearGradient(0,-h*0.5,0,h*0.25);
  wg.addColorStop(0,'rgba(255,255,255,0.2)'); wg.addColorStop(1,'rgba(0,0,0,0.3)');
  ctx.fillStyle=col;
  ctx.beginPath(); ctx.roundRect(-w*0.5,-h*0.5,w,h*0.66,4); ctx.fill();
  ctx.fillStyle=wg;
  ctx.beginPath(); ctx.roundRect(-w*0.5,-h*0.5,w,h*0.66,4); ctx.fill();
  // Camouflage blobs
  ctx.fillStyle='rgba(40,55,30,0.45)';
  ctx.beginPath(); ctx.ellipse(-w*0.22,-h*0.28,w*0.14,h*0.16,0.5,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(w*0.1,-h*0.2,w*0.18,h*0.14,-0.3,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(w*0.32,-h*0.34,w*0.12,h*0.12,0.8,0,Math.PI*2); ctx.fill();
  // Machine gun mount on roof
  ctx.fillStyle='#222';
  ctx.fillRect(-w*0.06,-h*0.62,12,h*0.16);
  ctx.fillRect(-w*0.12,-h*0.62,w*0.24,6);
  ctx.fillRect(w*0.06,-h*0.54,w*0.2,5);
  // Windshield
  ctx.fillStyle='rgba(100,180,100,0.4)';
  ctx.beginPath();
  ctx.moveTo(-w*0.12,-h*0.44); ctx.lineTo(w*0.3,-h*0.44);
  ctx.lineTo(w*0.28,-h*0.08); ctx.lineTo(-w*0.1,-h*0.08);
  ctx.closePath(); ctx.fill();
  // Grille slats
  ctx.fillStyle='rgba(0,0,0,0.6)';
  for(let gi=0;gi<4;gi++){
    ctx.fillRect(w*0.42,-h*0.42+gi*h*0.1,w*0.12,h*0.06);
  }
  // Exhaust
  if(thr>0){
    ctx.fillStyle='rgba(80,80,50,0.5)';
    ctx.beginPath(); ctx.arc(-w*0.52,-h*0.22,6+Math.random()*4,0,Math.PI*2); ctx.fill();
  }
  ctx.restore();
}

function drawOffroader(ctx, def, v, thr, t) {
  const w = def.w||110, h = def.h||54;
  const col = def.color||'#882200';
  ctx.save();
  // Skid plate / armor under
  ctx.fillStyle='#1a1a1a';
  ctx.beginPath(); ctx.roundRect(-w*0.52,-h*0.06,w*1.04,h*0.22,3); ctx.fill();
  // Body
  const og=ctx.createLinearGradient(0,-h*0.54,0,h*0.22);
  og.addColorStop(0,'rgba(255,255,255,0.32)'); og.addColorStop(1,'rgba(0,0,0,0.22)');
  ctx.fillStyle=col;
  ctx.beginPath(); ctx.roundRect(-w*0.48,-h*0.54,w*0.96,h*0.6,5); ctx.fill();
  ctx.fillStyle=og;
  ctx.beginPath(); ctx.roundRect(-w*0.48,-h*0.54,w*0.96,h*0.6,5); ctx.fill();
  // Windshield
  ctx.fillStyle='rgba(120,200,255,0.45)';
  ctx.beginPath();
  ctx.moveTo(-w*0.26,-h*0.5); ctx.lineTo(w*0.32,-h*0.5);
  ctx.lineTo(w*0.30,-h*0.08); ctx.lineTo(-w*0.24,-h*0.08);
  ctx.closePath(); ctx.fill();
  // WIKI(3 Agu): PALET (tracked) — wiki "this tracked vehicle" diyor. Çamurluk yerine
  //   makaraların üstünden geçen palet zinciri + üçgen palet ünitesi çizilir.
  //   4 küçük makara VehicleDefs'ten gelir ve drawVehicle tarafından zaten çizilmiştir.
  {
    const wl = def.wheels || [];
    if (wl.length >= 3) {
      const xs = wl.map(q => q.x), r0 = wl[0].r || 14, y0 = wl[0].y || 26;
      const x1 = Math.min.apply(null, xs), x2 = Math.max.apply(null, xs);
      // 🔴 PNG kanıtı: ilk sürümde palet ünitesi ÜÇGEN bir blok olarak makaraların
      //   ÜSTÜNE taşıyordu (y0-r0-6 = +6) ve gövdeyi yutuyordu — araç tek siyah
      //   leke gibi görünüyordu. Artık band YALNIZCA makaraları sarar (üst kenar
      //   y0-r0), yani gövdenin altında kalır; ayrıca rengi açıldı.
      const yUst = y0 - r0, yAlt = y0 + r0;
      // Palet kayışı — makaraları saran kapalı bant (uçları yuvarlak)
      ctx.fillStyle = '#2b2f34';
      ctx.beginPath();
      ctx.moveTo(x1, yUst - 3); ctx.lineTo(x2, yUst - 3);
      ctx.arc(x2, y0, r0 + 3, -Math.PI / 2, Math.PI / 2);
      ctx.lineTo(x1, yAlt + 3);
      ctx.arc(x1, y0, r0 + 3, Math.PI / 2, Math.PI * 1.5);
      ctx.closePath(); ctx.fill();
      // Palet dişleri (gaz/tekere göre kayar → hareket hissi)
      ctx.strokeStyle = 'rgba(170,175,182,0.55)'; ctx.lineWidth = 2;
      const kay = (((v && v.wheels && v.wheels[0] ? v.wheels[0].spin : 0) * 9) % 9 + 9) % 9;
      for (let p = x1 - r0; p < x2 + r0; p += 9) {
        const px = p + kay;
        ctx.beginPath(); ctx.moveTo(px, yAlt - 1); ctx.lineTo(px, yAlt + 3); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(px, yUst - 3); ctx.lineTo(px, yUst + 1); ctx.stroke();
      }
      // Tahrik dişlileri (uçlarda) + orta makara göbekleri
      ctx.fillStyle = '#4a5058';
      ctx.beginPath(); ctx.arc(x1, y0, r0 * 0.72, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(x2, y0, r0 * 0.72, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#8c939b'; ctx.lineWidth = 1.5;
      for (const q of wl) { ctx.beginPath(); ctx.arc(q.x, y0, r0 * 0.42, 0, Math.PI * 2); ctx.stroke(); }
      // Palet ünitesini şasiye bağlayan kol
      ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = 4;
      ctx.beginPath(); ctx.moveTo(x1 + 6, yUst - 2); ctx.lineTo(x2 - 6, yUst - 2); ctx.stroke();
    }
  }
  // Roof lights bar
  ctx.fillStyle='#111';
  ctx.fillRect(-w*0.4,-h*0.6,w*0.8,6);
  ctx.fillStyle='rgba(255,220,100,0.9)';
  for(let li=0;li<4;li++){
    ctx.beginPath(); ctx.arc(-w*0.3+li*w*0.2,-h*0.57,3,0,Math.PI*2); ctx.fill();
  }
  // Door handles
  ctx.fillStyle='rgba(0,0,0,0.5)';
  ctx.fillRect(-w*0.08,-h*0.3,w*0.18,4);
  // Grille mesh
  ctx.fillStyle='#111';
  ctx.beginPath(); ctx.roundRect(w*0.44,-h*0.36,w*0.06,h*0.3,2); ctx.fill();
  ctx.strokeStyle='rgba(80,80,80,0.6)'; ctx.lineWidth=1;
  for(let g2=0;g2<3;g2++){
    ctx.beginPath(); ctx.moveTo(w*0.44,-h*0.3+g2*8); ctx.lineTo(w*0.5,-h*0.3+g2*8); ctx.stroke();
  }
  ctx.restore();
}

function drawCybertruck(ctx, def, v, thr, t) {
  const w = def.w||115, h = def.h||50;
  const col = def.color||'#c0c0c0';
  ctx.save();
  // Mirror/chrome effect
  const mg=ctx.createLinearGradient(-w*0.5,-h*0.5,w*0.5,h*0.3);
  mg.addColorStop(0,'#e8e8e8'); mg.addColorStop(0.3,'#c0c0c0'); mg.addColorStop(0.6,'#e0e0e0'); mg.addColorStop(1,'#888');
  ctx.fillStyle=mg;
  // Angular polygonal body - no curves
  ctx.beginPath();
  ctx.moveTo(-w*0.52,h*0.18);
  ctx.lineTo(-w*0.5,-h*0.06);
  ctx.lineTo(-w*0.15,-h*0.48);
  ctx.lineTo(w*0.38,-h*0.48);
  ctx.lineTo(w*0.52,-h*0.06);
  ctx.lineTo(w*0.52,h*0.18);
  ctx.closePath(); ctx.fill();
  // Truck bed (flat back)
  ctx.fillStyle='#aaa';
  ctx.beginPath();
  ctx.moveTo(-w*0.52,h*0.18);
  ctx.lineTo(-w*0.5,-h*0.06);
  ctx.lineTo(-w*0.14,-h*0.06);
  ctx.lineTo(-w*0.14,h*0.18);
  ctx.closePath(); ctx.fill();
  // Windshield single flat pane
  ctx.fillStyle='rgba(120,200,255,0.4)';
  ctx.beginPath();
  ctx.moveTo(-w*0.14,-h*0.46); ctx.lineTo(w*0.38,-h*0.46);
  ctx.lineTo(w*0.5,-h*0.06); ctx.lineTo(-w*0.14,-h*0.06);
  ctx.closePath(); ctx.fill();
  // Edge lines
  ctx.strokeStyle='rgba(255,255,255,0.4)'; ctx.lineWidth=1;
  ctx.beginPath();
  ctx.moveTo(-w*0.52,h*0.18); ctx.lineTo(-w*0.5,-h*0.06);
  ctx.lineTo(-w*0.15,-h*0.48); ctx.lineTo(w*0.38,-h*0.48);
  ctx.lineTo(w*0.52,-h*0.06); ctx.lineTo(w*0.52,h*0.18);
  ctx.stroke();
  // LED strip headlights
  ctx.fillStyle='rgba(150,220,255,0.95)';
  ctx.fillRect(w*0.46,-h*0.24,w*0.07,3);
  ctx.fillStyle='rgba(255,60,60,0.9)';
  ctx.fillRect(-w*0.53,-h*0.24,w*0.07,3);
  // Tesla T logo
  ctx.fillStyle='rgba(255,0,0,0.8)'; ctx.font='bold 9px Arial'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText('T',w*0.2,-h*0.27);
  // Electric charge effect
  if(thr>0){
    ctx.save();
    ctx.shadowColor='rgba(0,200,255,0.8)'; ctx.shadowBlur=15;
    ctx.strokeStyle='rgba(0,200,255,0.5)'; ctx.lineWidth=1;
    ctx.beginPath();
    ctx.moveTo(-w*0.52,h*0.18); ctx.lineTo(-w*0.5,-h*0.06);
    ctx.lineTo(-w*0.15,-h*0.48); ctx.lineTo(w*0.38,-h*0.48);
    ctx.lineTo(w*0.52,-h*0.06); ctx.lineTo(w*0.52,h*0.18);
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();
}

function drawWheel(ctx, wheel, vehicleId, idx, def, animTime) {
  if (!wheel) return;
  if (wheel.isSki) {
    ctx.save(); ctx.translate(wheel.x, wheel.y);
    ctx.fillStyle='#c8d8ff';
    ctx.beginPath(); ctx.moveTo(-20,2); ctx.lineTo(20,2); ctx.lineTo(24,8); ctx.lineTo(-22,8); ctx.closePath(); ctx.fill();
    ctx.strokeStyle='#88aacc'; ctx.lineWidth=1.5; ctx.stroke();
    ctx.restore(); return;
  }
  if (wheel.isHover) {
    ctx.save(); ctx.translate(wheel.x, wheel.y);
    ctx.fillStyle='rgba(0,191,255,0.5)';
    ctx.beginPath(); ctx.ellipse(0,0,wheel.radius*2,wheel.radius,0,0,Math.PI*2); ctx.fill();
    ctx.restore(); return;
  }
  if (wheel.isLeg) {
    ctx.save(); ctx.translate(wheel.x, wheel.y);
    ctx.fillStyle='#888'; ctx.fillRect(-10,-3,20,6);
    ctx.restore(); return;
  }

  ctx.save();
  ctx.translate(wheel.x, wheel.y);
  ctx.rotate(wheel.spin || 0);

  const r = wheel.radius;
  // Tire color / tread
  const rimColors = {
    jeep:'#c8c8c8', motocross:'#e0e0e0', monster:'#888', racecar:'#e0e0e0',
    tractor:'#a07838', superdiesel:'#aaa', formula:'#ccc', dunebuggy:'#c8a84a',
    chopper:'#888', tank:'#6a8a4a', loader:'#FFD700', supercar:'#ddd', default:'#aaa'
  };
  const rim = rimColors[vehicleId] || rimColors.default;

  // Tire
  ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.fillStyle='#1a1a1a'; ctx.fill();
  ctx.strokeStyle='#333'; ctx.lineWidth=r*0.08; ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.stroke();

  // Tread grooves for big tires
  if (vehicleId==='monster' || vehicleId==='tractor' || vehicleId==='atv' || vehicleId==='dunebuggy') {
    ctx.strokeStyle='#333'; ctx.lineWidth=2.5;
    for (let kn=0; kn<8; kn++) {
      const ka = kn/8*Math.PI*2;
      ctx.beginPath(); ctx.arc(0,0,r-2,ka,ka+0.22); ctx.stroke();
    }
  }

  // Rim
  ctx.beginPath(); ctx.arc(0,0,r*0.62,0,Math.PI*2); ctx.fillStyle=rim; ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,0.2)'; ctx.lineWidth=1.5; ctx.beginPath(); ctx.arc(0,0,r*0.62,0,Math.PI*2); ctx.stroke();

  // Spokes
  ctx.strokeStyle=rim; ctx.lineWidth=2.5;
  const spokeCount = (vehicleId==='formula'||vehicleId==='racecar'||vehicleId==='supercar') ? 6 : 5;
  for (let sp=0; sp<spokeCount; sp++) {
    const sa2 = sp/spokeCount*Math.PI*2;
    ctx.beginPath();
    ctx.moveTo(Math.cos(sa2)*r*0.13, Math.sin(sa2)*r*0.13);
    ctx.lineTo(Math.cos(sa2)*r*0.58, Math.sin(sa2)*r*0.58);
    ctx.stroke();
  }

  // Center cap
  ctx.beginPath(); ctx.arc(0,0,r*0.16,0,Math.PI*2);
  ctx.fillStyle='#444'; ctx.fill();

  // Brake disc glow when braking (contact)
  if (wheel.contact && vehicleId === 'racecar') {
    ctx.fillStyle='rgba(255,80,0,0.25)';
    ctx.beginPath(); ctx.arc(0,0,r*0.4,0,Math.PI*2); ctx.fill();
  }

  ctx.restore();
}

// ── Master Draw Dispatcher ─────────────────────────────────────────────────
// ── YENİ ARAÇLAR ───────────────────────────────────────────────────────────
function drawJetSki(ctx, def, v, thr, t) {
  var c1 = def.color || '#00b3d6', c2 = def.color2 || '#ff2e63';
  // Su spreyi (arka) — gaza göre yoğunlaşan katmanlı sprey
  var jet = 0.4 + thr * 0.6;
  ctx.save();
  for (var i = 0; i < 6; i++) {
    ctx.fillStyle = 'rgba(200,240,255,' + (0.5 - i*0.06) + ')';
    var sy = 16 - Math.sin(t*10 + i)*4 + (i%2?3:-2);
    ctx.beginPath(); ctx.arc(-50 - i*7*jet, sy, (5 - i*0.6)*jet, 0, Math.PI*2); ctx.fill();
  }
  ctx.restore();
  // Rooster tail (arka su kuyruğu)
  ctx.fillStyle = 'rgba(220,245,255,0.4)';
  ctx.beginPath(); ctx.moveTo(-46, 12); ctx.quadraticCurveTo(-72, 2 - Math.sin(t*8)*4, -84, 18); ctx.quadraticCurveTo(-64, 20, -46, 18); ctx.closePath(); ctx.fill();
  // Gövde (aerodinamik hull)
  var bg = ctx.createLinearGradient(0, -14, 0, 18);
  bg.addColorStop(0, _shade(c1, 0.45)); bg.addColorStop(0.5, c1); bg.addColorStop(1, c2);
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-52, 10); ctx.quadraticCurveTo(-58, -2, -40, -6);
  ctx.lineTo(30, -6); ctx.quadraticCurveTo(62, -4, 58, 14);
  ctx.lineTo(-40, 18); ctx.closePath(); ctx.fill();
  // Hull alt gölge (su hattı)
  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.beginPath(); ctx.moveTo(-40, 18); ctx.lineTo(58, 14); ctx.quadraticCurveTo(40, 20, -40, 20); ctx.closePath(); ctx.fill();
  // Üst parlama (fiberglas glare)
  var glare = ctx.createLinearGradient(0, -6, 0, 4);
  glare.addColorStop(0, 'rgba(255,255,255,0.4)'); glare.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = glare;
  ctx.beginPath(); ctx.moveTo(-38, -5); ctx.lineTo(28, -5); ctx.quadraticCurveTo(50, -3, 40, 2); ctx.lineTo(-38, 2); ctx.closePath(); ctx.fill();
  // Ön kaput yükseltisi
  var hg = ctx.createLinearGradient(0, -24, 0, -6);
  hg.addColorStop(0, _shade(c1, 0.4)); hg.addColorStop(1, _shade(c1, 0.05));
  ctx.fillStyle = hg;
  ctx.beginPath(); ctx.moveTo(-6, -6); ctx.quadraticCurveTo(-10, -24, 10, -22); ctx.quadraticCurveTo(30, -20, 30, -6); ctx.closePath(); ctx.fill();
  // Kaput hava girişi (grill)
  ctx.strokeStyle = 'rgba(0,0,0,0.4)'; ctx.lineWidth = 1.4;
  for (var gv = 0; gv < 3; gv++) { ctx.beginPath(); ctx.moveTo(6 + gv*6, -20); ctx.lineTo(6 + gv*6, -8); ctx.stroke(); }
  // Krom rub-rail (yan bordür)
  var rr = ctx.createLinearGradient(0, 8, 0, 13);
  rr.addColorStop(0, '#f2f2f2'); rr.addColorStop(0.5, '#b0b0b0'); rr.addColorStop(1, '#707070');
  ctx.fillStyle = rr; ctx.beginPath(); ctx.moveTo(-46, 9); ctx.lineTo(54, 11); ctx.lineTo(54, 13); ctx.lineTo(-46, 12); ctx.closePath(); ctx.fill();
  // Koltuk minderi
  ctx.fillStyle = _shade(c2, -0.35); ctx.beginPath(); ctx.roundRect(-40, -8, 34, 8, 3); ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.3)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-30, -8); ctx.lineTo(-30, 0); ctx.moveTo(-18, -8); ctx.lineTo(-18, 0); ctx.stroke();
  // Gidon
  ctx.strokeStyle = '#111'; ctx.lineWidth = 3.5; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(0, -22); ctx.lineTo(-14, -30); ctx.moveTo(0, -22); ctx.lineTo(14, -30); ctx.stroke();
  // Gidon grip uçları
  ctx.fillStyle = c2; ctx.beginPath(); ctx.arc(-14, -30, 3, 0, Math.PI*2); ctx.arc(14, -30, 3, 0, Math.PI*2); ctx.fill();
  ctx.lineCap = 'butt';
  // Şerit (çift renk)
  ctx.strokeStyle = _shade(c2, 0.35); ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(-40, 4); ctx.lineTo(50, 6); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,0.6)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-40, 2); ctx.lineTo(50, 4); ctx.stroke();
  // --- Additive polish: hull sweep glint, chrome rub-rail sheen, waterline sparkle ---
  ctx.save();
  // Sweeping fiberglass specular glint (idle life)
  var jsgx = 6 + Math.sin(t*1.8)*20;
  ctx.fillStyle = 'rgba(255,255,255,0.20)';
  ctx.beginPath(); ctx.ellipse(jsgx,-2,11,3,-0.15,0,Math.PI*2); ctx.fill();
  // Chrome rub-rail top highlight
  ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-46,10); ctx.lineTo(54,12); ctx.stroke();
  // Waterline sparkle glints (idle bob)
  ctx.fillStyle = 'rgba(255,255,255,'+(0.3+0.3*Math.abs(Math.sin(t*3))).toFixed(2)+')';
  ctx.beginPath(); ctx.arc(20,19,1.4,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(-10,20,1.2,0,Math.PI*2); ctx.fill();
  ctx.restore();
  _driver(ctx, -18, -20, '#ffffff', c2, t);
}

