  for (var rv = 0; rv < 6; rv++) { ctx.beginPath(); ctx.arc(2 + rv*8, -16, 1.4, 0, Math.PI*2); ctx.fill(); }
  ctx.strokeStyle = _shade(c1, 0.4); ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(-6, -6); ctx.lineTo(50, -6); ctx.stroke();
  // Motor kaputu (ön silindir üstü) — pirinç kazan
