  kg.addColorStop(0, _shade(c1, 0.4)); kg.addColorStop(0.5, _shade(c1, 0.1)); kg.addColorStop(1, _shade(c1, -0.2));
  ctx.fillStyle = kg; ctx.beginPath(); ctx.roundRect(-56, -14, 44, 22, 6); ctx.fill();
  // Kazan bantları (pirinç halkalar)
  ctx.strokeStyle = '#c8952e'; ctx.lineWidth = 2.5;
  for (var bd = 0; bd < 3; bd++) { ctx.beginPath(); ctx.moveTo(-50 + bd*14, -14); ctx.lineTo(-50 + bd*14, 8); ctx.stroke(); }
  ctx.strokeStyle = 'rgba(255,240,180,0.6)'; ctx.lineWidth = 0.8;
  for (var bd2 = 0; bd2 < 3; bd2++) { ctx.beginPath(); ctx.moveTo(-51 + bd2*14, -14); ctx.lineTo(-51 + bd2*14, 8); ctx.stroke(); }
  // Basınç göstergesi (gauge)
  ctx.fillStyle = '#d8d8d8'; ctx.beginPath(); ctx.arc(-14, -2, 4, 0, Math.PI*2); ctx.fill();
  ctx.strokeStyle = '#333'; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(-14, -2, 4, 0, Math.PI*2); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-14, -2); ctx.lineTo(-12, -4.5); ctx.stroke();
  // Baca (pirinç ağız)
  ctx.fillStyle = '#333'; ctx.fillRect(-46, -30, 8, 16);
  ctx.fillStyle = '#c8952e'; ctx.fillRect(-47, -32, 10, 4);
  // Duman — gaza göre
  var smk = 0.4 + thr * 0.4;
  ctx.fillStyle = 'rgba(120,120,120,' + smk + ')';
  for (var i = 0; i < 4; i++) { ctx.beginPath(); ctx.arc(-42 + Math.sin(t*3+i)*3, -34 - i*8, 4 + i*2, 0, Math.PI*2); ctx.fill(); }
