  wg.addColorStop(0, '#d6efff'); wg.addColorStop(1, '#5b86a8');
  ctx.fillStyle = '#111'; ctx.beginPath(); ctx.roundRect(48.5, -41.5, 29, 21, 3); ctx.fill();
  ctx.fillStyle = wg; ctx.beginPath(); ctx.roundRect(50, -40, 26, 18, 3); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.3)'; ctx.beginPath(); ctx.moveTo(52,-38); ctx.lineTo(60,-38); ctx.lineTo(53,-24); ctx.lineTo(50,-24); ctx.closePath(); ctx.fill();
  // Su tankı / pompa panosu (arka)
  ctx.fillStyle = '#b0b0b0'; ctx.beginPath(); ctx.arc(-30, 2, 5, 0, Math.PI*2); ctx.fill();
  ctx.strokeStyle = '#555'; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(-30, 2, 5, 0, Math.PI*2); ctx.stroke();
  ctx.strokeStyle = '#333'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(-30,2); ctx.lineTo(-27,-1); ctx.stroke();
