  ctx.strokeStyle = '#c0c0c0'; ctx.lineWidth = 2;
  for (var i = 0; i < 8; i++) { ctx.beginPath(); ctx.moveTo(-66 + i * 11, -30); ctx.lineTo(-66 + i * 11, -42); ctx.stroke(); }
  // tepe lamba çubuğu (light bar) — kırmızı yanıp söner
