  ctx.save(); ctx.shadowColor = '#ff2200'; ctx.shadowBlur = 12;
  ctx.fillStyle = (Math.sin(t * 10) > 0) ? '#ff3322' : '#661010'; ctx.fillRect(48, -49, 8, 4);
  ctx.fillStyle = (Math.sin(t * 10) > 0) ? '#661010' : '#ff3322'; ctx.fillRect(60, -49, 8, 4); ctx.restore();
