  ctx.fillStyle = '#2a2a30'; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('7', 26, 1);
  // Şişkin lastik tampon halkası
  ctx.strokeStyle = _shade(c2, -0.05); ctx.lineWidth = 9; ctx.lineCap = 'round';
