  ctx.beginPath(); ctx.moveTo(30, -8); ctx.lineTo(30, 8); ctx.stroke();
  // Vinç direği (dik kolon)
  ctx.fillStyle = c2; ctx.fillRect(4, -44, 8, 40);
  // Vinç kolu (arkaya uzanan diyagonal)
