  ctx.beginPath(); ctx.moveTo(8, -42); ctx.lineTo(-58, -22); ctx.stroke();
  ctx.strokeStyle = _shade(c1, 0.2); ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(8, -44); ctx.lineTo(-58, -24); ctx.stroke();
  ctx.restore();
  // Makara + kanca kablosu
  ctx.strokeStyle = '#555'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(-58, -22); ctx.lineTo(-58, -2); ctx.stroke();
  // Kanca
  ctx.strokeStyle = '#888'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.arc(-58, 2, 5, Math.PI*0.2, Math.PI*1.7); ctx.stroke();
  // Tepe sarı lamba
  ctx.save(); ctx.shadowColor = '#ffcc00'; ctx.shadowBlur = 9;
  ctx.fillStyle = (Math.sin(t * 9) > 0) ? '#ffd21e' : '#7a5a10'; ctx.fillRect(34, -38, 12, 5); ctx.restore();
  // Far + stop
