  bg.addColorStop(0, _shade(c1, 0.35)); bg.addColorStop(0.55, c1); bg.addColorStop(1, _shade(c1, -0.28));
  ctx.fillStyle = bg; ctx.beginPath(); ctx.roundRect(-46, -22, 78, 42, [8,4,4,8]); ctx.fill();
  // Motor kaputu eğimi
