  ctx.fillStyle = c2; ctx.beginPath(); ctx.arc(0,-2,9,0,6.28); ctx.fill();
  ctx.fillStyle = '#e0a01a'; ctx.beginPath(); ctx.moveTo(0,-2); ctx.lineTo(-7,4); ctx.lineTo(7,4); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#c0402a'; ctx.beginPath(); ctx.arc(-2,1,1.4,0,6.28); ctx.fill(); ctx.beginPath(); ctx.arc(3,2,1.4,0,6.28); ctx.fill();
  if (thr<0.5){ ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(-4,-16); ctx.quadraticCurveTo(-7,-22+Math.sin(t*3)*2,-4,-28); ctx.moveTo(4,-16); ctx.quadraticCurveTo(7,-22+Math.cos(t*3)*2,4,-28); ctx.stroke(); }
