  var sa = v.suspAnim || [0,0], wd = def.wheels;
  if (wd) wd.forEach(function(w, i){ var c = sa[i]||0; _drawSusp(ctx, w.x, 4, w.x, w.y*(1-c*0.3), c); });
  // Wheel arches
