  ctx.beginPath(); ctx.roundRect(-54, -38, 40, 20, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-10, -38, 30, 20, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(26, -36, 26, 16, [4,8,4,4]); ctx.fill();
  // Window pillars
  ctx.fillStyle = c2; ctx.fillRect(-14, -38, 4, 20); ctx.fillRect(22, -38, 4, 20);
  // Chrome bumpers
  var chg = ctx.createLinearGradient(0,14,0,22); chg.addColorStop(0,'#eee'); chg.addColorStop(1,'#888');
  ctx.fillStyle = chg; ctx.beginPath(); ctx.roundRect(48, 12, 16, 8, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-64, 12, 16, 8, 3); ctx.fill();
