  // Round front badge with V emblem
  ctx.fillStyle = c2; ctx.beginPath(); ctx.arc(48, -2, 8, 0, Math.PI*2); ctx.fill();
  ctx.strokeStyle = _shade(c1,-0.2); ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(48, -2, 8, 0, Math.PI*2); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(44,-6); ctx.lineTo(48,2); ctx.lineTo(52,-6); ctx.stroke();
  // Roof rack with luggage
  ctx.strokeStyle = '#5a4a34'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-52, -44); ctx.lineTo(30, -44); ctx.stroke();
  ctx.fillStyle = '#8a6a44'; ctx.beginPath(); ctx.roundRect(-40, -50, 24, 8, 2); ctx.fill();
  ctx.fillStyle = '#b03a3a'; ctx.beginPath(); ctx.roundRect(-10, -49, 16, 7, 2); ctx.fill();
  // Trim line + door handle
  ctx.strokeStyle = _shade(c1,-0.4); ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(-58, 4); ctx.lineTo(58, 4); ctx.stroke();
  ctx.fillStyle = '#333'; ctx.fillRect(-8, -4, 8, 2);
  // Taillight + exhaust
  _taillight(ctx, -62, 2, 5);
  ctx.fillStyle = '#777'; ctx.beginPath(); ctx.roundRect(-60, 16, 10, 4, 2); ctx.fill();
  _exhaustFlame(ctx, -60, 18, thr, t, 0.5);
  // Driver behind the windscreen
  _driver(ctx, 34, -18, c1, _shade(c2,-0.2), t);
