  ctx.beginPath(); ctx.moveTo(28,-34); ctx.lineTo(40,-34); ctx.lineTo(30,-22); ctx.lineTo(24,-22); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(230,230,210,0.7)'; ctx.lineWidth = 1.5;
