// ============================================================
// drawExhaustSmoke — render exhaust particles on canvas
// ============================================================
function drawExhaustSmoke(ctx, vehicle, vehicleId, t) {
  const anim = VehicleAnimationParams[vehicleId];
  if (!anim || anim.exhaustPuffInterval <= 0) return;

  const speed = Math.sqrt((vehicle.vx || 0) ** 2 + (vehicle.vy || 0) ** 2);
  const intensity = Math.min(1.0, speed / 200);
  const puffCount = Math.floor(2 + intensity * 6);

  ctx.save();
  ctx.translate(vehicle.x + anim.exhaustPuffOffset.x, vehicle.y + anim.exhaustPuffOffset.y);
  ctx.rotate(vehicle.angle || 0);

  for (let i = 0; i < puffCount; i++) {
    const age = ((t + i * anim.exhaustPuffInterval) % (anim.exhaustPuffInterval * puffCount))
                 / (anim.exhaustPuffInterval * puffCount);
    const radius   = 3 + age * 12;
    const alpha    = (1 - age) * 0.35 * intensity;
    const offsetX  = -age * 25;
    const offsetY  = -age * 8 + Math.sin(t * 3 + i) * 4;
    const grayVal  = Math.floor(180 + age * 60);

    ctx.beginPath();
    ctx.arc(offsetX, offsetY, radius, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(${grayVal},${grayVal},${grayVal},${alpha.toFixed(3)})`;
    ctx.fill();
  }
  ctx.restore();
}

// ============================================================
// drawVehicleShadow — soft drop shadow beneath vehicle
// ============================================================
function drawVehicleShadow(ctx, vehicle, vehicleId) {
  const shadowScaleX = 1.2;
  const shadowScaleY = 0.25;
  const shadowAlpha  = 0.22;

  ctx.save();
  ctx.translate(vehicle.x, vehicle.y + (vehicle.height || 20));
  ctx.rotate(vehicle.angle || 0);
  ctx.scale(shadowScaleX, shadowScaleY);

  const grad = ctx.createRadialGradient(0, 0, 4, 0, 0, (vehicle.width || 60) * 0.55);
  grad.addColorStop(0, `rgba(0,0,0,${shadowAlpha})`);
  grad.addColorStop(1, 'rgba(0,0,0,0)');

  ctx.beginPath();
  ctx.ellipse(0, 0, (vehicle.width || 60) * 0.55, (vehicle.height || 20) * 0.55, 0, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.restore();
}

// ============================================================
// drawVehicleDamage — visualise damage level 0.0–1.0
// ============================================================
function drawVehicleDamage(ctx, vehicle, vehicleId, damageLevel) {
  if (!damageLevel || damageLevel <= 0) return;
  const clampedDmg = Math.min(1.0, Math.max(0.0, damageLevel));

  ctx.save();
  ctx.translate(vehicle.x, vehicle.y);
  ctx.rotate(vehicle.angle || 0);

  // Body dent overlay
  if (clampedDmg > 0.1) {
    const dentAlpha = (clampedDmg - 0.1) * 0.6;
    ctx.fillStyle = `rgba(80,40,10,${dentAlpha.toFixed(3)})`;
    const w = vehicle.width || 60;
    const h = vehicle.height || 25;
    // scatter dent patches
    const dentCount = Math.floor(clampedDmg * 8);
    for (let i = 0; i < dentCount; i++) {
      const dx = (Math.sin(i * 137.5) * 0.5) * w;
      const dy = (Math.cos(i * 97.3)  * 0.5) * h * 0.6;
      const dr = 3 + clampedDmg * 6;
      ctx.beginPath();
      ctx.ellipse(dx, dy, dr, dr * 0.6, i, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // Smoke wisps when heavily damaged
  if (clampedDmg > 0.5) {
    const smokeAlpha = (clampedDmg - 0.5) * 0.7;
    ctx.fillStyle = `rgba(60,60,60,${smokeAlpha.toFixed(3)})`;
    const t = Date.now() / 1000;
    for (let s = 0; s < 3; s++) {
      const sx = (s - 1) * 15;
      const sy = -15 - Math.abs(Math.sin(t * 1.5 + s)) * 10;
      ctx.beginPath();
      ctx.arc(sx, sy, 6 + s * 2, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // Fire glow when critical
  if (clampedDmg > 0.8) {
    const fireAlpha = (clampedDmg - 0.8) * 1.5;
    const t = Date.now() / 1000;
    const fireGrad = ctx.createRadialGradient(0, -10, 2, 0, -10, 18);
    fireGrad.addColorStop(0,   `rgba(255,200,0,${(fireAlpha * 0.9).toFixed(3)})`);
    fireGrad.addColorStop(0.5, `rgba(255,80,0,${(fireAlpha * 0.6).toFixed(3)})`);
    fireGrad.addColorStop(1,   'rgba(200,0,0,0)');
    ctx.beginPath();
    ctx.ellipse(0, -10 + Math.sin(t * 8) * 2, 12, 16, 0, 0, Math.PI * 2);
    ctx.fillStyle = fireGrad;
    ctx.fill();
  }

  ctx.restore();
}

// ============================================================
// getVehicleHandling — returns handling config for vehicleId
// ============================================================
function getVehicleHandling(vehicleId) {
  const defaults = {
    steerSpeed: 2.5, steerReturn: 0.12, maxLean: 0.35,
    throttleResponse: 0.9, brakeForce: 1.0,
    airControl: 0.4, flipTorque: 1.8,
    groundStick: 1.0, wheelieThreshold: 0.7,
  };

  const overrides = {
    motorbike:   { steerSpeed: 4.0, maxLean: 0.55, airControl: 0.7, wheelieThreshold: 0.5, groundStick: 0.7 },
    truck:       { steerSpeed: 1.2, steerReturn: 0.06, maxLean: 0.18, brakeForce: 1.4, groundStick: 1.4 },
    formula:     { steerSpeed: 5.0, steerReturn: 0.20, maxLean: 0.28, throttleResponse: 1.5, brakeForce: 1.8 },
    hovercar:    { steerSpeed: 3.5, maxLean: 0.40, airControl: 0.9, groundStick: 0.3, wheelieThreshold: 0.9 },
    cybertruck:  { steerSpeed: 2.0, maxLean: 0.22, brakeForce: 1.3, throttleResponse: 1.1, groundStick: 1.2 },
    hovercraft:  { steerSpeed: 1.8, maxLean: 0.10, airControl: 1.0, groundStick: 0.05, brakeForce: 0.4 },
    mech_walker: { steerSpeed: 0.9, maxLean: 0.50, airControl: 0.2, flipTorque: 2.5, groundStick: 1.8 },
    submarine:   { steerSpeed: 0.6, maxLean: 0.08, airControl: 0.05, brakeForce: 0.6, throttleResponse: 0.4 },
    skateboard:  { steerSpeed: 6.0, maxLean: 0.65, airControl: 0.8, groundStick: 0.5, wheelieThreshold: 0.3 },
    horse_cart:  { steerSpeed: 1.5, maxLean: 0.30, throttleResponse: 0.5, brakeForce: 0.7, flipTorque: 1.2 },
    spaceship:   { steerSpeed: 5.5, maxLean: 0.15, airControl: 1.5, groundStick: 0.1, throttleResponse: 2.0 },
    tank:        { steerSpeed: 0.7, maxLean: 0.12, brakeForce: 2.0, groundStick: 2.0, throttleResponse: 0.6 },
    rickshaw:    { steerSpeed: 3.0, maxLean: 0.42, airControl: 0.5, groundStick: 0.75, wheelieThreshold: 0.6 },
    ice_bike:    { steerSpeed: 3.8, maxLean: 0.50, airControl: 0.6, groundStick: 0.45, brakeForce: 0.5 },
    swamp_buggy: { steerSpeed: 2.2, maxLean: 0.28, brakeForce: 1.1, groundStick: 1.3, throttleResponse: 0.8 },
  };

  return Object.assign({}, defaults, overrides[vehicleId] || {});
}

