// ============================================================
// calcVehicleRating — composite performance rating 0-100
// ============================================================
function calcVehicleRating(vehicleId, upgradeLevels) {
  const def = (typeof VehicleDefs !== 'undefined') ? VehicleDefs[vehicleId] : null;
  if (!def || !def.stats) return 50;
  const s = def.stats;
  const base = (s.topSpeed || 0) * 0.25 + (s.acceleration || 0) * 30
             + (s.handling || 0) * 20   + (s.durability || 0) * 15;
  let bonus = 0;
  if (upgradeLevels) {
    const tree = VEHICLE_UPGRADE_TREES[vehicleId];
    if (tree) {
      Object.keys(upgradeLevels).forEach(cat => {
        bonus += Math.max(0, (upgradeLevels[cat] || 1) - 1) * 2;
      });
    }
  }
  return Math.min(100, Math.round(base * 0.35 + bonus));
}

// ============================================================
// getWheelPositions — resolve world-space wheel coordinates
// ============================================================
function getWheelPositions(vehicle, vehicleId) {
  const def = (typeof VehicleDefs !== 'undefined') ? VehicleDefs[vehicleId] : null;
  if (!def || !def.wheels) return [];
  const cx = vehicle.x || 0, cy = vehicle.y || 0, a = vehicle.angle || 0;
  const cosA = Math.cos(a), sinA = Math.sin(a);
  return def.wheels.map(w => ({
    x: cx + w.x * cosA - w.y * sinA,
    y: cy + w.x * sinA + w.y * cosA,
    r: w.r, localX: w.x, localY: w.y,
  }));
}

// ============================================================
// isVehicleUnlocked — check unlock conditions against playerStats
// ============================================================
function isVehicleUnlocked(vehicleId, playerStats) {
  const cond = VEHICLE_UNLOCK_CONDITIONS[vehicleId];
  if (!cond) return true;
  const dist = (playerStats && playerStats.totalDistance) || 0;
  const cups = (playerStats && playerStats.totalCups)     || 0;
  const rank = (playerStats && playerStats.rank)          || 0;
  return dist >= cond.distance || cups >= cond.cups || rank >= cond.rank;
}

// ============================================================
// getVehicleExhaustColor — colour tinted by engine temperature
// ============================================================
function getVehicleExhaustColor(vehicleId, engineTemp) {
  const BASE = {
    jeep:'#808080', motorbike:'#aaaaaa', truck:'#555555', formula:'#cccccc',
    hovercar:'#4499ff', cybertruck:'#00ffff', hovercraft:'#99ddff',
    mech_walker:'#666655', submarine:'#006688', skateboard:null,
    horse_cart:'#aaaaaa', spaceship:'#ff44ff', tank:'#445544',
    rickshaw:'#999988', ice_bike:'#ccddff', swamp_buggy:'#667755',
  };
  const base = BASE[vehicleId] || '#888888';
  if (!base) return null;
  const t = Math.min(1.0, Math.max(0.0, (engineTemp || 0) / 150));
  if (t < 0.5) return base;
  const r = parseInt(base.slice(1,3),16), g = parseInt(base.slice(3,5),16), b = parseInt(base.slice(5,7),16);
  const f = (t - 0.5) * 2;
  const hr = Math.min(255, r + Math.floor((255-r)*f));
  const hg = Math.max(0,   g - Math.floor(g * f));
  const hb = Math.max(0,   b - Math.floor(b * f));
  return '#' + hr.toString(16).padStart(2,'0') + hg.toString(16).padStart(2,'0') + hb.toString(16).padStart(2,'0');
}


