// ============================================================
// drawVehicleHUD — on-canvas speedometer/RPM gauge HUD
// ============================================================
function drawVehicleHUD(ctx, vehicle, vehicleId, canvasWidth, canvasHeight) {
  const speed    = Math.sqrt((vehicle.vx||0)**2 + (vehicle.vy||0)**2) * 0.1; // px/s to km/h approx
  const maxSpeed = (typeof VehicleDefs !== 'undefined' && VehicleDefs[vehicleId])
                   ? VehicleDefs[vehicleId].stats.topSpeed
                   : 200;
  const fuel     = vehicle.fuel !== undefined ? vehicle.fuel : 1.0;
  const damage   = vehicle.damage || 0;

  const hudX = canvasWidth  - 180;
  const hudY = canvasHeight - 130;

  ctx.save();
  ctx.globalAlpha = 0.80;

  // Speedometer background arc
  ctx.beginPath();
  ctx.arc(hudX + 70, hudY + 70, 60, Math.PI * 0.75, Math.PI * 2.25);
  ctx.strokeStyle = '#334455';
  ctx.lineWidth   = 12;
  ctx.stroke();

  // Speed fill arc
  const speedFrac  = Math.min(1.0, speed / maxSpeed);
  const startAngle = Math.PI * 0.75;
  const endAngle   = startAngle + speedFrac * Math.PI * 1.5;
  ctx.beginPath();
  ctx.arc(hudX + 70, hudY + 70, 60, startAngle, endAngle);
  const speedColor = speedFrac < 0.7 ? '#00dd55' : speedFrac < 0.9 ? '#ffaa00' : '#ff2200';
  ctx.strokeStyle = speedColor;
  ctx.lineWidth   = 12;
  ctx.stroke();

  // Speed text
  ctx.fillStyle   = '#ffffff';
  ctx.font        = 'bold 22px monospace';
  ctx.textAlign   = 'center';
  ctx.fillText(Math.floor(speed).toString(), hudX + 70, hudY + 75);
  ctx.font        = '11px sans-serif';
  ctx.fillText('km/h', hudX + 70, hudY + 92);

  // Fuel bar
  ctx.fillStyle = '#223344';
  ctx.fillRect(hudX, hudY + 140, 140, 12);
  ctx.fillStyle = fuel > 0.3 ? '#44bb44' : '#dd4422';
  ctx.fillRect(hudX, hudY + 140, 140 * fuel, 12);
  ctx.strokeStyle = '#445566';
  ctx.lineWidth   = 1;
  ctx.strokeRect(hudX, hudY + 140, 140, 12);

  // Damage indicator
  if (damage > 0) {
    const dw = 140 * damage;
    ctx.fillStyle = '#cc2200';
    ctx.fillRect(hudX, hudY + 158, dw, 8);
    ctx.strokeStyle = '#884400';
    ctx.strokeRect(hudX, hudY + 158, 140, 8);
  }

  ctx.restore();
}

// ============================================================
// drawWheelTrails — rubber trail marks on terrain
// ============================================================
function drawWheelTrails(ctx, trailPoints, vehicleId) {
  if (!trailPoints || trailPoints.length < 2) return;
  const colors = {
    jeep:        'rgba(60,40,20,',
    motorbike:   'rgba(40,40,40,',
    truck:       'rgba(80,50,20,',
    formula:     'rgba(30,30,30,',
    hovercar:    'rgba(0,150,220,',
    cybertruck:  'rgba(0,200,200,',
    hovercraft:  'rgba(200,240,255,',
    mech_walker: 'rgba(80,70,50,',
    submarine:   'rgba(0,100,140,',
    skateboard:  'rgba(50,50,50,',
    horse_cart:  'rgba(100,70,30,',
    spaceship:   'rgba(150,0,255,',
    tank:        'rgba(50,60,30,',
    rickshaw:    'rgba(70,60,40,',
    ice_bike:    'rgba(180,220,255,',
    swamp_buggy: 'rgba(50,80,30,',
  };
  const baseColor = colors[vehicleId] || 'rgba(50,50,50,';

  ctx.save();
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  for (let i = 1; i < trailPoints.length; i++) {
    const prev = trailPoints[i - 1];
    const curr = trailPoints[i];
    const age  = curr.age || 0;
    const alpha = Math.max(0, 0.5 - age * 0.08);
    if (alpha <= 0) continue;

    ctx.beginPath();
    ctx.moveTo(prev.x, prev.y);
    ctx.lineTo(curr.x, curr.y);
    ctx.strokeStyle = baseColor + alpha.toFixed(3) + ')';
    ctx.lineWidth   = curr.width || 4;
    ctx.stroke();
  }
  ctx.restore();
}

