// ============================================================
// getVehicleDescription — returns full desc string for UI
// ============================================================
function getVehicleDescription(vehicleId) {
  const lore = VEHICLE_LORE[vehicleId];
  if (!lore) return 'A mystery vehicle.';
  return [
    lore.name,
    lore.description,
    'Stats: ' + lore.statsFlavor,
    'Origin: ' + lore.origin,
    lore.unlockQuote,
  ].join('\n');
}

// ============================================================
// getVehicleSpecs — returns formatted spec sheet string
// ============================================================
function getVehicleSpecs(vehicleId) {
  const def = (typeof VehicleDefs !== 'undefined') ? VehicleDefs[vehicleId] : null;
  const mass = (typeof VEHICLE_MASS_TABLE !== 'undefined') ? VEHICLE_MASS_TABLE[vehicleId] : '?';
  const handling = getVehicleHandling(vehicleId);

  if (!def) return 'Unknown vehicle.';
  const s = def.stats || {};
  return [
    `Vehicle:      ${def.name || vehicleId}`,
    `Mass:         ${mass} kg`,
    `Top Speed:    ${s.topSpeed     || '?'} km/h`,
    `Acceleration: ${s.acceleration || '?'}`,
    `Handling:     ${s.handling     || '?'}`,
    `Durability:   ${s.durability   || '?'}`,
    `Steer Speed:  ${handling.steerSpeed}`,
    `Air Control:  ${handling.airControl}`,
    `Flip Torque:  ${handling.flipTorque}`,
  ].join('\n');
}


