// ============================================================
// getVehicleSummary — one-line summary for leaderboard display
// ============================================================
function getVehicleSummary(vehicleId) {
  const lore    = (typeof VEHICLE_LORE          !== 'undefined') ? VEHICLE_LORE[vehicleId]          : null;
  const unlock  = (typeof VEHICLE_UNLOCK_CONDITIONS !== 'undefined') ? VEHICLE_UNLOCK_CONDITIONS[vehicleId] : null;
  const sound   = (typeof VEHICLE_SOUNDS        !== 'undefined') ? VEHICLE_SOUNDS[vehicleId]        : null;
  const name    = lore   ? lore.name                  : vehicleId;
  const unlockD = unlock ? unlock.description         : 'always available';
  const pitch   = sound  ? `engine pitch ${sound.enginePitch}` : '';
  return `${name} | ${unlockD} | ${pitch}`;
}


