// ============================================================
// drawWheelVariant — alternatif jant çizici
// ============================================================
function drawWheelVariant(ctx, r, style, spin, t) {
  ctx.save();
  ctx.rotate(spin);
  switch (style) {
    case '7-spoke-alloy':
      for (let i = 0; i < 7; i++) {
        ctx.save();
        ctx.rotate((i / 7) * Math.PI * 2);
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(0, -r * 0.85);
        ctx.lineWidth = r * 0.13;
        ctx.strokeStyle = '#c0c0c0';
        ctx.stroke();
        ctx.restore();
      }
      break;
    case 'beadlock':
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.strokeStyle = '#555';
      ctx.lineWidth = r * 0.18;
      ctx.stroke();
      for (let i = 0; i < 12; i++) {
        const a = (i / 12) * Math.PI * 2;
        ctx.beginPath();
        ctx.arc(Math.cos(a) * r * 0.88, Math.sin(a) * r * 0.88, r * 0.06, 0, Math.PI * 2);
        ctx.fillStyle = '#888';
        ctx.fill();
      }
      break;
    case '6-spoke-chrome':
      for (let i = 0; i < 6; i++) {
        ctx.save();
        ctx.rotate((i / 6) * Math.PI * 2);
        const grad = ctx.createLinearGradient(0, 0, 0, -r * 0.9);
        grad.addColorStop(0, '#888');
        grad.addColorStop(0.5, '#eee');
        grad.addColorStop(1, '#aaa');
        ctx.beginPath();
        ctx.moveTo(-r * 0.08, 0);
        ctx.lineTo(-r * 0.04, -r * 0.9);
        ctx.lineTo(r * 0.04, -r * 0.9);
        ctx.lineTo(r * 0.08, 0);
        ctx.fillStyle = grad;
        ctx.fill();
        ctx.restore();
      }
      break;
    case '5-spoke-gold':
      for (let i = 0; i < 5; i++) {
        ctx.save();
        ctx.rotate((i / 5) * Math.PI * 2);
        const ggrad = ctx.createLinearGradient(0, 0, 0, -r * 0.88);
        ggrad.addColorStop(0, '#aa8800');
        ggrad.addColorStop(0.4, '#ffdd44');
        ggrad.addColorStop(1, '#cc9900');
        ctx.beginPath();
        ctx.moveTo(-r * 0.1, 0);
        ctx.lineTo(-r * 0.05, -r * 0.88);
        ctx.lineTo(r * 0.05, -r * 0.88);
        ctx.lineTo(r * 0.1, 0);
        ctx.fillStyle = ggrad;
        ctx.fill();
        ctx.restore();
      }
      break;
    case 'mega-spike':
      for (let i = 0; i < 8; i++) {
        ctx.save();
        ctx.rotate((i / 8) * Math.PI * 2);
        ctx.beginPath();
        ctx.moveTo(0, -r * 0.5);
        ctx.lineTo(-r * 0.08, -r);
        ctx.lineTo(r * 0.08, -r);
        ctx.closePath();
        ctx.fillStyle = '#445';
        ctx.fill();
        ctx.restore();
      }
      break;
    case 'blade-runner':
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 0.15, r, 0, 0, Math.PI * 2);
      ctx.strokeStyle = '#aaccea';
      ctx.lineWidth = r * 0.08;
      ctx.stroke();
      break;
    case 'thruster-ring':
      for (let ri = 0; ri < 3; ri++) {
        const rr = r * (0.4 + ri * 0.25);
        ctx.beginPath();
        ctx.arc(0, 0, rr, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(100,180,255,${0.8 - ri * 0.25})`;
        ctx.lineWidth = r * 0.07;
        ctx.stroke();
      }
      break;
    case 'snow-spike':
      for (let i = 0; i < 16; i++) {
        ctx.save();
        ctx.rotate((i / 16) * Math.PI * 2);
        ctx.beginPath();
        ctx.moveTo(-r * 0.03, r * 0.8);
        ctx.lineTo(0, r * 1.05);
        ctx.lineTo(r * 0.03, r * 0.8);
        ctx.closePath();
        ctx.fillStyle = '#aaccff';
        ctx.fill();
        ctx.restore();
      }
      break;
    case 'mud-paddle':
      for (let i = 0; i < 6; i++) {
        ctx.save();
        ctx.rotate((i / 6) * Math.PI * 2);
        ctx.beginPath();
        ctx.rect(-r * 0.12, r * 0.65, r * 0.24, r * 0.38);
        ctx.fillStyle = '#6a4a2a';
        ctx.fill();
        ctx.restore();
      }
      break;
    default:
      for (let i = 0; i < 5; i++) {
        ctx.save();
        ctx.rotate((i / 5) * Math.PI * 2);
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(0, -r * 0.82);
        ctx.lineWidth = r * 0.14;
        ctx.strokeStyle = '#888';
        ctx.stroke();
        ctx.restore();
      }
  }
  ctx.beginPath();
  ctx.arc(0, 0, r * 0.22, 0, Math.PI * 2);
  ctx.fillStyle = '#333';
  ctx.fill();
  ctx.restore();
}

// ============================================================
// VEHICLE_BODY_DAMAGE_MAPS — hasar bölgeleri
// ============================================================
const VEHICLE_BODY_DAMAGE_MAPS = {};
['jeep','monster_truck','dragster','submarine','spaceship','mech_walker','tank','rickshaw','ice_bike','swamp_buggy'].forEach(vid => {
  VEHICLE_BODY_DAMAGE_MAPS[vid] = {
    front:       { health: 100, deformation: 0, maxDeform: 0.28, color: '#cc2200' },
    rear:        { health: 100, deformation: 0, maxDeform: 0.22, color: '#cc4400' },
    roof:        { health: 100, deformation: 0, maxDeform: 0.18, color: '#cc6600' },
    undercarriage:{ health: 100, deformation: 0, maxDeform: 0.12, color: '#aa2200' }
  };
});

function applyDamageToZone(vehicleId, zone, amount) {
  const map = VEHICLE_BODY_DAMAGE_MAPS[vehicleId];
  if (!map || !map[zone]) return;
  map[zone].health = Math.max(0, map[zone].health - amount);
  map[zone].deformation = Math.min(
    map[zone].maxDeform,
    map[zone].deformation + amount * 0.003
  );
}

function repairVehicleDamage(vehicleId, zone) {
  const map = VEHICLE_BODY_DAMAGE_MAPS[vehicleId];
  if (!map) return;
  const zones = zone ? [zone] : Object.keys(map);
  zones.forEach(z => {
    if (map[z]) { map[z].health = 100; map[z].deformation = 0; }
  });
}

