// ============================================================
// LIVERY_GENERATOR — prosedürel livery üretici
// ============================================================
const LIVERY_GENERATOR = {
  patterns: ['stripes', 'camo', 'urban', 'racing', 'retro'],
  palettes: {
    stripes: [['#cc0000','#ffffff','#0000cc'],['#ffcc00','#000000','#ff6600'],['#00aa44','#ffffff','#006622']],
    camo:    [['#3a4a2a','#2a3a1a','#6a5a3a','#4a3a2a'],['#885522','#664411','#997733','#553311'],['#2a4a5a','#1a3a4a','#3a5a6a','#0a2a3a']],
    urban:   [['#444','#888','#222','#666'],['#334455','#445566','#223344','#556677'],['#553344','#442233','#664455','#331122']],
    racing:  [['#cc0000','#ffffff'],['#0000cc','#ffcc00'],['#00aa00','#ffffff']],
    retro:   [['#ff6600','#ffcc00','#cc0044'],['#0044cc','#00aacc','#ffffff'],['#44aa00','#ffee00','#cc4400']]
  },

  seededRandom(seed) {
    let s = seed % 2147483647;
    return () => { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; };
  },

  generateStripes(ctx, W, H, palette, rng) {
    const count = Math.floor(rng() * 6) + 3;
    for (let i = 0; i < count; i++) {
      const x = rng() * W;
      const w = rng() * 30 + 8;
      const angle = (rng() - 0.5) * 0.4;
      ctx.save();
      ctx.translate(x, H / 2);
      ctx.rotate(angle);
      ctx.fillStyle = palette[i % palette.length];
      ctx.globalAlpha = 0.7 + rng() * 0.3;
      ctx.fillRect(-w / 2, -H, w, H * 2);
      ctx.restore();
    }
  },

  generateCamo(ctx, W, H, palette, rng) {
    const blobs = Math.floor(rng() * 20) + 15;
    for (let b = 0; b < blobs; b++) {
      ctx.beginPath();
      const bx = rng() * W, by = rng() * H;
      const br = rng() * 30 + 10;
      ctx.ellipse(bx, by, br * (0.5 + rng()), br * (0.5 + rng()), rng() * Math.PI, 0, Math.PI * 2);
      ctx.fillStyle = palette[Math.floor(rng() * palette.length)];
      ctx.globalAlpha = 0.8;
      ctx.fill();
    }
  },

  generateRacing(ctx, W, H, palette, rng) {
    ctx.fillStyle = palette[0];
    ctx.globalAlpha = 1;
    ctx.fillRect(0, 0, W, H);
    const stripeY = H * 0.3;
    const stripeH = H * 0.15;
    ctx.fillStyle = palette[1];
    ctx.fillRect(0, stripeY, W, stripeH);
    const stripeY2 = H * 0.55;
    ctx.fillRect(0, stripeY2, W, stripeH * 0.6);
    const numWidth = W * 0.2;
    ctx.fillStyle = palette[0];
    ctx.fillRect(W * 0.4, H * 0.1, numWidth, H * 0.8);
  },

  generateRetro(ctx, W, H, palette, rng) {
    const cellW = W / 8, cellH = H / 4;
    for (let cy = 0; cy < 4; cy++) {
      for (let cx = 0; cx < 8; cx++) {
        ctx.fillStyle = palette[Math.floor(rng() * palette.length)];
        ctx.globalAlpha = 0.6 + rng() * 0.4;
        ctx.fillRect(cx * cellW, cy * cellH, cellW, cellH);
      }
    }
  },

  generateUrban(ctx, W, H, palette, rng) {
    const shapes = Math.floor(rng() * 15) + 10;
    for (let s = 0; s < shapes; s++) {
      ctx.beginPath();
      const pts = Math.floor(rng() * 3) + 3;
      ctx.moveTo(rng() * W, rng() * H);
      for (let p = 0; p < pts; p++) ctx.lineTo(rng() * W, rng() * H);
      ctx.closePath();
      ctx.fillStyle = palette[Math.floor(rng() * palette.length)];
      ctx.globalAlpha = 0.5 + rng() * 0.5;
      ctx.fill();
    }
  }
};

function generateLivery(vehicleId, seed) {
  const rng = LIVERY_GENERATOR.seededRandom(seed || 42);
  const patternIdx = Math.floor(rng() * LIVERY_GENERATOR.patterns.length);
  const pattern = LIVERY_GENERATOR.patterns[patternIdx];
  const paletteArr = LIVERY_GENERATOR.palettes[pattern];
  const palette = paletteArr[Math.floor(rng() * paletteArr.length)];
  return {
    vehicleId,
    seed,
    pattern,
    palette,
    renderFn: (ctx, W, H) => {
      const r2 = LIVERY_GENERATOR.seededRandom(seed || 42);
      r2(); // skip first (used for pattern choice)
      ctx.save();
      ctx.globalAlpha = 1;
      switch (pattern) {
        case 'stripes': LIVERY_GENERATOR.generateStripes(ctx, W, H, palette, r2); break;
        case 'camo':    LIVERY_GENERATOR.generateCamo(ctx, W, H, palette, r2);    break;
        case 'racing':  LIVERY_GENERATOR.generateRacing(ctx, W, H, palette, r2);  break;
        case 'retro':   LIVERY_GENERATOR.generateRetro(ctx, W, H, palette, r2);   break;
        case 'urban':   LIVERY_GENERATOR.generateUrban(ctx, W, H, palette, r2);   break;
      }
      ctx.restore();
    }
  };
}

