function getUpgradeCost(vehicleId, component, currentLevel) {
  const costs = VEHICLE_UPGRADE_COSTS[vehicleId];
  if (!costs || !costs[component]) return Infinity;
  const idx = Math.max(0, Math.min(4, currentLevel));
  return costs[component][idx] || Infinity;
}

