// ============================================================
const VEHICLE_BASE_STATS = {
  jeep:         { speed: 95,  acceleration: 50, handling: 60, durability: 65, fuel_efficiency: 55 },
  monster_truck:{ speed: 85,  acceleration: 42, handling: 35, durability: 75, fuel_efficiency: 28 },
  dragster:     { speed: 165, acceleration: 72, handling: 28, durability: 32, fuel_efficiency: 18 },
  submarine:    { speed: 60,  acceleration: 38, handling: 52, durability: 62, fuel_efficiency: 48 },
  spaceship:    { speed: 190, acceleration: 65, handling: 55, durability: 35, fuel_efficiency: 15 },
  mech_walker:  { speed: 55,  acceleration: 32, handling: 40, durability: 80, fuel_efficiency: 22 },
  tank:         { speed: 48,  acceleration: 28, handling: 30, durability: 85, fuel_efficiency: 18 },
  rickshaw:     { speed: 100, acceleration: 58, handling: 65, durability: 38, fuel_efficiency: 70 },
  ice_bike:     { speed: 155, acceleration: 65, handling: 42, durability: 28, fuel_efficiency: 42 },
  swamp_buggy:  { speed: 88,  acceleration: 48, handling: 55, durability: 60, fuel_efficiency: 38 }
};

function getVehicleStatAtLevel(vehicleId, stat, level) {
  const base = VEHICLE_BASE_STATS[vehicleId];
  const cap  = VEHICLE_STAT_CAPS[vehicleId];
  if (!base || !cap) return 0;
  const b = base[stat] || 0;
  const c = cap[stat]  || 0;
  const t = Math.min(1, level / 5);
  return Math.round(b + (c - b) * t);
}

