const VEHICLE_REWARD_MULTIPLIERS = {
  jeep:         { coin: 1.0,  gem: 1.0,  xp: 1.0,  distance: 1.0 },
  monster_truck:{ coin: 1.15, gem: 1.10, xp: 1.20, distance: 0.95 },
  dragster:     { coin: 1.30, gem: 0.90, xp: 1.40, distance: 1.15 },
  submarine:    { coin: 0.90, gem: 1.40, xp: 1.10, distance: 0.80 },
  spaceship:    { coin: 1.50, gem: 1.30, xp: 1.50, distance: 1.20 },
  mech_walker:  { coin: 1.20, gem: 1.10, xp: 1.25, distance: 0.85 },
  tank:         { coin: 1.10, gem: 0.95, xp: 1.15, distance: 0.80 },
  rickshaw:     { coin: 0.85, gem: 0.90, xp: 0.90, distance: 1.10 },
  ice_bike:     { coin: 1.25, gem: 1.05, xp: 1.30, distance: 1.25 },
  swamp_buggy:  { coin: 1.05, gem: 1.20, xp: 1.10, distance: 1.00 }
};

function calculateReward(vehicleId, baseAmount, type) {
  const mults = VEHICLE_REWARD_MULTIPLIERS[vehicleId];
  if (!mults) return baseAmount;
  return Math.round(baseAmount * (mults[type] || 1.0));
}


