function getComboMultiplier(vehicleId, comboCount) {
  const mults = VEHICLE_COMBO_MULTIPLIERS[vehicleId];
  if (!mults) return 1.0;
  const base = 1.0 + (comboCount - 1) * 0.15;
  return Math.min(mults.max_combo, base);
}

