// VEHICLE_PRESTIGE_SYSTEM — prestij sistemi
// ============================================================
const VEHICLE_PRESTIGE_SYSTEM = {
  levels: [
    { prestige: 1, requirement: 'max_level_all_upgrades', reward: { coinMult: 1.1, badge: 'bronze_badge' } },
    { prestige: 2, requirement: 'win_100_races',           reward: { coinMult: 1.25, badge: 'silver_badge', newSkin: 'prestige_silver' } },
    { prestige: 3, requirement: 'distance_total_100000',   reward: { coinMult: 1.45, badge: 'gold_badge', newSkin: 'prestige_gold' } },
    { prestige: 4, requirement: 'flip_total_1000',         reward: { coinMult: 1.70, badge: 'platinum_badge', newSkin: 'prestige_platinum' } },
    { prestige: 5, requirement: 'all_challenges_complete', reward: { coinMult: 2.0,  badge: 'legendary_badge', newSkin: 'prestige_legendary', specialEffect: 'rainbow_trail' } }
  ],

  getPrestigeBadge(prestigeLevel) {
    const lvl = this.levels.find(l => l.prestige === prestigeLevel);
    return lvl ? lvl.reward.badge : null;
  },

  getPrestigeCoinMult(prestigeLevel) {
    const lvl = this.levels.find(l => l.prestige === prestigeLevel);
    return lvl ? lvl.reward.coinMult : 1.0;
  },

  drawPrestigeBadge(ctx, x, y, prestigeLevel) {
    if (!prestigeLevel || prestigeLevel < 1) return;
    const colors = {
      1: { outer:'#cd7f32', inner:'#a05a20', text:'#fff' },
      2: { outer:'#c0c0c0', inner:'#888888', text:'#fff' },
      3: { outer:'#ffcc00', inner:'#cc9900', text:'#fff' },
      4: { outer:'#e5e4e2', inner:'#aaa9ad', text:'#222' },
      5: { outer:'#ff8c00', inner:'#cc4400', text:'#fff' }
    };
    const c = colors[Math.min(prestigeLevel, 5)];
    ctx.save();
    ctx.translate(x, y);
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI*2);
    ctx.fillStyle = c.outer;
    ctx.fill();
    ctx.beginPath();
    ctx.arc(0, 0, 8, 0, Math.PI*2);
    ctx.fillStyle = c.inner;
    ctx.fill();
    ctx.font = 'bold 9px monospace';
    ctx.textAlign = 'center';
    ctx.fillStyle = c.text;
    ctx.fillText(prestigeLevel, 0, 3);
    ctx.restore();
  }
};


