function getDailyChallenge(dateStr) {
  const seed = dateStr ? dateStr.split('').reduce((a,c) => a + c.charCodeAt(0), 0) : Date.now();
  const idx = seed % VEHICLE_DAILY_CHALLENGES.length;
  return VEHICLE_DAILY_CHALLENGES[idx];
}

