function canAffordVehicle(vehicleId, playerCoins, playerGems) {
  const price = VEHICLE_UNLOCK_PRICES[vehicleId];
  if (!price) return false;
  return playerCoins >= price.coins && playerGems >= price.gems;
}

// ============================================================
// VEHICLE_ACHIEVEMENT_HOOKS — başarım tetikleyicileri
// ============================================================
const VEHICLE_ACHIEVEMENT_HOOKS = {
  on_first_flip: {
    achievementId: 'first_flip',
    vehicles: ['jeep','monster_truck','dragster','ice_bike','swamp_buggy'],
    check: (state) => (state.totalFlips || 0) >= 1
  },
  on_first_wheelie: {
    achievementId: 'wheelie_master',
    vehicles: ['dragster','ice_bike','rickshaw'],
    check: (state) => (state.maxWheelieTime || 0) >= 3000
  },
  on_max_speed: {
    achievementId: 'speed_demon',
    vehicles: ['dragster','spaceship','ice_bike'],
    check: (state) => (state.maxSpeed || 0) >= 200
  },
  on_stomp: {
    achievementId: 'ground_breaker',
    vehicles: ['mech_walker'],
    check: (state) => (state.stompCount || 0) >= 1
  },
  on_crush: {
    achievementId: 'crusher',
    vehicles: ['monster_truck','tank','mech_walker'],
    check: (state) => (state.crushCount || 0) >= 5
  },
  on_underwater_30s: {
    achievementId: 'deep_dive',
    vehicles: ['submarine'],
    check: (state) => (state.underwaterTime || 0) >= 30000
  }
};

function checkVehicleAchievements(vehicleId, gameState) {
  const triggered = [];
  for (const [key, hook] of Object.entries(VEHICLE_ACHIEVEMENT_HOOKS)) {
    if (hook.vehicles.includes(vehicleId) && hook.check(gameState)) {
      triggered.push(hook.achievementId);
    }
  }
  return triggered;
}

