// ─── Stacking Rules ────────────────────────────────────────────────────────────
const STACKING_RULES = {
  // No two BOOST-type abilities can be active simultaneously
  boost_exclusive: {
    type: 'exclusive_by_type',
    affectedTypes: [ABILITY_TYPES.BOOST],
    rule: 'Only one BOOST ability may be active at a time. New activation cancels previous.'
  },
  // SHIELD + REPAIR can stack but cap at 100% damage reduction
  shield_repair_stack: {
    type: 'cap_on_stat',
    abilities: ['ab_energy_shield','ab_iron_skin','ab_nanobots'],
    stat: 'damageReduction',
    cap: 100
  },
  // TIME_SLOW cancels BOOST
  time_cancels_boost: {
    type: 'cancel_on_activate',
    trigger: ABILITY_TYPES.TIME_SLOW,
    cancels: ABILITY_TYPES.BOOST
  },
  // PASSIVE abilities always stack with active abilities
  passive_always_active: {
    type: 'always_active',
    affectedTypes: [ABILITY_TYPES.PASSIVE]
  },
  // Maximum 3 active abilities simultaneously (excluding passives)
  max_active_concurrent: {
    type: 'count_limit',
    excludeTypes: [ABILITY_TYPES.PASSIVE],
    maxCount: 3
  }
};

