const ABILITY_INTERACTIONS = {
  'ab_nitro_surge+ab_turbo_spool':  { type: 'synergy',  bonus: { speedMultiplier: 0.15, description: 'Turbo+Nitro: extra 15% speed stacks' } },
  'ab_bullet_time+ab_coin_magnet':  { type: 'synergy',  bonus: { coinRadius: 5.0, description: 'Slow time expands magnet radius by 5m' } },
  'ab_energy_shield+ab_emp_blast':  { type: 'conflict', penalty: { shieldHP: -200, description: 'EMP partially disrupts own shield' } },
  'ab_ghost_mode+ab_coin_magnet':   { type: 'synergy',  bonus: { coinMultiplier: 0.5, description: 'Ghost collects coins through walls' } },
  'ab_flamethrower+ab_ice_burst':   { type: 'cancel',   description: 'Fire and Ice cancel each other — neither effect applies' },
  'ab_gravity_flip+ab_super_jump':  { type: 'synergy',  bonus: { jumpForce: 2.0, description: 'Inverted gravity makes jumping extremely powerful' } }
};

function getInteractionKey(id1, id2) {
  return [id1, id2].sort().join('+');
}
function checkInteraction(abilityId1, abilityId2) {
  return ABILITY_INTERACTIONS[getInteractionKey(abilityId1, abilityId2)] || null;
}

