'use strict';

// ─── Fusion Cost Calculation ──────────────────────────────────────────────────
function computeFusionCost(vehicleA, vehicleB) {
  const RARITY_VALUES = { common: 1, rare: 2, epic: 4, legendary: 8 };
  const raritySum = (RARITY_VALUES[vehicleA.rarity] || 1) + (RARITY_VALUES[vehicleB.rarity] || 1);
  const baseCost = raritySum * 8000;
  return {
    gold:    baseCost,
    diamond: Math.ceil(raritySum * 1.5),
    fusionGems: Math.ceil(raritySum * 0.5)
  };
}

function computeAttributeInheritance(vehicleA, vehicleB, bonusPercent) {
  const bonus = 1 + (bonusPercent || 0) / 100;
  const result = {};
  const statKeys = ['speed','acceleration','handling','traction','fuel','nitro','armor','weight'];
  for (const stat of statKeys) {
    const aVal = (vehicleA.baseStats || {})[stat] || 0;
    const bVal = (vehicleB.baseStats || {})[stat] || 0;
    const best = Math.max(aVal, bVal);
    result[stat] = stat === 'weight'
      ? Math.round(Math.min(aVal, bVal) * 0.90)     // lighter of two, reduced 10%
      : Math.min(100, Math.round(best * bonus));     // best stat + bonus, capped 100
  }
  return result;
}

