// =============================================================================
// VEHICLE_MAP_DATA: Track-specific vehicle data, surface zones, spawn data (~40KB)
// =============================================================================
const VEHICLE_MAP_DATA = (() => {
  const TRACK_LIST = [
    "mountain_pass","desert_highway","arctic_tundra","forest_trail","city_circuit",
    "jungle_run","coastline_drive","cave_system","sky_island","volcano_road",
    "swamp_crossing","glacier_peak","urban_canyon","night_circuit","beach_sprint",
    "mine_shaft","ancient_ruins","space_station","underwater_tube","tornado_alley"
  ];

  const SURFACE_ZONES = {};
  TRACK_LIST.forEach((track, ti) => {
    SURFACE_ZONES[track] = Array.from({ length: 20 }, (_, i) => ({
      zoneId: `${track}_z${i}`,
      startPct: i * 5,
      endPct: (i + 1) * 5,
      surface: ["asphalt","gravel","dirt","grass","mud","snow","ice","sand","water","rock"][
        (ti * 3 + i * 7) % 10
      ],
      gripMult:   parseFloat((0.5 + ((ti * 11 + i * 13) % 100) / 200).toFixed(2)),
      bumpFactor: parseFloat((0.02 + ((ti * 7  + i * 11) % 50) / 1000).toFixed(3)),
      widthM:     10 + ((ti * 5 + i * 3) % 20),
      lightLevel: parseFloat((0.4 + ((ti * 9 + i * 6) % 60) / 100).toFixed(2))
    }));
  });

  const SPAWN_POINTS = {};
  TRACK_LIST.forEach((track, ti) => {
    SPAWN_POINTS[track] = Array.from({ length: 8 }, (_, i) => ({
      playerId: i,
      x: 200 + i * 60 + (ti * 17) % 30,
      y: 300 + (ti * 23) % 50,
      angle: 0,
      direction: 1
    }));
  });

  const CHECKPOINT_DATA = {};
  TRACK_LIST.forEach((track, ti) => {
    CHECKPOINT_DATA[track] = Array.from({ length: 10 }, (_, i) => ({
      id: i,
      x: 500 + i * 300 + (ti * 41) % 100,
      y: 200 + ((ti * 31 + i * 47) % 150),
      width: 80 + ((ti * 13 + i * 7) % 60),
      required: i % 3 !== 2
    }));
  });

  const TRACK_RECORDS = {};
  TRACK_LIST.forEach(track => {
    TRACK_RECORDS[track] = {
      distance: { value: 0, holder: null, date: null },
      time: { value: 0, holder: null, date: null },
      tricks: { value: 0, holder: null, date: null },
      flips: { value: 0, holder: null, date: null }
    };
  });

  const VEHICLE_TRACK_RATINGS = {};
  const vehicleList = [
    "muscle_car","sports_car","atv","monster_truck","formula_car","buggy",
    "motocross","snowmobile","boat","helicopter","tank","bicycle","skateboard"
  ];
  vehicleList.forEach(v => {
    VEHICLE_TRACK_RATINGS[v] = {};
    TRACK_LIST.forEach(t => {
      VEHICLE_TRACK_RATINGS[v][t] = parseFloat((0.5 + Math.abs(Math.sin(v.length * t.length)) * 0.5).toFixed(2));
    });
  });

  const NITRO_PICKUP_ZONES = {};
  TRACK_LIST.forEach((track, ti) => {
    NITRO_PICKUP_ZONES[track] = Array.from({ length: 6 }, (_, i) => ({
      id: `np_${ti}_${i}`,
      x: 400 + i * 250 + (ti * 37) % 120,
      y: 250 + ((ti * 53 + i * 29) % 100),
      value: 15 + ((ti * 7 + i * 11) % 30),
      respawnSec: 10 + ((ti + i) % 5) * 2
    }));
  });

  const RAMP_DATA = {};
  TRACK_LIST.forEach((track, ti) => {
    RAMP_DATA[track] = Array.from({ length: 8 }, (_, i) => ({
      id: `ramp_${ti}_${i}`,
      x: 600 + i * 350 + (ti * 43) % 150,
      y: 180 + ((ti * 61 + i * 23) % 80),
      angle: 15 + ((ti * 7 + i * 5) % 45),
      launchBoost: parseFloat((1.0 + ((ti * 3 + i * 2) % 20) / 100).toFixed(2))
    }));
  });

  const WEATHER_DATA = {};
  TRACK_LIST.forEach((track, ti) => {
    WEATHER_DATA[track] = {
      defaultWeather: ["sunny","cloudy","foggy","rainy","snowy","stormy","windy","clear"][ti % 8],
      weatherCycles: ["sunny","cloudy","rainy"].slice(0, 2 + ti % 2),
      windSpeedKph: 10 + (ti * 7) % 50,
      windDirection: (ti * 37) % 360,
      rainGripMult: 0.75,
      snowGripMult: 0.55,
      fogVisibility: 0.4
    };
  });

  const AI_PATH_NODES = {};
  TRACK_LIST.forEach((track, ti) => {
    AI_PATH_NODES[track] = Array.from({ length: 50 }, (_, i) => ({
      id: i,
      x: 200 + i * 55 + Math.round(Math.sin(i * 0.3 + ti) * 40),
      y: 250 + Math.round(Math.cos(i * 0.2 + ti * 0.5) * 80),
      speedLimit: 80 + ((ti * 11 + i * 7) % 120),
      trickZone: i % 8 === 3,
      nitroZone: i % 10 === 5
    }));
  });

  return {
    TRACK_LIST,
    SURFACE_ZONES,
    SPAWN_POINTS,
    CHECKPOINT_DATA,
    TRACK_RECORDS,
    VEHICLE_TRACK_RATINGS,
    NITRO_PICKUP_ZONES,
    RAMP_DATA,
    WEATHER_DATA,
    AI_PATH_NODES,
    version: "2.0.0"
  };
})();

