// ═══════════════════════════════════════════════════════════════════════════
//  WİKİ ARAÇLARI — 14 YENİ ÇİZİM  (3 Ağu)
//  Kaynak tarifi: port-araclari/_arac-wiki.json → her aracın `gorunum` alanı.
//  Kurallar (bu blokta bilinçli olarak uygulandı):
//    · `ctx.ellipse` KULLANILMADI — daire için `arc`, elips için `save/scale/arc`.
//    · Araç +x yönüne bakar (far/burun +x tarafında, stop lambası -x tarafında).
//    · Tekerler drawVehicle içinde GÖVDEDEN ÖNCE çizilir → gövde onları örter;
//      açık tekerlekli araçlarda (bolt, hotrod) gövde bilinçli olarak dardır.
//    · Jant rengi vurgusu gövdeden sonra ince halka olarak geçilir.
// ═══════════════════════════════════════════════════════════════════════════

// Elips — ctx.ellipse KULLANMADAN (save/scale/arc). Bu blokta tek elips yolu budur.
function _wEllipse(ctx, cx, cy, rx, ry) {
  ctx.save(); ctx.translate(cx, cy); ctx.scale(1, ry / rx);
  ctx.beginPath(); ctx.arc(0, 0, rx, 0, Math.PI * 2); ctx.restore();
}
// KAPALI KABİNLİ araçlar için CAMIN İÇİNDE görünen küçük sürücü silueti.
// 🔴 NEDEN VAR (PNG kanıtıyla bulundu): `_driver()` gövdeyi y-12..y+2, kaskı y-16
//   merkezli r=8 çizer → en üst nokta y-24. Kapalı tavanlı bir araçta tavanın
//   üstüne yerleştirilince kask ÇATIDA DURAN SİYAH SİLİNDİR gibi görünüyordu
//   (ilk çizimde hotrod/ccev/stocker/raider'da 4 kez oldu, ızgara PNG'de görüldü).
function _wCabinHead(ctx, x, y, helmet, t) {
  var bob = Math.sin(t * 2.2) * 0.4;
  ctx.save();
  ctx.fillStyle = 'rgba(10,14,20,0.55)';                      // omuz gölgesi (cam ardı)
  ctx.beginPath(); ctx.roundRect(x - 7, y + 2 + bob, 14, 8, 3); ctx.fill();
  ctx.fillStyle = helmet;
  ctx.beginPath(); ctx.arc(x, y - 2 + bob, 5.5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.22)';
  ctx.beginPath(); ctx.arc(x, y - 2 + bob, 5.5, Math.PI * 1.15, Math.PI * 1.85); ctx.fill();
  ctx.restore();
}
// Tanımdaki tekerlerin üstüne ince renkli jant halkası (wiki'de jant rengi belirtilen araçlar)
function _wRimRing(ctx, def, color, w) {
  var wd = def.wheels || [];
  ctx.strokeStyle = color; ctx.lineWidth = w || 3;
  for (var i = 0; i < wd.length; i++) {
    ctx.beginPath(); ctx.arc(wd[i].x, wd[i].y, (wd[i].r || 16) * 0.58, 0, Math.PI * 2); ctx.stroke();
  }
}

// ── 1) Süper Jeep (Hill Climber Mk. 2) ──────────────────────────────────────
//  Wiki: kırmızı gövde + SİYAH kaput, siyah roll cage/tavan çerçevesi, siyah
//        çamurluk taşkınları, açık kabin, kalın siyah koç barı, daha büyük lastik.
function drawSuperJeep(ctx, def, v, thr, t) {
  var c1 = def.color || '#cc2222', c2 = def.color2 || '#141414';
  var sa = v.suspAnim || [0, 0], wd = def.wheels;
  if (wd) wd.forEach(function (w, i) { var c = sa[i] || 0; _drawSusp(ctx, w.x, -2, w.x, w.y * (1 - c * 0.3), c); });
  // Siyah taşkın çamurluk kemerleri (Mk1'den belirgin kalın)
  ctx.fillStyle = '#141414';
  if (wd) wd.forEach(function (w) {
    ctx.beginPath(); ctx.arc(w.x, w.y - 2, w.r + 10, Math.PI, 0);
    ctx.lineTo(w.x + w.r + 10, w.y + 4); ctx.lineTo(w.x - w.r - 10, w.y + 4); ctx.closePath(); ctx.fill();
  });
  // Alt eşik
  ctx.fillStyle = _shade(c1, -0.6);
  ctx.beginPath(); ctx.roundRect(-58, 2, 116, 13, 4); ctx.fill();
  // Ana gövde — kırmızı
  var bg = ctx.createLinearGradient(0, -20, 0, 14);
  bg.addColorStop(0, _shade(c1, 0.4)); bg.addColorStop(0.45, c1); bg.addColorStop(1, _shade(c1, -0.3));
  ctx.fillStyle = bg;
  ctx.beginPath(); ctx.roundRect(-58, -20, 116, 34, 8); ctx.fill();
  // SİYAH KAPUT (Mk2'nin ayırt edici parçası)
  var hg = ctx.createLinearGradient(0, -24, 0, -8);
  hg.addColorStop(0, '#3a3a3a'); hg.addColorStop(1, '#0e0e0e');
  ctx.fillStyle = hg;
  ctx.beginPath(); ctx.roundRect(14, -24, 44, 16, [6, 6, 2, 2]); ctx.fill();
  ctx.strokeStyle = '#555'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(20, -21); ctx.lineTo(52, -21); ctx.stroke();
  // Açık kabin: koltuklar görünüyor
  ctx.fillStyle = '#241416';
  ctx.beginPath(); ctx.roundRect(-42, -26, 52, 14, 3); ctx.fill();
  ctx.fillStyle = '#4a2a2a';
  ctx.beginPath(); ctx.roundRect(-36, -34, 12, 12, 3); ctx.fill();   // arka koltuk sırtı
  ctx.beginPath(); ctx.roundRect(-14, -34, 12, 12, 3); ctx.fill();
  // Siyah roll cage / tavan çerçevesi
  ctx.strokeStyle = '#101010'; ctx.lineWidth = 4; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-44, -14); ctx.lineTo(-44, -46); ctx.lineTo(12, -46); ctx.lineTo(20, -22);
  ctx.moveTo(-20, -46); ctx.lineTo(-20, -26);
  ctx.stroke();
  // Ön cam çerçevesi
  ctx.strokeStyle = '#1c1c1c'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(12, -46); ctx.lineTo(22, -24); ctx.stroke();
  ctx.fillStyle = 'rgba(150,200,235,0.45)';
  ctx.beginPath(); ctx.moveTo(13, -44); ctx.lineTo(20, -26); ctx.lineTo(11, -26); ctx.closePath(); ctx.fill();
  // Kalın siyah koç barı (bull bar)
  ctx.strokeStyle = '#0d0d0d'; ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(58, -8); ctx.lineTo(68, -8); ctx.lineTo(68, 12); ctx.lineTo(58, 12); ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(68, 2); ctx.lineTo(58, 2); ctx.stroke();
  // Farlar
  ctx.save(); ctx.shadowColor = '#fff6c8'; ctx.shadowBlur = 12; ctx.fillStyle = '#fffbe0';
  ctx.beginPath(); ctx.arc(56, -4, 5.5, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  // Stop
  ctx.save(); ctx.shadowColor = '#ff2200'; ctx.shadowBlur = 8; ctx.fillStyle = '#ff3322';
  ctx.beginPath(); ctx.arc(-56, -4, 4, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  _driver(ctx, -10, -38, '#f5f5f5', '#7a1010', t);
}

// ── 2) Lowrider ─────────────────────────────────────────────────────────────
//  Wiki: çok uzun/çok alçak üstü açık klasik Amerikan cabrio; zeytin yeşili
//        gövde + koyu yeşil alt bant; katlanmış tavan arka bagajda; krom ızgara
//        ve ince krom tamponlar; küçük beyaz bantlı lastik + krom jant kapağı.
function drawLowrider(ctx, def, v, thr, t) {
  var c1 = def.color || '#6b8f3a', c2 = def.color2 || '#3a5220';
  var sa = v.suspAnim || [0, 0], wd = def.wheels;
  if (wd) wd.forEach(function (w, i) { var c = sa[i] || 0; _drawSusp(ctx, w.x, 2, w.x, w.y * (1 - c * 0.3), c); });
  // Krom marşpiye (çok alçak)
  _chrome(ctx, -68, 8, 136, 5);
  // Ana gövde — uzun ve alçak
  var bg = ctx.createLinearGradient(0, -14, 0, 10);
  bg.addColorStop(0, _shade(c1, 0.42)); bg.addColorStop(0.5, c1); bg.addColorStop(1, _shade(c1, -0.15));
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-72, 8); ctx.lineTo(-74, -6);
  ctx.quadraticCurveTo(-70, -14, -40, -16);
  ctx.lineTo(30, -16); ctx.quadraticCurveTo(66, -15, 74, -4);
  ctx.lineTo(74, 8); ctx.closePath(); ctx.fill();
  // Koyu yeşil alt bant
  ctx.fillStyle = c2;
  ctx.beginPath(); ctx.roundRect(-72, 0, 146, 9, 3); ctx.fill();
  // Uzun kaput çizgisi
  ctx.strokeStyle = _shade(c1, 0.55); ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(22, -14); ctx.lineTo(68, -8); ctx.stroke();
  // Açık kabin — koltuklar
  ctx.fillStyle = '#2a2418';
  ctx.beginPath(); ctx.roundRect(-42, -22, 60, 10, 3); ctx.fill();
  ctx.fillStyle = '#b8a66a';
  ctx.beginPath(); ctx.roundRect(-36, -30, 13, 12, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-12, -30, 13, 12, 3); ctx.fill();
  // İndirilmiş yumuşak tavan — arka bagajın üstünde katlanmış
  ctx.fillStyle = '#5a5344';
  ctx.beginPath(); ctx.roundRect(-70, -24, 26, 9, 4); ctx.fill();
  ctx.strokeStyle = '#3d382d'; ctx.lineWidth = 1;
  for (var f = -66; f < -46; f += 6) { ctx.beginPath(); ctx.moveTo(f, -23); ctx.lineTo(f, -16); ctx.stroke(); }
  // Ön cam (küçük, dik olmayan)
  ctx.strokeStyle = '#c8cdd4'; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(18, -16); ctx.lineTo(22, -28); ctx.lineTo(2, -28); ctx.stroke();
  ctx.fillStyle = 'rgba(190,225,245,0.4)';
  ctx.beginPath(); ctx.moveTo(19, -17); ctx.lineTo(21, -27); ctx.lineTo(4, -27); ctx.closePath(); ctx.fill();
  // Krom ızgara + ince tamponlar
  var cg = ctx.createLinearGradient(0, -8, 0, 6); cg.addColorStop(0, '#f4f4f4'); cg.addColorStop(1, '#7e8288');
  ctx.fillStyle = cg;
  ctx.beginPath(); ctx.roundRect(62, -8, 12, 12, 2); ctx.fill();     // ızgara
  ctx.beginPath(); ctx.roundRect(66, 5, 12, 5, 2); ctx.fill();       // ön tampon
  ctx.beginPath(); ctx.roundRect(-78, 5, 12, 5, 2); ctx.fill();      // arka tampon
  ctx.strokeStyle = '#5f6367'; ctx.lineWidth = 0.8;
  for (var gl = -6; gl <= 2; gl += 3) { ctx.beginPath(); ctx.moveTo(63, gl); ctx.lineTo(73, gl); ctx.stroke(); }
  // Krom jant kapağı + beyaz bant vurgusu
  _wRimRing(ctx, def, 'rgba(245,245,245,0.9)', 3.5);
  ctx.save(); ctx.shadowColor = '#fff6c8'; ctx.shadowBlur = 10; ctx.fillStyle = '#fffbe0';
  ctx.beginPath(); ctx.arc(70, -3, 4, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  _taillight(ctx, -74, -2, 3.5);
  _driver(ctx, -14, -34, '#f0e6c8', '#7a5a2a', t);   // PNG: koyu kask siyah silindir gibi duruyordu
}

// ── 3) Hot Rod ──────────────────────────────────────────────────────────────
//  Wiki: 1930'lar coupe; hardal/altın gövde, siyah şasi; kaputsuz motor +
//        yandan 4 krom zoomie egzoz; kabin ARKADA küçük ve dik (chopped top);
//        önde açık iskelet aks, ince küçük ön teker + KIRMIZI jant, arkada
//        büyük geniş teker + kırmızı jant.
function drawHotRod(ctx, def, v, thr, t) {
  var c1 = def.color || '#d8a418', c2 = def.color2 || '#191919';
  var sa = v.suspAnim || [0, 0], wd = def.wheels || [];
  // Arka (büyük) tekerde yay; ön aks açık iskelet olduğu için yay YOK.
  wd.forEach(function (w, i) { if (w.x < 0) _drawSusp(ctx, w.x, 2, w.x, w.y * (1 - (sa[i] || 0) * 0.3), sa[i] || 0); });
  // ── Açık iskelet ön aks (I-beam + radius rod) ──
  ctx.strokeStyle = c2; ctx.lineWidth = 4; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(24, 4); ctx.lineTo(52, 14); ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(38, -2); ctx.lineTo(52, 12); ctx.stroke();
  ctx.strokeStyle = '#9aa0a6'; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(44, 12); ctx.lineTo(60, 12); ctx.stroke();      // enine dingil
  // ── Siyah şasi rayı ──
  ctx.fillStyle = c2; ctx.beginPath(); ctx.roundRect(-54, 4, 106, 8, 3); ctx.fill();
  // ── T-bucket gövde: kısa/tıknaz arka kısım + ince UZUN kaput ──
  var bg = ctx.createLinearGradient(0, -18, 0, 8);
  bg.addColorStop(0, _shade(c1, 0.5)); bg.addColorStop(0.5, c1); bg.addColorStop(1, _shade(c1, -0.3));
  ctx.fillStyle = bg;
  ctx.beginPath();                       // arka gövde (kabin altı kutu)
  ctx.moveTo(-56, 6); ctx.lineTo(-56, -14);
  ctx.quadraticCurveTo(-54, -20, -44, -20);
  ctx.lineTo(-2, -20); ctx.lineTo(-2, 6); ctx.closePath(); ctx.fill();
  ctx.beginPath();                       // ince alçak kaput (öne uzanan)
  ctx.moveTo(-2, -14); ctx.lineTo(38, -12); ctx.quadraticCurveTo(48, -11, 50, -4);
  ctx.lineTo(50, 4); ctx.lineTo(-2, 4); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = _shade(c1, 0.62); ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.moveTo(2, -11); ctx.lineTo(44, -9); ctx.stroke();
  // ── Kabin ARKADA, küçük ve ALÇALTILMIŞ tavan (chopped top) ──
  var rg = ctx.createLinearGradient(0, -40, 0, -20);
  rg.addColorStop(0, _shade(c1, 0.34)); rg.addColorStop(1, _shade(c1, -0.16));
  ctx.fillStyle = rg;
  ctx.beginPath(); ctx.roundRect(-52, -40, 44, 22, [10, 7, 0, 0]); ctx.fill();
  ctx.fillStyle = c2;                                   // alçaltılmış tavan bandı
  ctx.beginPath(); ctx.roundRect(-53, -42, 46, 5, [6, 4, 0, 0]); ctx.fill();
  // Küçük dik camlar
  var gg = ctx.createLinearGradient(0, -36, 0, -22);
  gg.addColorStop(0, '#cfe6ff'); gg.addColorStop(0.6, '#5b86a8'); gg.addColorStop(1, '#26384a');
  ctx.fillStyle = gg;
  ctx.beginPath(); ctx.roundRect(-49, -35, 17, 14, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-28, -35, 17, 14, 2); ctx.fill();
  _wCabinHead(ctx, -22, -30, '#f2f2f2', t);            // sürücü CAMIN İÇİNDE
  ctx.fillStyle = 'rgba(255,255,255,0.26)';
  ctx.beginPath(); ctx.moveTo(-47, -33); ctx.lineTo(-39, -33); ctx.lineTo(-45, -23); ctx.lineTo(-48, -23); ctx.closePath(); ctx.fill();
  // ── KAPUTSUZ MOTOR: blok + krom kompresör + huni ──
  ctx.fillStyle = '#2f2f2f'; ctx.beginPath(); ctx.roundRect(2, -30, 28, 18, 2); ctx.fill();
  ctx.strokeStyle = '#565656'; ctx.lineWidth = 1;
  for (var f = 0; f < 4; f++) { ctx.beginPath(); ctx.moveTo(5, -27 + f * 4); ctx.lineTo(27, -27 + f * 4); ctx.stroke(); }
  var mg = ctx.createLinearGradient(0, -40, 0, -28); mg.addColorStop(0, '#f2f2f2'); mg.addColorStop(1, '#82868c');
  ctx.fillStyle = mg; ctx.beginPath(); ctx.roundRect(7, -40, 18, 11, 2); ctx.fill();
  ctx.fillStyle = '#c9ccd1';
  ctx.beginPath(); ctx.moveTo(10, -40); ctx.lineTo(22, -40); ctx.lineTo(19, -47); ctx.lineTo(13, -47); ctx.closePath(); ctx.fill();
  // ── 4 KROM ZOOMIE EGZOZ (blokın altından çıkıp arkaya kıvrılır) ──
  var eg = ctx.createLinearGradient(0, -14, 0, 0); eg.addColorStop(0, '#fbfbfb'); eg.addColorStop(1, '#767a80');
  ctx.strokeStyle = eg; ctx.lineWidth = 4.5; ctx.lineCap = 'round';
  for (var e = 0; e < 4; e++) {
    var ex = 26 - e * 7;
    ctx.beginPath(); ctx.moveTo(ex, -14); ctx.quadraticCurveTo(ex - 7, -8, ex - 12, -2); ctx.stroke();
  }
  if (thr > 0.1) _exhaustFlame(ctx, -6, -2, thr, t, 5);
  // ── Kırmızı jant + far/stop ──
  _wRimRing(ctx, def, '#d81f26', 4);
  ctx.save(); ctx.shadowColor = '#fff0b0'; ctx.shadowBlur = 9; ctx.fillStyle = '#fff6d0';
  ctx.beginPath(); ctx.arc(48, -8, 4, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  _taillight(ctx, -56, -10, 3);
}

// ── 4) Rotator ──────────────────────────────────────────────────────────────
//  Wiki: açık boru kafesli kaya tırmanıcı; fıstık yeşili kafes, yeşil panel;
//        kabin yok, koltuk kafesin içinde; ARKADA yüksek dik döner kule/kol
//        (ters dönen aracı çeviren mekanizma); ortada açık motor; SARI jant.
function drawRotator(ctx, def, v, thr, t) {
  var c1 = def.color || '#9ad63c', c2 = def.color2 || '#2f6b16';
  var sa = v.suspAnim || [0, 0], wd = def.wheels;
  if (wd) wd.forEach(function (w, i) { var c = sa[i] || 0; _drawSusp(ctx, w.x, 0, w.x, w.y * (1 - c * 0.3), c); });
  // Alt şasi
  ctx.fillStyle = c2; ctx.beginPath(); ctx.roundRect(-52, 6, 104, 9, 3); ctx.fill();
  // Yeşil gövde panelleri (kafesin içinde)
  var bg = ctx.createLinearGradient(0, -16, 0, 8);
  bg.addColorStop(0, _shade(c2, 0.45)); bg.addColorStop(1, _shade(c2, -0.2));
  ctx.fillStyle = bg;
  ctx.beginPath(); ctx.roundRect(-46, -16, 92, 24, 4); ctx.fill();
  // Ortada açık motor
  ctx.fillStyle = '#2b2b2b'; ctx.beginPath(); ctx.roundRect(-6, -28, 26, 14, 3); ctx.fill();
  ctx.strokeStyle = '#5a5a5a'; ctx.lineWidth = 1;
  for (var f = 0; f < 4; f++) { ctx.beginPath(); ctx.moveTo(-3, -25 + f * 3); ctx.lineTo(17, -25 + f * 3); ctx.stroke(); }
  // Açık boru kafes (roll cage) — fıstık yeşili
  ctx.strokeStyle = c1; ctx.lineWidth = 5; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-50, 8); ctx.lineTo(-50, -30); ctx.lineTo(-16, -44); ctx.lineTo(24, -44);
  ctx.lineTo(48, -20); ctx.lineTo(50, 8);
  ctx.stroke();
  ctx.lineWidth = 3.5;
  ctx.beginPath(); ctx.moveTo(-16, -44); ctx.lineTo(-16, -12); ctx.moveTo(24, -44); ctx.lineTo(28, -14); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-50, -14); ctx.lineTo(48, -20); ctx.stroke();
  // Koltuk (kafesin içinde)
  ctx.fillStyle = '#1e1e1e'; ctx.beginPath(); ctx.roundRect(-34, -34, 14, 20, 3); ctx.fill();
  // ARKADA YÜKSEK DÖNER KULE/KOL — aracın ayırt edici mekanizması (dönüyor)
  var ang = Math.sin(t * 1.1) * 0.5;
  ctx.save();
  ctx.translate(-46, -30);
  ctx.fillStyle = '#4a4a4a'; ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
  ctx.rotate(-1.35 + ang);
  var tg = ctx.createLinearGradient(0, 0, 0, -46);
  tg.addColorStop(0, _shade(c1, -0.1)); tg.addColorStop(1, _shade(c1, 0.4));
  ctx.fillStyle = tg; ctx.beginPath(); ctx.roundRect(-5, -46, 10, 48, 4); ctx.fill();
  ctx.fillStyle = '#f0c000'; ctx.beginPath(); ctx.roundRect(-8, -50, 16, 7, 3); ctx.fill();   // kol ucu ağırlığı
  ctx.strokeStyle = '#2a2a2a'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(-4, -12); ctx.lineTo(4, -12); ctx.moveTo(-4, -28); ctx.lineTo(4, -28); ctx.stroke();
  ctx.restore();
  // SARI jant
  _wRimRing(ctx, def, '#f5d020', 4.5);
  ctx.save(); ctx.shadowColor = '#fff0a0'; ctx.shadowBlur = 9; ctx.fillStyle = '#fffbd0';
  ctx.beginPath(); ctx.arc(46, -8, 4, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  _driver(ctx, -27, -40, '#f5d020', '#2f6b16', t);
}

// ── 5) CC-EV ────────────────────────────────────────────────────────────────
//  Wiki: kompakt elektrikli crossover; turuncu-mercan gövde, beyaz/açık gri cam
//        ve tavan; kısa-YÜKSEK, dik ön cam; arka üstte batarya/şarj modülü +
//        anten; beyaz-gümüş far, altta koruma plakası.
function drawCcEv(ctx, def, v, thr, t) {
  var c1 = def.color || '#ff7043', c2 = def.color2 || '#eceff1';
  var sa = v.suspAnim || [0, 0], wd = def.wheels;
  if (wd) wd.forEach(function (w, i) { var c = sa[i] || 0; _drawSusp(ctx, w.x, -2, w.x, w.y * (1 - c * 0.3), c); });
  // Hafif taşkın çamurluklar
  // 🔴 PNG kanıtı: ilk sürümde `_shade(c1,-0.5)` KOYU KAHVE veriyordu ve +7 px
  //   taşkınlıkla gövdeden büyük iki blob oluşuyordu (araç "kahverengi tekerlek
  //   üstünde turuncu şerit" gibi görünüyordu). Renk koyu gri-mavi, taşkınlık +4.
  ctx.fillStyle = '#333b42';
  if (wd) wd.forEach(function (w) {
    ctx.beginPath(); ctx.arc(w.x, w.y - 2, w.r + 4, Math.PI, 0);
    ctx.lineTo(w.x + w.r + 4, w.y + 2); ctx.lineTo(w.x - w.r - 4, w.y + 2); ctx.closePath(); ctx.fill();
  });
  // Altta koruma plakası
  var sg = ctx.createLinearGradient(0, 8, 0, 16); sg.addColorStop(0, '#b8bec6'); sg.addColorStop(1, '#6c737b');
  ctx.fillStyle = sg; ctx.beginPath(); ctx.roundRect(-46, 6, 96, 9, 3); ctx.fill();
  // Ana gövde — kısa ve yüksek
  var bg = ctx.createLinearGradient(0, -25, 0, 10);
  bg.addColorStop(0, _shade(c1, 0.35)); bg.addColorStop(0.5, c1); bg.addColorStop(1, _shade(c1, -0.3));
  ctx.fillStyle = bg;
  ctx.beginPath(); ctx.roundRect(-52, -25, 104, 33, [10, 12, 6, 6]); ctx.fill();
  // Beyaz cam alanı + tavan (tek parça, kısa-dik)
  // 🔴 PNG kanıtı: ilk sürümde tavan -48'e kadar çıkıyordu ve gövdenin YARISINDAN
  //   büyüktü (araç "tekne" gibi görünüyordu). Tavan -42'ye alındı, kabin daraltıldı.
  var rg = ctx.createLinearGradient(0, -44, 0, -20);
  rg.addColorStop(0, c2); rg.addColorStop(1, _shade(c2, -0.2));
  ctx.fillStyle = rg;
  ctx.beginPath();
  ctx.moveTo(-42, -20); ctx.lineTo(-40, -42); ctx.lineTo(20, -42);
  ctx.quadraticCurveTo(34, -40, 40, -20); ctx.closePath(); ctx.fill();
  // Geniş yan pencere + dik ön cam
  var gg = ctx.createLinearGradient(0, -40, 0, -22);
  gg.addColorStop(0, '#cfe9ff'); gg.addColorStop(0.55, '#5f89a8'); gg.addColorStop(1, '#28394a');
  ctx.fillStyle = gg;
  ctx.beginPath(); ctx.roundRect(-36, -39, 30, 17, 3); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-2, -39); ctx.lineTo(18, -39); ctx.quadraticCurveTo(29, -37, 34, -22); ctx.lineTo(-2, -22); ctx.closePath(); ctx.fill();
  _wCabinHead(ctx, -20, -33, '#ffffff', t);            // sürücü CAMIN İÇİNDE
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  ctx.beginPath(); ctx.moveTo(-34, -37); ctx.lineTo(-24, -37); ctx.lineTo(-31, -24); ctx.lineTo(-34, -24); ctx.closePath(); ctx.fill();
  // ARKA ÜST: batarya/şarj modülü + anten (ayırt edici teknik detay)
  ctx.fillStyle = '#37474f'; ctx.beginPath(); ctx.roundRect(-52, -36, 12, 16, 3); ctx.fill();
  ctx.fillStyle = '#7fe3ff'; ctx.beginPath(); ctx.roundRect(-49, -33, 6, 3, 1); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-49, -28, 6, 3, 1); ctx.fill();
  ctx.strokeStyle = '#546e7a'; ctx.lineWidth = 2; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(-46, -36); ctx.lineTo(-50, -52); ctx.stroke();
  ctx.fillStyle = '#7fe3ff'; ctx.beginPath(); ctx.arc(-50, -53, 2.5, 0, Math.PI * 2); ctx.fill();
  // Elektrik akım işareti (kaput üstü)
  ctx.strokeStyle = 'rgba(255,255,255,0.75)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(6, -16); ctx.lineTo(0, -8); ctx.lineTo(6, -8); ctx.lineTo(0, 0); ctx.stroke();
  // Beyaz-gümüş far
  ctx.save(); ctx.shadowColor = '#e8f6ff'; ctx.shadowBlur = 14; ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.roundRect(44, -12, 9, 5, 2); ctx.fill(); ctx.restore();
  _taillight(ctx, -50, -10, 3.5);
}

// ── 6) Stocker ──────────────────────────────────────────────────────────────
//  Wiki: 70'ler NASCAR stock car; sarı-altın gövde, yuvarlak uzun kaput +
//        fastback arka cam; kapıda MAVİ daire içinde "3A", gövde boyunca mavi
//        şerit; arkada düşük ördek kuyruğu spoiler; MAVİ jant.
function drawStocker(ctx, def, v, thr, t) {
  var c1 = def.color || '#f2c230', c2 = def.color2 || '#1e4fd0';
  var sa = v.suspAnim || [0, 0], wd = def.wheels;
  if (wd) wd.forEach(function (w, i) { var c = sa[i] || 0; _drawSusp(ctx, w.x, 0, w.x, w.y * (1 - c * 0.3), c); });
  // Çamurluk kemeri
  ctx.fillStyle = _shade(c1, -0.45);
  if (wd) wd.forEach(function (w) {
    ctx.beginPath(); ctx.arc(w.x, w.y - 2, w.r + 6, Math.PI, 0);
    ctx.lineTo(w.x + w.r + 6, w.y + 3); ctx.lineTo(w.x - w.r - 6, w.y + 3); ctx.closePath(); ctx.fill();
  });
  // Ana gövde — alçak, uzun, yuvarlak hatlı
  var bg = ctx.createLinearGradient(0, -18, 0, 10);
  bg.addColorStop(0, _shade(c1, 0.4)); bg.addColorStop(0.5, c1); bg.addColorStop(1, _shade(c1, -0.28));
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-64, 8); ctx.lineTo(-66, -8);
  ctx.quadraticCurveTo(-62, -18, -40, -19);
  ctx.lineTo(14, -19); ctx.quadraticCurveTo(56, -17, 66, -4);
  ctx.lineTo(66, 8); ctx.closePath(); ctx.fill();
  // Fastback tavan — arkaya doğru uzun eğim
  var rg = ctx.createLinearGradient(0, -40, 0, -18);
  rg.addColorStop(0, _shade(c1, 0.28)); rg.addColorStop(1, _shade(c1, -0.15));
  ctx.fillStyle = rg;
  ctx.beginPath();
  ctx.moveTo(-52, -18); ctx.quadraticCurveTo(-46, -40, -22, -40);
  ctx.lineTo(6, -40); ctx.quadraticCurveTo(20, -38, 30, -18); ctx.closePath(); ctx.fill();
  // Camlar
  var gg = ctx.createLinearGradient(0, -38, 0, -20);
  gg.addColorStop(0, '#d3ecff'); gg.addColorStop(0.55, '#5b86a8'); gg.addColorStop(1, '#2a3c4d');
  ctx.fillStyle = gg;
  ctx.beginPath(); ctx.moveTo(-48, -20); ctx.lineTo(-40, -37); ctx.lineTo(-16, -37); ctx.lineTo(-16, -20); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-10, -20); ctx.lineTo(-10, -37); ctx.lineTo(4, -37); ctx.quadraticCurveTo(16, -34, 24, -20); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  ctx.beginPath(); ctx.moveTo(-44, -35); ctx.lineTo(-32, -35); ctx.lineTo(-42, -22); ctx.lineTo(-47, -22); ctx.closePath(); ctx.fill();
  // Gövde boyunca MAVİ şerit
  ctx.fillStyle = c2;
  ctx.beginPath(); ctx.roundRect(-64, -6, 128, 6, 2); ctx.fill();
  // Kapıda MAVİ daire içinde "3A"
  ctx.fillStyle = c2; ctx.beginPath(); ctx.arc(-24, -10, 11, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(-24, -10, 8.5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = c2; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('3A', -24, -9);
  ctx.textAlign = 'start'; ctx.textBaseline = 'alphabetic';
  // Düşük ördek kuyruğu spoiler
  ctx.fillStyle = _shade(c1, -0.35);
  ctx.beginPath(); ctx.moveTo(-66, -8); ctx.lineTo(-74, -18); ctx.lineTo(-56, -14); ctx.closePath(); ctx.fill();
  // Egzoz + far
  ctx.fillStyle = '#b8bcc2'; ctx.beginPath(); ctx.roundRect(-70, 2, 10, 5, 2); ctx.fill();
  if (thr > 0.15) _exhaustFlame(ctx, -72, 4, thr, t, 4);
  _wRimRing(ctx, def, '#1e4fd0', 4);
  ctx.save(); ctx.shadowColor = '#fff4c0'; ctx.shadowBlur = 10; ctx.fillStyle = '#fffbdc';
  ctx.beginPath(); ctx.arc(60, -8, 4.5, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  _taillight(ctx, -64, -12, 3.5);
  _wCabinHead(ctx, -30, -28, '#f5f5f5', t);            // sürücü CAMIN İÇİNDE
}

// ── 7) Rock Bouncer ─────────────────────────────────────────────────────────
//  Wiki: açık boru kafesli kaya zıplatıcı; yeşil/lime kafes + yeşil panel;
//        kafes tüm gövdeyi sarıyor, kabin kapalı değil; arkada AÇIKTA motor;
//        önde uzun düşük burun/koruma barı; MAVİ jant çemberi + yeşil göbek.
function drawRockBouncer(ctx, def, v, thr, t) {
  var c1 = def.color || '#7ed321', c2 = def.color2 || '#1f7a1f';
  var sa = v.suspAnim || [0, 0], wd = def.wheels;
  if (wd) wd.forEach(function (w, i) { var c = sa[i] || 0; _drawSusp(ctx, w.x, 2, w.x, w.y * (1 - c * 0.3), c); });
  // Alt şasi kirişi
  ctx.strokeStyle = _shade(c2, -0.35); ctx.lineWidth = 6; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(-48, 10); ctx.lineTo(48, 10); ctx.stroke();
  // Yeşil panel gövde (kafesin içinde, ağırlık merkezi arkada)
  var bg = ctx.createLinearGradient(0, -14, 0, 10);
  bg.addColorStop(0, _shade(c2, 0.5)); bg.addColorStop(1, _shade(c2, -0.25));
  ctx.fillStyle = bg;
  ctx.beginPath(); ctx.roundRect(-44, -14, 76, 24, 4); ctx.fill();
  // ARKADA AÇIKTA MOTOR BLOĞU
  ctx.fillStyle = '#2e2e2e'; ctx.beginPath(); ctx.roundRect(-44, -30, 28, 18, 3); ctx.fill();
  ctx.fillStyle = '#616161'; ctx.beginPath(); ctx.roundRect(-40, -36, 8, 7, 2); ctx.fill();   // hava filtresi
  ctx.strokeStyle = '#6d6d6d'; ctx.lineWidth = 1;
  for (var f = 0; f < 4; f++) { ctx.beginPath(); ctx.moveTo(-41, -26 + f * 4); ctx.lineTo(-20, -26 + f * 4); ctx.stroke(); }
  // Egzoz (yukarı)
  ctx.strokeStyle = '#9aa0a6'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(-22, -30); ctx.lineTo(-18, -46); ctx.stroke();
  if (thr > 0.15) _exhaustFlame(ctx, -18, -48, thr, t, 4);
  // TÜM GÖVDEYİ SARAN LIME BORU KAFES
  ctx.strokeStyle = c1; ctx.lineWidth = 5.5; ctx.lineJoin = 'round';
  ctx.beginPath();
  ctx.moveTo(-48, 10); ctx.lineTo(-50, -34); ctx.lineTo(-24, -48); ctx.lineTo(14, -48);
  ctx.lineTo(34, -30); ctx.lineTo(50, -6); ctx.lineTo(50, 10);
  ctx.stroke();
  ctx.lineWidth = 3.5;
  ctx.beginPath(); ctx.moveTo(-24, -48); ctx.lineTo(-22, -12); ctx.moveTo(14, -48); ctx.lineTo(18, -12); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-50, -20); ctx.lineTo(40, -22); ctx.stroke();
  // ÖNDE UZUN DÜŞÜK BURUN / KORUMA BARI
  ctx.strokeStyle = _shade(c1, -0.15); ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(50, 6); ctx.lineTo(66, 2); ctx.lineTo(66, -8); ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(50, -6); ctx.lineTo(66, -6); ctx.stroke();
  // Koltuk
  ctx.fillStyle = '#1c1c1c'; ctx.beginPath(); ctx.roundRect(-10, -34, 14, 20, 3); ctx.fill();
  // MAVİ jant çemberi + yeşil göbek
  _wRimRing(ctx, def, '#2f7ff5', 4.5);
  ctx.fillStyle = c1;
  (wd || []).forEach(function (w) { ctx.beginPath(); ctx.arc(w.x, w.y, 5, 0, Math.PI * 2); ctx.fill(); });
  _driver(ctx, -3, -40, '#f5f5f5', '#1f7a1f', t);
}

// ── 8) Raider ───────────────────────────────────────────────────────────────
//  Wiki: agresif kırmızı-siyah baja SUV; kısa-YÜKSEK, çok taşkın SİYAH çamurluk
//        kemerleri; siyah tavan + ön cam çerçevesi, eğimli burun; önde kalın
//        siyah tampon + beyaz far çifti; süspansiyon kolları görünür.
function drawRaider(ctx, def, v, thr, t) {
  var c1 = def.color || '#c62828', c2 = def.color2 || '#151515';
  var sa = v.suspAnim || [0, 0], wd = def.wheels;
  // Görünür süspansiyon kolları
  ctx.strokeStyle = '#4a4a4a'; ctx.lineWidth = 4; ctx.lineCap = 'round';
  if (wd) wd.forEach(function (w, i) {
    var c = sa[i] || 0;
    ctx.beginPath(); ctx.moveTo(w.x * 0.3, 4); ctx.lineTo(w.x, w.y * (1 - c * 0.3)); ctx.stroke();
    _drawSusp(ctx, w.x, -4, w.x, w.y * (1 - c * 0.3), c);
  });
  // TAŞKIN SİYAH ÇAMURLUK KEMERLERİ
  // 🔴 PNG kanıtı: ilk sürümde +13 px taşkınlıkla İKİ KEMER BİRLEŞİP aracın alt
  //   yarısını tek siyah lekeye çeviriyordu (kırmızı gövde ayrı bir araç gibi
  //   üstte duruyordu). +7'ye indirildi; kemerler artık ayrı görünüyor.
  ctx.fillStyle = c2;
  if (wd) wd.forEach(function (w) {
    ctx.beginPath(); ctx.arc(w.x, w.y - 3, w.r + 7, Math.PI, 0);
    ctx.lineTo(w.x + w.r + 7, w.y + 2); ctx.lineTo(w.x - w.r - 7, w.y + 2); ctx.closePath(); ctx.fill();
  });
  // Ana gövde — kısa, yüksek, eğimli burun
  var bg = ctx.createLinearGradient(0, -22, 0, 10);
  bg.addColorStop(0, _shade(c1, 0.35)); bg.addColorStop(0.5, c1); bg.addColorStop(1, _shade(c1, -0.35));
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-56, 8); ctx.lineTo(-56, -22); ctx.lineTo(30, -22);
  ctx.quadraticCurveTo(52, -20, 58, -4); ctx.lineTo(58, 8); ctx.closePath(); ctx.fill();
  // Siyah tavan + ön cam çerçevesi
  ctx.fillStyle = c2;
  ctx.beginPath(); ctx.roundRect(-48, -46, 74, 10, [8, 4, 0, 0]); ctx.fill();
  ctx.beginPath(); ctx.moveTo(24, -40); ctx.lineTo(34, -20); ctx.lineTo(26, -20); ctx.lineTo(18, -40); ctx.closePath(); ctx.fill();
  ctx.fillStyle = _shade(c1, -0.15);
  ctx.beginPath(); ctx.roundRect(-48, -38, 74, 18, 3); ctx.fill();
  // Camlar
  var gg = ctx.createLinearGradient(0, -38, 0, -20);
  gg.addColorStop(0, '#cfe9ff'); gg.addColorStop(0.55, '#557b99'); gg.addColorStop(1, '#233240');
  ctx.fillStyle = gg;
  ctx.beginPath(); ctx.roundRect(-44, -36, 28, 15, 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-12, -36); ctx.lineTo(16, -36); ctx.lineTo(24, -21); ctx.lineTo(-12, -21); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.28)';
  ctx.beginPath(); ctx.moveTo(-42, -34); ctx.lineTo(-32, -34); ctx.lineTo(-39, -23); ctx.lineTo(-43, -23); ctx.closePath(); ctx.fill();
  // Yan koruma çubuğu
  ctx.strokeStyle = c2; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(-30, 4); ctx.lineTo(24, 4); ctx.stroke();
  // KALIN SİYAH ÖN TAMPON
  ctx.fillStyle = c2; ctx.beginPath(); ctx.roundRect(52, -6, 14, 16, 3); ctx.fill();
  ctx.strokeStyle = '#3a3a3a'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(60, -6); ctx.lineTo(60, -18); ctx.stroke();
  // BEYAZ FAR ÇİFTİ
  ctx.save(); ctx.shadowColor = '#ffffff'; ctx.shadowBlur = 13; ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(48, -14, 4.5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(48, -3, 4, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  _taillight(ctx, -54, -12, 4);
  _wCabinHead(ctx, -30, -30, '#e8e8e8', t);            // sürücü CAMIN İÇİNDE
}

// ── 9) Bolt ─────────────────────────────────────────────────────────────────
//  Wiki: klasik (1930-50) Grand Prix; sarı-turuncu "puro" gövde, ÇOK uzun ve
//        ÇOK ince; açık kokpit ortada-arkada (kask + küçük rüzgâr siperi);
//        kaputta uzunlamasına hava alma sırtı; AÇIK TEKERLEK (çamurluk YOK),
//        ön küçük/ince, arka belirgin daha büyük; sarı/krem telli jant.
function drawBolt(ctx, def, v, thr, t) {
  var c1 = def.color || '#f0b429', c2 = def.color2 || '#8a5a12';
  // Açık tekerlek: ÇAMURLUK ÇİZİLMEZ, gövde dar tutulur.
  // İnce "puro" gövde
  var bg = ctx.createLinearGradient(0, -14, 0, 6);
  bg.addColorStop(0, _shade(c1, 0.5)); bg.addColorStop(0.45, c1); bg.addColorStop(1, _shade(c2, -0.1));
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-62, 0);
  ctx.quadraticCurveTo(-66, -8, -54, -11);
  ctx.lineTo(24, -13);
  ctx.quadraticCurveTo(60, -12, 70, -2);
  ctx.quadraticCurveTo(60, 5, 24, 6);
  ctx.lineTo(-54, 5);
  ctx.closePath(); ctx.fill();
  // Uzunlamasına hava alma sırtı (kaput üstü)
  ctx.fillStyle = _shade(c2, 0.15);
  ctx.beginPath(); ctx.moveTo(18, -13); ctx.quadraticCurveTo(46, -18, 62, -6); ctx.lineTo(46, -8); ctx.quadraticCurveTo(34, -13, 18, -13); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = _shade(c1, 0.6); ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(-46, -9); ctx.lineTo(20, -11); ctx.stroke();
  // Yan egzoz borusu (klasik GP detayı)
  var eg = ctx.createLinearGradient(0, -4, 0, 2); eg.addColorStop(0, '#efefef'); eg.addColorStop(1, '#7d8188');
  ctx.strokeStyle = eg; ctx.lineWidth = 3.5; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(30, -2); ctx.lineTo(-56, 1); ctx.stroke();
  // Açık kokpit — ortada-arkada
  ctx.fillStyle = '#20180c';
  ctx.beginPath(); ctx.roundRect(-34, -18, 26, 8, 4); ctx.fill();
  // Küçük rüzgâr siperi
  ctx.fillStyle = 'rgba(210,235,250,0.65)';
  ctx.beginPath(); ctx.moveTo(-6, -14); ctx.quadraticCurveTo(-2, -24, -12, -24); ctx.lineTo(-12, -14); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#c8ccd2'; ctx.lineWidth = 1.5; ctx.stroke();
  // Yarış numarası dairesi
  ctx.fillStyle = '#f7f3e6'; ctx.beginPath(); ctx.arc(-46, -4, 8, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#2a2a2a'; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('7', -46, -3);
  ctx.textAlign = 'start'; ctx.textBaseline = 'alphabetic';
  // Krem telli jant vurgusu (açık tekerlek)
  _wRimRing(ctx, def, '#efe3b8', 3.5);
  var wd = def.wheels || [];
  ctx.strokeStyle = 'rgba(240,232,190,0.75)'; ctx.lineWidth = 1;
  for (var i = 0; i < wd.length; i++) {
    for (var s = 0; s < 8; s++) {
      var a = s * Math.PI / 4;
      ctx.beginPath(); ctx.moveTo(wd[i].x, wd[i].y);
      ctx.lineTo(wd[i].x + Math.cos(a) * wd[i].r * 0.55, wd[i].y + Math.sin(a) * wd[i].r * 0.55); ctx.stroke();
    }
  }
  if (thr > 0.2) _exhaustFlame(ctx, -58, 1, thr, t, 4);
  _driver(ctx, -24, -24, '#f7f3e6', '#8a5a12', t);
}

// ── 10) Doughnut ────────────────────────────────────────────────────────────
//  Wiki: simit/donut biçimli araç; kırmızı-koyu kırmızı geniş OVAL halka (torus)
//        gövde, üstte siyah oturma/tutunma yüzeyi; GÖRÜNÜR TEKERLEK YOK —
//        gövdenin kendisi yuvarlanıyor.
function drawDoughnut(ctx, def, v, thr, t) {
  var c1 = def.color || '#e2402f', c2 = def.color2 || '#1b1b1b';
  var spin = (v.wheels && v.wheels[0] ? v.wheels[0].spin : 0) || 0;
  // Torus gövde — dış halka
  ctx.save();
  ctx.translate(0, 18);
  var rg = ctx.createRadialGradient(-10, -12, 6, 0, 0, 46);
  rg.addColorStop(0, _shade(c1, 0.5)); rg.addColorStop(0.6, c1); rg.addColorStop(1, _shade(c1, -0.4));
  ctx.fillStyle = rg;
  ctx.beginPath(); ctx.arc(0, 0, 44, 0, Math.PI * 2); ctx.fill();
  // İç delik
  ctx.globalCompositeOperation = 'destination-out';
  ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI * 2); ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  // Hamur kenarı
  ctx.strokeStyle = _shade(c1, -0.45); ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(0, 0, 43, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(0, 0, 16, 0, Math.PI * 2); ctx.stroke();
  // Üstte siyah oturma/tutunma yüzeyi (halkanın üst yarısı) — döner
  ctx.save(); ctx.rotate(spin);
  ctx.strokeStyle = c2; ctx.lineWidth = 13;
  ctx.beginPath(); ctx.arc(0, 0, 30, Math.PI * 1.12, Math.PI * 1.88); ctx.stroke();
  ctx.strokeStyle = _shade(c2, 0.35); ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(0, 0, 30, Math.PI * 1.12, Math.PI * 1.88); ctx.stroke();
  // Serpme (sprinkle) — halkayla birlikte döner
  var renk = ['#ffe14a', '#7fe3ff', '#ffffff', '#7ef58a', '#ff8ad0'];
  for (var s = 0; s < 14; s++) {
    var a = spin * 0 + s * (Math.PI * 2 / 14);
    var rr = 24 + (s % 3) * 6;
    ctx.save();
    ctx.translate(Math.cos(a) * rr, Math.sin(a) * rr);
    ctx.rotate(a + 0.7);
    ctx.fillStyle = renk[s % renk.length];
    ctx.beginPath(); ctx.roundRect(-4, -1.4, 8, 2.8, 1.4); ctx.fill();
    ctx.restore();
  }
  ctx.restore();
  // Parlaklık
  ctx.fillStyle = 'rgba(255,255,255,0.22)';
  _wEllipse(ctx, -14, -26, 15, 6); ctx.fill();
  ctx.restore();
  _driver(ctx, 0, -20, '#ff8ad0', '#7a1c14', t);
}

// ── 11) Snowboard ───────────────────────────────────────────────────────────
//  Wiki: uzun ince yeşil-lime tahta, iki ucu hafif YUKARI kıvrık; üstte iki adet
//        SİYAH bağlama (binding) kutusu yan yana; alt kenarda koyu kayak yüzeyi.
function drawSnowboard(ctx, def, v, thr, t) {
  var c1 = def.color || '#7ed321', c2 = def.color2 || '#1b3b12';
  var bg = ctx.createLinearGradient(-60, 0, 60, 0);
  bg.addColorStop(0, _shade(c1, -0.2)); bg.addColorStop(0.5, _shade(c1, 0.3)); bg.addColorStop(1, _shade(c1, -0.2));
  ctx.fillStyle = bg;
  // Tahta — iki ucu kıvrık
  ctx.beginPath();
  ctx.moveTo(-58, 4);
  ctx.quadraticCurveTo(-66, 0, -62, -6);
  ctx.quadraticCurveTo(-30, -2, 0, -2);
  ctx.quadraticCurveTo(30, -2, 62, -6);
  ctx.quadraticCurveTo(66, 0, 58, 4);
  ctx.quadraticCurveTo(0, 8, -58, 4);
  ctx.closePath(); ctx.fill();
  // Üst yüzey deseni
  ctx.strokeStyle = _shade(c2, 0.4); ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(-50, 0); ctx.lineTo(50, 0); ctx.stroke();
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  ctx.beginPath(); ctx.moveTo(-40, -1); ctx.lineTo(20, -1); ctx.lineTo(14, 1); ctx.lineTo(-44, 1); ctx.closePath(); ctx.fill();
  // Alt kenar — koyu kayak yüzeyi
  ctx.fillStyle = c2;
  ctx.beginPath();
  ctx.moveTo(-58, 4); ctx.quadraticCurveTo(0, 8, 58, 4);
  ctx.quadraticCurveTo(0, 10, -58, 4); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#cfe6f5'; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(-56, 6); ctx.quadraticCurveTo(0, 9, 56, 6); ctx.stroke();
  // İKİ SİYAH BAĞLAMA (binding)
  ctx.fillStyle = '#141414';
  ctx.beginPath(); ctx.roundRect(-26, -12, 18, 11, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(8, -12, 18, 11, 3); ctx.fill();
  ctx.strokeStyle = '#4a4a4a'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(-24, -9); ctx.lineTo(-10, -9); ctx.moveTo(10, -9); ctx.lineTo(24, -9); ctx.stroke();
  ctx.fillStyle = '#2e2e2e';
  ctx.beginPath(); ctx.roundRect(-27, -18, 5, 7, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(22, -18, 5, 7, 2); ctx.fill();
  _driver(ctx, -2, -22, '#7ed321', '#1b3b12', t);
}

// ── 12) Beast ───────────────────────────────────────────────────────────────
//  Wiki: uzun, iskeletimsi off-road şasi; parlak mavi/açık mavi boru ve paneller;
//        ARKADA yüksek turuncu-kahve AHŞAP KARGO KASASI (çemberli fıçı); önde
//        uzun ince eğimli burun (ok gibi); sürücü koltuğu ortada açıkta;
//        arkada büyük dişli lastik, önde daha küçük teker; üçgen silüet.
function drawBeast(ctx, def, v, thr, t) {
  var c1 = def.color || '#2f8fd6', c2 = def.color2 || '#1a5c8f';
  var sa = v.suspAnim || [0, 0], wd = def.wheels;
  if (wd) wd.forEach(function (w, i) { var c = sa[i] || 0; _drawSusp(ctx, w.x, 2, w.x, w.y * (1 - c * 0.3), c); });
  // İskelet şasi boruları — ön alçak, arka yüksek (üçgen silüet)
  ctx.strokeStyle = c1; ctx.lineWidth = 6; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(72, 4); ctx.lineTo(10, -6); ctx.lineTo(-30, -30); ctx.lineTo(-64, -30);
  ctx.moveTo(-64, 10); ctx.lineTo(66, 6);
  ctx.stroke();
  ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(-30, 10); ctx.moveTo(10, -6); ctx.lineTo(10, 8); ctx.stroke();
  // Mavi gövde panelleri (orta bölüm)
  var bg = ctx.createLinearGradient(0, -18, 0, 8);
  bg.addColorStop(0, _shade(c1, 0.4)); bg.addColorStop(1, c2);
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-32, -26); ctx.lineTo(16, -10); ctx.lineTo(16, 6); ctx.lineTo(-32, 8); ctx.closePath(); ctx.fill();
  // ÖNDE UZUN İNCE EĞİMLİ BURUN (ok gibi)
  ctx.fillStyle = _shade(c1, 0.15);
  ctx.beginPath(); ctx.moveTo(16, -8); ctx.lineTo(78, 2); ctx.lineTo(78, 8); ctx.lineTo(16, 8); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = _shade(c1, 0.55); ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(20, -6); ctx.lineTo(74, 3); ctx.stroke();
  // ARKADA YÜKSEK AHŞAP KARGO KASASI (çemberli fıçı)
  var wg = ctx.createLinearGradient(0, -52, 0, -12);
  wg.addColorStop(0, '#d4913f'); wg.addColorStop(0.5, '#a8672a'); wg.addColorStop(1, '#6f4118');
  ctx.fillStyle = wg;
  ctx.beginPath(); ctx.roundRect(-70, -52, 44, 42, 7); ctx.fill();
  ctx.strokeStyle = '#5a3512'; ctx.lineWidth = 1.2;
  for (var p = -66; p < -28; p += 8) { ctx.beginPath(); ctx.moveTo(p, -51); ctx.lineTo(p, -11); ctx.stroke(); }
  // Metal çemberler
  var hg = ctx.createLinearGradient(0, -46, 0, -40); hg.addColorStop(0, '#d8dce2'); hg.addColorStop(1, '#7c8188');
  ctx.fillStyle = hg;
  ctx.beginPath(); ctx.roundRect(-71, -46, 46, 6, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-71, -24, 46, 6, 2); ctx.fill();
  // Sürücü koltuğu ORTADA AÇIKTA
  ctx.fillStyle = '#1a1a1a'; ctx.beginPath(); ctx.roundRect(-24, -34, 15, 22, 3); ctx.fill();
  // Direksiyon
  ctx.strokeStyle = '#3a3a3a'; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.arc(2, -20, 6, 0, Math.PI * 2); ctx.stroke();
  // Egzoz
  ctx.strokeStyle = '#9aa0a6'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(-20, -12); ctx.lineTo(-16, -38); ctx.stroke();
  if (thr > 0.15) _exhaustFlame(ctx, -16, -40, thr, t, 5);
  // Gri jant
  _wRimRing(ctx, def, '#9aa0a6', 4);
  ctx.save(); ctx.shadowColor = '#fff6c8'; ctx.shadowBlur = 10; ctx.fillStyle = '#fffbe0';
  ctx.beginPath(); ctx.arc(72, 0, 4, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  _driver(ctx, -16, -40, '#ffd54a', '#1a5c8f', t);
}

// ── 13) Glider ──────────────────────────────────────────────────────────────
//  Wiki: ev yapımı hafif uçak/ultralight; beyaz-krem gövde, turuncu burun ve
//        kanat ucu vurguları; ÜSTTE uzun düz KANAT (gövde boyundan geniş);
//        altta ince boru gövde; arkada dikey + yatay kuyruk; 3 KÜÇÜK KIRMIZI
//        teker (önde 1, altta 2); açık koltuk kanadın altında.
function drawGlider(ctx, def, v, thr, t) {
  var c1 = def.color || '#f2efe6', c2 = def.color2 || '#e8722a';
  var salin = Math.sin(t * 1.8) * 1.5;
  var wd = def.wheels || [];
  // ── İniş takımı: ince bacaklar (tekerler drawVehicle'da çizildi) ──
  ctx.strokeStyle = '#8b9098'; ctx.lineWidth = 2.5; ctx.lineCap = 'round';
  for (var i = 0; i < wd.length; i++) {
    ctx.beginPath(); ctx.moveTo(wd[i].x * 0.75, 4); ctx.lineTo(wd[i].x, wd[i].y - 6); ctx.stroke();
  }
  ctx.strokeStyle = '#b6bcc4'; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(-46, 16); ctx.lineTo(18, 18); ctx.stroke();     // ana bacak kirişi
  // ── Kuyruk konisi: gövde arkaya doğru İNCELİR (düz bar DEĞİL) ──
  var bg = ctx.createLinearGradient(0, -14, 0, 10);
  bg.addColorStop(0, '#ffffff'); bg.addColorStop(0.45, c1); bg.addColorStop(1, _shade(c1, -0.32));
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-70, -4);                                  // kuyruk ucu (ince)
  ctx.quadraticCurveTo(-40, -12, -6, -16);              // üst hat
  ctx.quadraticCurveTo(34, -18, 56, -10);
  ctx.quadraticCurveTo(66, -6, 66, 0);
  ctx.quadraticCurveTo(66, 7, 54, 9);                   // burun altı
  ctx.quadraticCurveTo(20, 12, -12, 8);
  ctx.quadraticCurveTo(-44, 4, -70, -1);
  ctx.closePath(); ctx.fill();
  // Gövde kaplama dikişleri
  ctx.strokeStyle = 'rgba(140,148,158,0.45)'; ctx.lineWidth = 1;
  for (var d = -56; d < 46; d += 14) { ctx.beginPath(); ctx.moveTo(d, -13); ctx.lineTo(d, 7); ctx.stroke(); }
  // ── DİKEY KUYRUK (belirgin üçgen) + YATAY DENGELEYİCİ ──
  ctx.fillStyle = c1;
  ctx.beginPath(); ctx.moveTo(-52, -12); ctx.lineTo(-76, -40); ctx.lineTo(-62, -40);
  ctx.lineTo(-44, -14); ctx.closePath(); ctx.fill();
  ctx.fillStyle = c2;
  ctx.beginPath(); ctx.moveTo(-76, -40); ctx.lineTo(-62, -40); ctx.lineTo(-64, -32); ctx.lineTo(-74, -32); ctx.closePath(); ctx.fill();
  ctx.fillStyle = _shade(c1, -0.12);
  ctx.beginPath(); ctx.roundRect(-84, -10, 30, 5, 2); ctx.fill();      // yatay kuyruk
  ctx.fillStyle = c2;
  ctx.beginPath(); ctx.roundRect(-84, -10, 11, 5, [2, 0, 0, 2]); ctx.fill();
  // ── TURUNCU BURUN + PERVANE ──
  ctx.fillStyle = c2;
  ctx.beginPath();
  ctx.moveTo(48, -12); ctx.quadraticCurveTo(68, -8, 68, 0);
  ctx.quadraticCurveTo(68, 8, 50, 10); ctx.lineTo(48, 10); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.28)';
  ctx.beginPath(); ctx.moveTo(52, -9); ctx.quadraticCurveTo(64, -6, 64, -2); ctx.lineTo(52, -4); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#6b7078'; ctx.lineWidth = 2.5;
  var pv = (t * 22) % (Math.PI * 2);
  ctx.beginPath(); ctx.moveTo(70, -Math.cos(pv) * 17 - 1); ctx.lineTo(70, Math.cos(pv) * 17 - 1); ctx.stroke();
  ctx.fillStyle = '#3a3f45'; ctx.beginPath(); ctx.arc(70, -1, 3.2, 0, Math.PI * 2); ctx.fill();
  // ── AÇIK KOLTUK (kanadın altında, gövdenin üstünde) ──
  ctx.fillStyle = '#2b2f36'; ctx.beginPath(); ctx.roundRect(-8, -26, 16, 14, 3); ctx.fill();
  _wCabinHead(ctx, 0, -28, c2, t);
  ctx.strokeStyle = '#7a8088'; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(14, -14); ctx.lineTo(16, -24); ctx.stroke();     // kumanda kolu
  // ── ÜSTTE UZUN DÜZ KANAT (gövde boyundan geniş) + direkler ──
  ctx.save(); ctx.translate(0, salin);
  ctx.strokeStyle = '#9aa0a6'; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(-24, -32); ctx.lineTo(-14, -14); ctx.moveTo(24, -32); ctx.lineTo(14, -14); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(0, -32); ctx.lineTo(0, -26); ctx.stroke();
  var kg = ctx.createLinearGradient(0, -40, 0, -31);
  kg.addColorStop(0, '#ffffff'); kg.addColorStop(1, _shade(c1, -0.26));
  ctx.fillStyle = kg;
  ctx.beginPath(); ctx.roundRect(-76, -40, 152, 9, 4); ctx.fill();
  ctx.fillStyle = c2;                                          // turuncu kanat ucu vurguları
  ctx.beginPath(); ctx.roundRect(-76, -40, 18, 9, [4, 0, 0, 4]); ctx.fill();
  ctx.beginPath(); ctx.roundRect(58, -40, 18, 9, [0, 4, 4, 0]); ctx.fill();
  ctx.strokeStyle = 'rgba(120,130,140,0.5)'; ctx.lineWidth = 1;
  for (var r = -64; r <= 64; r += 16) { ctx.beginPath(); ctx.moveTo(r, -39); ctx.lineTo(r, -32); ctx.stroke(); }
  ctx.fillStyle = 'rgba(255,255,255,0.35)';                    // kanat üstü parlama
  ctx.beginPath(); ctx.roundRect(-70, -39, 140, 2.5, 1.2); ctx.fill();
  ctx.restore();
}

// ── 14) Sled ────────────────────────────────────────────────────────────────
//  Wiki: basit kızak; turkuaz düz taban, ön uç YUKARI kıvrık (kızak burnu),
//        arka uçta küçük kalkık kenar; üst yüzeyde açık renkli ince şerit;
//        sürücü, motor, tekerlek YOK. Neredeyse iki boyutlu bir şerit.
function drawSled(ctx, def, v, thr, t) {
  var c1 = def.color || '#20c6c6', c2 = def.color2 || '#0e7d7d';
  // Düz taban + öne kıvrık burun
  var bg = ctx.createLinearGradient(0, -8, 0, 6);
  bg.addColorStop(0, _shade(c1, 0.42)); bg.addColorStop(0.55, c1); bg.addColorStop(1, c2);
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.moveTo(-60, 0);
  ctx.lineTo(-62, -8);                                  // arka uçtaki küçük kalkık kenar
  ctx.lineTo(-54, -8);
  ctx.lineTo(-52, -1);
  ctx.lineTo(48, -1);
  ctx.quadraticCurveTo(66, -2, 68, -14);                // ön uç yukarı kıvrık (kızak burnu)
  ctx.quadraticCurveTo(74, -12, 72, -2);
  ctx.quadraticCurveTo(70, 5, 52, 5);
  ctx.lineTo(-58, 5);
  ctx.closePath(); ctx.fill();
  // Üst yüzeyde açık renkli ince şerit
  ctx.fillStyle = _shade(c1, 0.55);
  ctx.beginPath(); ctx.roundRect(-48, 0.4, 96, 2, 1); ctx.fill();
  // Alt kayma yüzeyi (koyu)
  ctx.fillStyle = _shade(c2, -0.35);
  ctx.beginPath();
  ctx.moveTo(-58, 5); ctx.lineTo(52, 5); ctx.quadraticCurveTo(64, 5, 68, 1);
  ctx.quadraticCurveTo(66, 8, 50, 8); ctx.lineTo(-58, 8); ctx.closePath(); ctx.fill();
  // Kar parlaması
  ctx.strokeStyle = 'rgba(255,255,255,0.55)'; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(-44, -0.2); ctx.lineTo(30, -0.2); ctx.stroke();
  // Tutma ipi (kızak burnundan)
  ctx.strokeStyle = '#c8b48a'; ctx.lineWidth = 1.6; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(68, -12); ctx.quadraticCurveTo(52, -20, 30, -14); ctx.stroke();
  _driver(ctx, -4, -12, '#ffffff', '#0e7d7d', t);
}
